window.EXAM_DATA=[{"subject": "A", "year": "111", "num": 1, "type": "單選", "rate": "29%", "img": "img/111_q01.png", "answer": [{"t": "(4)　120"}], "key": "先由「兩球不同口味 C(n,2)>100」定出 n=15；「可同口味」是重複組合。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}, {"unit": "排列組合與機率", "title": "考點1 計數原理與排列（有順序）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "「兩球不同口味的組合數 C(n,2)>100」→ n(n−1)/2>100 → n(n−1)>200，最小 n=15（15×14=210）。"}, {"type": "text", "c": "顧客任選兩球「可同一口味」＝重複組合 = C(n+1, 2)："}, {"type": "math", "c": "\\binom{15+1}{2}=\\dfrac{15\\times16}{2}=120"}, {"type": "text", "c": "故選 (4)。"}]}, {"subject": "A", "year": "111", "num": 2, "type": "單選", "rate": "40%", "img": "img/111_q02.png", "answer": [{"t": "(1)　"}, {"m": "a^2=b^3"}], "key": "設 x=log_a b，誤按得到 log_b a = 1/x；由 1/x =(9/4)x 解 x。", "kaodian": [{"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "../concept-map/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "設 x=log_a b（正確值）。順序弄錯按成 log_b a = 1/x。題意「誤值 = 正確值的 9/4 倍」："}, {"type": "math", "c": "\\dfrac{1}{x}=\\dfrac{9}{4}x\\Rightarrow x^2=\\dfrac{4}{9}\\Rightarrow x=\\dfrac23\\ (\\because a,b>1)"}, {"type": "text", "c": "即 log_a b=2/3 → b=a^(2/3) → a²=b³。選 (1)。"}]}, {"subject": "A", "year": "111", "num": 3, "type": "單選", "rate": "12%", "img": "img/111_q03.png", "answer": [{"t": "(5)　"}, {"m": "y=-\\tfrac{x}{2}"}], "key": "投影後變異最小 ＝ 投影到與「資料散布最大方向（主軸）」垂直的直線。", "kaodian": [{"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "../concept-map/115學測數學_數據分析.html#kp3"}, {"unit": "數據分析", "title": "考點2 相關係數 r", "url": "../concept-map/115學測數學_數據分析.html#kp2"}], "steps": [{"type": "text", "c": "資料主要沿一條斜率約 2 的直線分布（正相關）。把資料垂直投影到某直線上，投影點的變異在「與散布最大方向垂直」時最小。"}, {"type": "text", "c": "主軸斜率≈2，垂直方向斜率 = −1/2，故投影到 y=−x/2 變異最小。選 (5)。（見右圖）"}], "fig": "img/111_fig_q03.png"}, {"subject": "A", "year": "111", "num": 4, "type": "單選", "rate": "57%", "img": "img/111_q04.png", "answer": [{"t": "(3)　"}, {"m": "\\log\\tfrac32"}], "key": "log a1,log a3,log a6 等差 → a3²=a1·a6，解出 a1=4d。", "kaodian": [{"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "../concept-map/115學測數學_數列與級數.html#kp1"}, {"unit": "指數與對數", "title": "考點5 指對數的應用：成長衰退模型與數列", "url": "../concept-map/115學測數學_指數與對數.html#kp5"}], "steps": [{"type": "text", "c": "log 成等差 → 2log a3 = log a1 + log a6 → a3² = a1·a6。代 a3=a1+2d、a6=a1+5d："}, {"type": "math", "c": "(a_1+2d)^2=a_1(a_1+5d)\\Rightarrow 4d^2=a_1 d\\Rightarrow a_1=4d"}, {"type": "text", "c": "則 a1=4d、a3=6d、a6=9d，公差 = log a3 − log a1 = log(6d/4d)=log(3/2)。選 (3)。"}]}, {"subject": "A", "year": "111", "num": 5, "type": "單選", "rate": "53%", "img": "img/111_q05.png", "answer": [{"t": "(2)　8"}], "key": "貝氏定理分別算「單次判陰」與「三次皆陰」中的染病機率，再相除。", "kaodian": [{"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "../concept-map/115學測數學_排列組合與機率.html#kp4"}, {"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "../concept-map/115學測數學_排列組合與機率.html#kp5"}], "steps": [{"type": "text", "c": "P(染)=0.3、P(陰|染)=0.2、P(陰|未)=0.6。單次判陰中染病："}, {"type": "math", "c": "P=\\dfrac{0.3\\times0.2}{0.3\\times0.2+0.7\\times0.6}=\\dfrac{0.06}{0.48}=\\dfrac18"}, {"type": "text", "c": "三次皆判陰中染病："}, {"type": "math", "c": "P\\,'=\\dfrac{0.3\\times0.2^3}{0.3\\times0.2^3+0.7\\times0.6^3}=\\dfrac{0.0024}{0.1536}=\\dfrac{1}{64}"}, {"type": "math", "c": "\\dfrac{P}{P\\,'}=\\dfrac{1/8}{1/64}=8"}, {"type": "text", "c": "故選 (2)。"}]}, {"subject": "A", "year": "111", "num": 6, "type": "單選", "rate": "48%", "img": "img/111_q06.png", "answer": [{"t": "(5)　"}, {"m": "27x+33y=65"}], "key": "正三角形中，兩邊夾角的平分線是對稱軸，第三邊垂直於它。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "正三角形中，L1、L2 夾角的平分線是對稱軸，第三邊 L 垂直於此平分線。平分線斜率 11/9 → L 斜率 = −9/11。"}, {"type": "text", "c": "L 過 (2, 1/3) 斜率 −9/11："}, {"type": "math", "c": "y-\\tfrac13=-\\tfrac{9}{11}(x-2)\\Rightarrow 27x+33y=65"}, {"type": "text", "c": "故選 (5)。"}]}, {"subject": "A", "year": "111", "num": 7, "type": "多選", "rate": "57%（全對率 37%）", "img": "img/111_q07.png", "answer": [{"t": "(2)(4)"}], "key": "兩非負數比大小可平方；|5n−21|≥7|n| 等價於 (5n−21)²≥49n²。", "kaodian": [{"unit": "數與式", "title": "考點2 絕對值的意義、方程式與不等式", "url": "../concept-map/115學測數學_數與式.html#kp2"}, {"unit": "多項式函數", "title": "考點3 多項式方程式與不等式的解法", "url": "../concept-map/115學測數學_多項式函數.html#kp3"}], "steps": [{"type": "text", "c": "兩邊非負，平方後等價：|5n−21|≥7|n| 就是 (5n−21)²≥49n²，(4) 對；也等價於 |7n/(5n−21)|≤1，即 (2) 對。"}, {"type": "math", "c": "(5n-21)^2\\ge 49n^2\\Rightarrow 24n^2+210n-441\\le0\\Rightarrow -10.5\\le n\\le 1.75"}, {"type": "text", "c": "整數 n∈{−10, …, 1} 共 12 個（有限），(5) 錯。(1)(3) 非等價變形，錯。選 (2)(4)。"}]}, {"subject": "A", "year": "111", "num": 8, "type": "多選", "rate": "60%（全對率 39%）", "img": "img/111_q08.png", "answer": [{"t": "(1)(4)"}], "key": "先算三邊長，用餘弦定理判斷角，用正弦定理算外接圓半徑。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "../concept-map/115學測數學_三角.html#kp2"}, {"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "../concept-map/115學測數學_直線與圓.html#kp2"}], "steps": [{"type": "text", "c": "AB=√5、BC=√10、AC=√17。(1) AC 最長，對。(3) AB²+BC²−AC²=−2<0 → 角B 為鈍角，非銳角三角形，錯。"}, {"type": "math", "c": "(4)\\ \\cos B=\\dfrac{5+10-17}{2\\sqrt5\\sqrt{10}}=-\\dfrac{\\sqrt2}{10}\\Rightarrow \\sin B=\\dfrac{7\\sqrt2}{10}\\ (\\text{對})"}, {"type": "text", "c": "(2) 大邊對大角：BC>AB → 角A>角C → sin A>sin C，「sin A<sin C」錯。(5) 2R=AC/sinB=5√34/7，R≈2.08>2，錯。選 (1)(4)。"}]}, {"subject": "A", "year": "111", "num": 9, "type": "多選", "rate": "19%（全對率 4%）", "img": "img/111_q09.png", "answer": [{"t": "(3)(4)"}], "key": "用向量係數表示各點；三角形面積、到某邊距離只看對應的分量。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}], "steps": [{"type": "text", "c": "P 在△內 → a,b>0、a+b<1。AQ=(b,a)（係數對調）、AR=(a, b−0.05)。"}, {"type": "text", "c": "(3) △ABP=(b/2)|AB×AC|、△ACQ=(b/2)|AB×AC|，相等，對。(4) P、Q 到 BC 的距離都比例於 1−a−b（對調不變），△BCP=△BCQ，對。"}, {"type": "text", "c": "(1) R 可能 b−0.05<0 跑到△外，錯。(2) |AP|=|AQ| 需 |AB|=|AC|，不一定，錯。(5) △ABP>△ABR 需 b>|b−0.05|，b 很小時不成立，錯。選 (3)(4)。"}]}, {"subject": "A", "year": "111", "num": 10, "type": "多選", "rate": "20%（全對率 3%）", "img": "img/111_q10.png", "answer": [{"t": "(1)(2)"}], "key": "g=f(−x)−3；由對稱中心 (1,0)、g(−1)<0 定出 b=3a、c=2a、a<0。", "kaodian": [{"unit": "多項式函數", "title": "考點5 三次函數圖形與對稱中心", "url": "../concept-map/115學測數學_多項式函數.html#kp5"}, {"unit": "多項式函數", "title": "考點4 高次方程式：有理根、勘根定理與奇偶函數", "url": "../concept-map/115學測數學_多項式函數.html#kp4"}], "steps": [{"type": "text", "c": "g(x)=f(−x)−3=−ax³+bx²−cx。對稱中心 x=b/(3a)=1 → b=3a；g(1)=0 → c=2a；g(−1)=6a<0 → a<0。"}, {"type": "text", "c": "(1) g(x)=−a·x(x−1)(x−2)，三整數根 0,1,2，對。(2) a<0，對。(3) f 的對稱中心是 (−1, 3) 不是 (−1,−3)，錯。"}, {"type": "math", "c": "(4)\\ f(100)=1030200a+3;\\ a\\to0^-\\ \\text{時}\\ f(100)>0,\\ \\text{不一定}<0\\ (\\text{錯})"}, {"type": "text", "c": "(5) 令 u=x+1 移到對稱中心，展開得 f=au³−au+3；中心附近 u 很小、au³ 可忽略，近似直線 f≈−au+3，斜率是 −a 不是 a，錯。選 (1)(2)。"}]}, {"subject": "A", "year": "111", "num": 11, "type": "多選", "rate": "38%（全對率 16%）", "img": "img/111_q11.png", "answer": [{"t": "(2)(3)(4)"}], "key": "兩矩形共邊 AD ⊥ 兩邊 → AD⊥底面，是三角柱；設坐標逐一算角。", "kaodian": [{"unit": "空間向量", "title": "考點6 二面角與立體（摺疊問題）", "url": "../concept-map/115學測數學_空間向量.html#kp6"}, {"unit": "三角", "title": "考點7 圓周角與二面角中的三角", "url": "../concept-map/115學測數學_三角.html#kp7"}], "steps": [{"type": "text", "c": "ADEB、ADFC 皆矩形 → AD⊥AB 且 AD⊥AC → AD⊥底面 ABC（三角柱）。設 A=(0,0,0)、B=(5,6,0)、C=(5,0,0)、D=(0,0,h)、E=(5,6,h)、F=(5,0,h)。"}, {"type": "text", "c": "(1) 沿平面 ACE 切 → 得「四面體 ABCE」＋「四角錐 E–ADFC」，不是兩個四面體，錯。"}, {"type": "text", "c": "(2) 兩矩形沿 AD 的夾角 = ∠BAC，cos∠BAC=5/√61 → ≈50°>45°，對。"}, {"type": "math", "c": "(3)\\ \\cos\\angle CEB=\\dfrac{h}{\\sqrt{36+h^2}}>\\cos\\angle AEB=\\dfrac{h}{\\sqrt{61+h^2}}\\Rightarrow \\angle CEB<\\angle AEB\\ (\\text{對})"}, {"type": "text", "c": "(4) 對各種 h 檢驗，tan∠AEC < sin∠CEB 皆成立，對。(5) ∠CEB>∠AEC，錯。選 (2)(3)(4)。"}]}, {"subject": "A", "year": "111", "num": 12, "type": "多選", "rate": "21%（全對率 9%）", "img": "img/111_q12.png", "answer": [{"t": "(1)(2)"}], "key": "(g)²除 f 餘 g → g(g−1)=f·q；用 f 無實根與次數限制推出頂點值範圍。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "../concept-map/115學測數學_多項式函數.html#kp1"}, {"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "../concept-map/115學測數學_多項式函數.html#kp2"}], "steps": [{"type": "text", "c": "(g)²=f·q+g → g(g−1)=f·q。餘式次數 2 < deg f，故 deg f≥3。"}, {"type": "text", "c": "若 deg f=3（奇數）必有實根，與「f 無實根」矛盾 → deg f=4，f = g(g−1)/常數。"}, {"type": "text", "c": "「f 無實根」等於「g=0、g=1 皆無解」，也就是 g 的最小值（頂點 y 坐標）大於 1。"}, {"type": "text", "c": "故頂點 y 必 >1。不可能的值 = ≤1 者，即 √2/2 與 1。選 (1)(2)。"}]}, {"subject": "A", "year": "111", "num": 13, "type": "選填", "rate": "46%", "img": "img/111_q13.png", "answer": [{"t": "選填　"}, {"m": "4.2"}, {"t": " 張"}], "key": "錢只夠 15 次十連抽；每次十連抽的金卡期望 = 9×2% + 1×10%。", "kaodian": [{"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp6"}], "steps": [{"type": "text", "c": "23000÷1500 → 可做 15 次十連抽（15×1500=22500，第 16 次不夠）。每次十連抽的金卡期望："}, {"type": "math", "c": "9\\times0.02+1\\times0.10=0.28"}, {"type": "text", "c": "15 次共 15×0.28 = 4.2 張。"}]}, {"subject": "A", "year": "111", "num": 14, "type": "選填", "rate": "21%", "img": "img/111_q14.png", "answer": [{"t": "選填　"}, {"m": "a=2,\\ b=\\tfrac12"}], "key": "由化簡後矩陣解出含 b 的 (x,y,z)，代回原方程組求 a、b。", "kaodian": [{"unit": "矩陣", "title": "考點4 一次聯立方程式與高斯消去法", "url": "../concept-map/115學測數學_矩陣.html#kp4"}], "steps": [{"type": "text", "c": "由化簡後矩陣：bz=0（唯一解 → b≠0 → z=0）、by=−5 → y=−5/b、x=7−2y=7+10/b。代回原方程組："}, {"type": "math", "c": "\\text{第2式}\\Rightarrow 10-5a=0\\Rightarrow a=2;\\quad \\text{第3式}\\Rightarrow 21-\\dfrac{10}{b}=1\\Rightarrow b=\\dfrac12"}, {"type": "text", "c": "故 a=2、b=1/2。"}]}, {"subject": "A", "year": "111", "num": 15, "type": "選填", "rate": "16%", "img": "img/111_q15.png", "answer": [{"t": "選填　"}, {"m": "192"}, {"t": " 平方公尺"}], "key": "由 9/16 得相似比 3/4（定路寬與高）；由 ∠EBC=30° 定路寬，再算面積。", "kaodian": [{"unit": "三角", "title": "考點6 三角形面積比、相似與角平分線", "url": "../concept-map/115學測數學_三角.html#kp6"}, {"unit": "三角", "title": "考點3 三角測量與平面幾何應用", "url": "../concept-map/115學測數學_三角.html#kp3"}], "steps": [{"type": "text", "c": "剩 9/16 → 頂部小三角形相似比 √(9/16)=3/4 → E 在 AC 的 3/4 處、高 = H/4 = 路寬 h。"}, {"type": "text", "c": "新路寬 = C 到直線 BE 的距離 = BC·sin30° = 16×(1/2) = 8 = h → H=32、△ABC=½·16·32=256。"}, {"type": "text", "c": "E 的高 = H/4 = 8，△BCE=½·16·8=64，故 △ABE = 256 − 64 = 192 平方公尺。"}]}, {"subject": "A", "year": "111", "num": 16, "type": "選填", "rate": "18%", "img": "img/111_q16.png", "answer": [{"t": "選填　"}, {"m": "x-3y-2z=5"}], "key": "L′在 E 的投影＝L（L′在原平面上）→ E 須垂直原平面，且 E 含 L。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "../concept-map/115學測數學_空間向量.html#kp4"}, {"unit": "空間向量", "title": "考點5 空間中的直線、軌跡與歪斜線", "url": "../concept-map/115學測數學_空間向量.html#kp5"}], "steps": [{"type": "text", "c": "L′ 在 E 的投影 = L（L′ 在原平面上）→ E 的法向量須垂直原平面法向量 (1,−1,2)，且 E 含 L（法向量⊥L 的方向 (4,2,−1)）："}, {"type": "math", "c": "\\vec{n}_E=(1,-1,2)\\times(4,2,-1)=(-3,9,6)\\parallel(1,-3,-2)"}, {"type": "text", "c": "E 過 L 上一點 (2,−1,0)：x − 3y − 2z = 5。"}]}, {"subject": "A", "year": "111", "num": 17, "type": "選填", "rate": "5%", "img": "img/111_q17.png", "answer": [{"t": "選填　"}, {"m": "21"}], "key": "三頂點定底面法向量 n；頂面頂點 T 在 xy 單位圓上，體積 =|T·n+11| 取最大。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "../concept-map/115學測數學_空間向量.html#kp3"}, {"unit": "空間向量", "title": "考點1 空間坐標、距離與正立方體", "url": "../concept-map/115學測數學_空間向量.html#kp1"}], "steps": [{"type": "text", "c": "底面三頂點求兩邊 u、v，法向量 n=u×v=(8,−6,9)；三頂點都在平面 n·x=−11 上。"}, {"type": "text", "c": "頂面某頂點 T 在 xy 平面單位圓上（|T|=1）。體積 = |(T−底頂點)·n| = |T·n + 11|，其中 T·n=8x−6y 最大 = 10："}, {"type": "math", "c": "V_{\\max}=|10+11|=21"}]}, {"subject": "A", "year": "111", "num": 18, "type": "混合題（單選 3 分）", "rate": "55%", "img": "img/111_q18.png", "answer": [{"t": "(4)　"}, {"m": "(\\sqrt3,1)"}], "key": "棒長 1、黑端半徑 √3、白端半徑 2，用距離公式解白端角度。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}, {"unit": "直線與圓", "title": "考點3 圓方程式與點的位置", "url": "../concept-map/115學測數學_直線與圓.html#kp3"}], "steps": [{"type": "text", "c": "黑端 A(√3,0)，白端 B=(2cosβ, 2sinβ)，由 |AB|=1："}, {"type": "math", "c": "|AB|^2=7-4\\sqrt3\\cos\\beta=1\\Rightarrow \\cos\\beta=\\dfrac{\\sqrt3}{2}\\Rightarrow B=(\\sqrt3,\\ 1)"}, {"type": "text", "c": "故選 (4)。"}], "stem": "img/111_stem.png"}, {"subject": "A", "year": "111", "num": 19, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/111_q19.png", "answer": [{"t": "非選　"}, {"m": "\\cos\\angle OA'B'=0"}], "key": "白端停在 B′(−2,0)，解黑端 A′；發現 OA′²+A′B′²=OB′² → 直角。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}, {"unit": "直線與圓", "title": "考點3 圓方程式與點的位置", "url": "../concept-map/115學測數學_直線與圓.html#kp3"}], "steps": [{"type": "text", "c": "白端停在 B′(−2,0)，黑端 A′=(√3cosα′, √3sinα′)，由 |A′B′|=1 → cosα′=−√3/2 → A′=(−3/2, √3/2)。"}, {"type": "text", "c": "因 |OA′|=√3、|A′B′|=1、|OB′|=2 且 3+1=4，故 ∠OA′B′ 為直角："}, {"type": "math", "c": "\\cos\\angle OA'B'=0,\\qquad A'\\ \\text{的極坐標}=\\left(\\sqrt3,\\ \\dfrac{5\\pi}{6}\\right)"}, {"type": "text", "c": "（與官方參考答案一致）"}], "stem": "img/111_stem.png"}, {"subject": "A", "year": "111", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/111_q20.png", "answer": [{"t": "非選　"}, {"m": "\\Omega=\\tfrac{6\\sqrt3-\\pi}{12}"}, {"t": "、"}, {"m": "R=\\tfrac{5\\pi}{12}"}], "key": "因 √3²+1²=2²，棒恆與內圓相切；用扇形加減求面積。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}, {"unit": "直線與圓", "title": "考點3 圓方程式與點的位置", "url": "../concept-map/115學測數學_直線與圓.html#kp3"}], "steps": [{"type": "text", "c": "因 √3²+1²=2²，掃描棒恆與內圓相切。第一象限 Ω = 扇形OBE + △OAB − 扇形OAD："}, {"type": "math", "c": "\\Omega=\\tfrac12\\cdot\\tfrac{\\pi}{3}\\cdot2^2+\\tfrac12\\cdot\\sqrt3\\cdot1-\\tfrac12\\cdot\\tfrac{\\pi}{2}\\cdot3=\\dfrac{\\sqrt3}{2}-\\dfrac{\\pi}{12}"}, {"type": "text", "c": "R = 扇形OBB′（半徑 2）− 扇形OCC′（半徑 √3），圓心角皆 5π/6："}, {"type": "math", "c": "R=\\tfrac12\\cdot\\tfrac{5\\pi}{6}\\cdot2^2-\\tfrac12\\cdot\\tfrac{5\\pi}{6}\\cdot3=\\dfrac{5\\pi}{3}-\\dfrac{5\\pi}{4}=\\dfrac{5\\pi}{12}"}, {"type": "text", "c": "故 Ω=(6√3−π)/12、R=5π/12。（與官方一致）"}], "stem": "img/111_stem.png"}, {"subject": "B", "year": "111", "num": 1, "type": "單選", "rate": "74%", "img": "img/111B_q01.png", "answer": [{"t": "(1)　13 個"}], "key": "絕對值分 x≥0 與 x<0 兩種情形拆開，各自解一次不等式再數整數。", "kaodian": [{"unit": "數與式", "title": "考點2 絕對值的意義、方程式與不等式", "url": "../concept-map/115學測數學_數與式.html#kp2"}], "steps": [{"type": "text", "c": "分兩種情形去絕對值："}, {"type": "text", "c": "• x≥0：2x+x=3x<10 → x<10/3，得 x=0,1,2,3（4 個）。"}, {"type": "text", "c": "• x<0：-2x+x=-x<10 → x>-10，得 x=-1,-2,…,-9（9 個）。"}, {"type": "text", "c": "共 4+9=13 個。選 (1)。"}]}, {"subject": "B", "year": "111", "num": 2, "type": "單選", "rate": "83%", "img": "img/111B_q02.png", "answer": [{"t": "(3)　皆為紅燈"}], "key": "一個循環是藍(5)+白(2)+紅(6)+白(2)=15 秒；把 99~101 秒對 15 取餘數，看落在哪一段。", "kaodian": [{"unit": "數列與級數", "title": "考點4 級數求和與規律、週期", "url": "../concept-map/115學測數學_數列與級數.html#kp4"}], "steps": [{"type": "text", "c": "一循環 = 藍5＋白2＋紅6＋白2 = 15 秒。循環內時段：藍[0,5)、白[5,7)、紅[7,13)、白[13,15)。"}, {"type": "text", "c": "99=6×15+9，故第 99、100、101 秒對應循環內的第 9、10、11 秒，都落在 [7,13) → 紅燈。"}, {"type": "text", "c": "所以皆為紅燈。選 (3)。"}]}, {"subject": "B", "year": "111", "num": 3, "type": "單選", "rate": "50%", "img": "img/111B_q03.png", "answer": [{"t": "(2)　13"}], "key": "3 號不設，把大廈分成 {1,2} 與 {4,5,6,7,8} 兩段（2 與 4 不相鄰）；兩段獨立地選「互不相鄰」的基地台。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}], "steps": [{"type": "text", "c": "排除 3 號後，可用大廈為 {1,2} 與 {4,5,6,7,8}；因 2 與 4 之間隔著 3，兩段互不相鄰，可獨立處理。"}, {"type": "text", "c": "要選 3 個且兩兩不相鄰："}, {"type": "text", "c": "• {1,2} 取 0、{4,5,6,7,8} 取 3（不相鄰）：只有 {4,6,8}，1 種。"}, {"type": "text", "c": "• {1,2} 取 1（2 種）、{4,5,6,7,8} 取 2（不相鄰，6 種）：2×6=12 種。"}, {"type": "text", "c": "共 1+12=13 種。選 (2)。"}]}, {"subject": "B", "year": "111", "num": 4, "type": "單選", "rate": "49%", "img": "img/111B_q04.png", "answer": [{"t": "(2)　第二象限"}], "key": "Q = P + 向量 PQ，兩個 x 座標相加時用 log 相加變 log 相乘；再看 Q 的座標正負。", "kaodian": [{"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "../concept-map/115學測數學_平面向量.html#kp1"}, {"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "../concept-map/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "Q = P + PQ。x 座標：log(1/2)+log(1/5)=log(1/10)=-1 <0。"}, {"type": "text", "c": "y 座標：2⁻⁵ - 10⁻⁵ = 1/32 - 1/100000 > 0。"}, {"type": "text", "c": "Q=(-1, 正) → x<0、y>0，在第二象限。選 (2)。"}]}, {"subject": "B", "year": "111", "num": 5, "type": "單選", "rate": "65%", "img": "img/111B_q05.png", "answer": [{"t": "(5)　10"}], "key": "先算 A²：這個 A 剛好 A²=2I，於是高次方能一路化簡。", "kaodian": [{"unit": "矩陣", "title": "考點2 矩陣的高次方 \\(A^n\\)★★☆", "url": "../concept-map/115學測數學_矩陣.html#kp2"}], "steps": [{"type": "text", "c": "先算 A²："}, {"type": "math", "c": "A^2=\\begin{bmatrix}1&1\\\\1&-1\\end{bmatrix}^2=\\begin{bmatrix}2&0\\\\0&2\\end{bmatrix}=2I"}, {"type": "text", "c": "所以 A⁷=A·(A²)³=A·(2I)³=8A，故 A⁷-3A=8A-3A=5A："}, {"type": "math", "c": "5A=\\begin{bmatrix}5&5\\\\5&-5\\end{bmatrix}\\Rightarrow a+b+c+d=5+5+5-5=10"}, {"type": "text", "c": "選 (5)。"}]}, {"subject": "B", "year": "111", "num": 6, "type": "單選", "rate": "53%", "img": "img/111B_q06.png", "answer": [{"t": "(3)　東經 75°、南緯 15°"}], "key": "沿經線走的弧長 = 半徑 × 圓心角；圓心角 = 甲地到北極的角度。先把 7π/12 換成度數。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "弧長 = r×圓心角（弧度）。7π/12 弧度 = 7×180/12 = 105°，即甲地到北極的角度是 105°。"}, {"type": "text", "c": "到北極角度 = 90°+（南緯度數），故 90°+南緯 = 105° → 南緯 15°（經度不影響經線弧長）。"}, {"type": "text", "c": "含南緯 15° 的是選 (3)。"}]}, {"subject": "B", "year": "111", "num": 7, "type": "單選", "rate": "27%", "img": "img/111B_q07.png", "answer": [{"t": "(5)　1, 7, 9, 10"}], "key": "K 值在透視下維持不變；先算空間中「等距四點」的 K，再找畫紙上哪組座標算出同樣的 K。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}], "steps": [{"type": "text", "c": "空間中 Q₁Q₂=Q₂Q₃=Q₃Q₄（等距），取座標 0,1,2,3 算 K："}, {"type": "math", "c": "K=\\dfrac{\\overline{P_1P_4}\\cdot\\overline{P_2P_3}}{\\overline{P_1P_3}\\cdot\\overline{P_2P_4}}=\\dfrac{3\\cdot1}{2\\cdot2}=\\dfrac34"}, {"type": "text", "c": "畫紙上四點 K 必須也 =3/4。逐一檢查，只有 (5) 1,7,9,10："}, {"type": "math", "c": "\\dfrac{(10-1)(9-7)}{(9-1)(10-7)}=\\dfrac{9\\cdot2}{8\\cdot3}=\\dfrac{3}{4}"}, {"type": "text", "c": "選 (5)。"}]}, {"subject": "B", "year": "111", "num": 8, "type": "多選", "rate": "54%（全對率 30%）", "img": "img/111B_q08.png", "answer": [{"t": "(1)(2)(5)"}], "key": "雷射是 y=ax；擊中某靶 ⟺ 圓心到直線距離 ≤1。把三個「距離≤1」化成 a 的範圍，比對有無交集。", "kaodian": [{"unit": "直線與圓", "title": "考點4 直線與圓的位置：相切、弦長與切線", "url": "../concept-map/115學測數學_直線與圓.html#kp4"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "雷射沿 (1,a) 方向從原點出發，即直線 y=ax（(1) 正確）。圓心 (x₀,y₀) 到此線距離 = |ax₀-y₀|/√(a²+1)。"}, {"type": "text", "c": "(2) a=3/2 時，(4,6) 到線距離 = |6-6|/√13 = 0 ≤1，擊中 ✓。"}, {"type": "text", "c": "(5) 擊中 (8,1)：|8a-1|≤√(a²+1) → 63a²-16a≤0 → 0≤a≤16/63 ✓。"}, {"type": "text", "c": "三靶各自的 a 範圍：(2,2)→[0.45,2.22]、(4,6)→[1.12,2.08]、(8,1)→[0,0.25]。第三靶與前兩靶無交集，故一道雷射打不到三靶，(3) 錯；但 (2,2)(4,6) 可同一道打中，加打第三靶只需 2 道，(4) 錯。答 (1)(2)(5)。"}]}, {"subject": "B", "year": "111", "num": 9, "type": "多選", "rate": "42%（全對率 16%）", "img": "img/111B_q09.png", "answer": [{"t": "(1)"}], "key": "三次函數 ax³+bx²+cx+d 的對稱中心在 x=-b/(3a)；此題 b=0，中心在 x=0，即 (0,1)，不是 (1,0)。", "kaodian": [{"unit": "多項式函數", "title": "考點5 三次函數圖形與對稱中心", "url": "../concept-map/115學測數學_多項式函數.html#kp5"}], "steps": [{"type": "text", "c": "(1) f(1)=2-3+1=0，圖形過 (1,0) ✓。"}, {"type": "text", "c": "(2) f(x)=(x-1)(2x²+2x-1)，2x²+2x-1=0 有兩相異實根，故與 x 軸共 3 個交點 → 錯。"}, {"type": "text", "c": "(3) 三次函數對稱中心在 x=-b/(3a)=0，中心是 (0, f(0))=(0,1) 不是 (1,0) → 錯。"}, {"type": "text", "c": "(4) 在中心 x=0 附近，x 很小時 2x³ 幾乎可忽略，故 f(x)≈-3x+1（只剩 -3x+1），是 y=-3x+1 不是 y=3x-3 → 錯。"}, {"type": "text", "c": "(5) 最高次係數 3≠2，平移不會改變最高次係數，兩圖形無法重合 → 錯。答 (1)。"}]}, {"subject": "B", "year": "111", "num": 10, "type": "多選", "rate": "46%（全對率 26%）", "img": "img/111B_q10.png", "answer": [{"t": "(1)(2)(4)"}], "key": "平均、標準差跟著線性變換走：由調整後回推原始平均與標準差；比較時記得分數上限 100。", "kaodian": [{"unit": "數據分析", "title": "考點1 一維數據：平均、中位數與標準差", "url": "../concept-map/115學測數學_數據分析.html#kp1"}], "steps": [{"type": "text", "c": "由調整後平均 60：甲 0.8·平均(x₁)+20=60→平均(x₁)=50；乙 0.75·平均(x₂)+25=60→平均(x₂)=46.7。標準差：0.8·s₁=16→s₁=20；0.75·s₂=15→s₂=20。"}, {"type": "text", "c": "(1) 甲 y₁=0.8x₁+20≥x₁ ⟺ x₁≤100，恒成立 ✓。"}, {"type": "text", "c": "(2) 平均 50>46.7 ✓。"}, {"type": "text", "c": "(4) 若 0.8x_A+20>0.75x_B+25，反設 x_A≤x_B 會推出 x_B>100（矛盾），故 x_A>x_B ✓。"}, {"type": "text", "c": "(3) 兩班原始標準差都 20，不是「甲較高」→ 錯。(5) 調整後不及格用的門檻（x₁<50、x₂<46.7）與原始不及格門檻（<60）不同，無法推得 → 錯。答 (1)(2)(4)。"}]}, {"subject": "B", "year": "111", "num": 11, "type": "多選", "rate": "50%（全對率 34%）", "img": "img/111B_q11.png", "answer": [{"t": "(2)(3)"}], "key": "v·OA>0、v·OB>0 把 v 的方向鎖在 OA、OB 之間的一個扇形；v 與某向量內積「一定<0」代表該向量落在這扇形的正對面扇形。", "kaodian": [{"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}], "steps": [{"type": "text", "c": "v·OA>0 且 v·OB>0，表示 v 與 OA、OB 都成銳角，v 的方向被夾在一個約從 -35° 到 65° 的扇形內。"}, {"type": "text", "c": "v·OX 一定<0 ⟺ OX 落在此扇形的「正對面」範圍（約 155°~235°），這裡的 v 才會與 OX 都成鈍角。"}, {"type": "text", "c": "各點方向：C≈110°、D≈170°、E≈190°、F≈265°、G≈300°。落在 155°~235° 的只有 D、E。答 (2)(3)。"}]}, {"subject": "B", "year": "111", "num": 12, "type": "多選", "rate": "39%（全對率 20%）", "img": "img/111B_q12.png", "answer": [{"t": "(3)(5)"}], "key": "把原式的 x 換成 g(x)，新方程式的根 x 滿足 g(x)= 原根（在 1~3）；要新根落在 4~5，就要 g 把 (4,5) 對到 (1,3)。", "kaodian": [{"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "../concept-map/115學測數學_多項式函數.html#kp2"}, {"unit": "多項式函數", "title": "考點3 多項式方程式與不等式的解法", "url": "../concept-map/115學測數學_多項式函數.html#kp3"}], "steps": [{"type": "text", "c": "原方程式根在 (1,3)。若把 x 換成 g(x)，新根 x 滿足 g(x)=原根∈(1,3)。要新根落在 (4,5)，需 g 把 (4,5) 映到 (1,3) 內。"}, {"type": "text", "c": "(3) g(x)=2x-7：x∈(4,5)→2x-7∈(1,3) ✓。"}, {"type": "text", "c": "(5) g(x)=3x-11：x∈(4,5)→3x-11∈(1,4)，其中對應原根 (1,3) 的 x∈(4, 14/3)⊂(4,5) ✓。"}, {"type": "text", "c": "(1)(2)(4) 映出的範圍分別是 (3,5)、(-1,1)、(-5,-1)，都不保證落在 (4,5) → 錯。答 (3)(5)。"}]}, {"subject": "B", "year": "111", "num": 13, "type": "選填", "rate": "48%", "img": "img/111B_q13.png", "answer": [{"t": "99"}], "key": "先用 2 log y=1 解出 y，再代回指數式解 x。", "kaodian": [{"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "../concept-map/115學測數學_指數與對數.html#kp1"}, {"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "../concept-map/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "2 log y=1 → log y=1/2 → y=√10，故 y²=10。"}, {"type": "text", "c": "x^(-1/3)·y²=1 → x^(-1/3)=1/10 → x^(1/3)=10 → x=1000。"}, {"type": "math", "c": "\\dfrac{x-y^2}{10}=\\dfrac{1000-10}{10}=99"}, {"type": "text", "c": "答 99。"}]}, {"subject": "B", "year": "111", "num": 14, "type": "選填", "rate": "44%", "img": "img/111B_q14.png", "answer": [{"t": "17"}], "key": "用 |AB|²=|OB-OA|² 展開，就會出現內積 OA·OB。", "kaodian": [{"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}], "steps": [{"type": "text", "c": "AB=OB-OA，且 |OA|=|OB|=7、|AB|=8："}, {"type": "math", "c": "|AB|^2=|OA|^2+|OB|^2-2\\,\\vec{OA}\\cdot\\vec{OB}=98-2\\,\\vec{OA}\\cdot\\vec{OB}=64"}, {"type": "text", "c": "解得 OA·OB=17。答 17。"}]}, {"subject": "B", "year": "111", "num": 15, "type": "選填", "rate": "52%", "img": "img/111B_q15.png", "answer": [{"m": "\\dfrac{14}{15}"}], "key": "用貝氏定理：P(找到|裝ELT)=（找到且裝ELT）÷（全部裝ELT），分「找到」「沒找到」兩支計算。", "kaodian": [{"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "../concept-map/115學測數學_排列組合與機率.html#kp4"}], "steps": [{"type": "text", "c": "P(找到)=0.7、P(沒找到)=0.3；P(裝ELT|找到)=0.6、P(裝ELT|沒找到)=1-0.9=0.1。"}, {"type": "math", "c": "P(\\text{找到}\\mid \\text{裝ELT})=\\dfrac{0.6\\times0.7}{0.6\\times0.7+0.1\\times0.3}=\\dfrac{0.42}{0.45}=\\dfrac{14}{15}"}, {"type": "text", "c": "答 14/15。"}]}, {"subject": "B", "year": "111", "num": 16, "type": "選填", "rate": "39%", "img": "img/111B_q16.png", "answer": [{"m": "\\dfrac{31}{45}"}], "key": "先由「皆藍」「皆綠」的機率反推藍、綠球數，得黃球數；相異色機率 = 1 - 同色機率。", "kaodian": [{"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "../concept-map/115學測數學_排列組合與機率.html#kp3"}, {"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}], "steps": [{"type": "text", "c": "抽 2 顆共 C(10,2)=45 種。皆藍 C(b,2)/45=1/15→C(b,2)=3→b=3；皆綠 C(g,2)/45=2/9→C(g,2)=10→g=5；黃=10-3-5=2。"}, {"type": "text", "c": "同色機率 = 皆藍+皆綠+皆黃 = 1/15+2/9+C(2,2)/45 = 3/45+10/45+1/45 = 14/45。"}, {"type": "math", "c": "P(\\text{相異色})=1-\\dfrac{14}{45}=\\dfrac{31}{45}"}, {"type": "text", "c": "答 31/45。"}]}, {"subject": "B", "year": "111", "num": 17, "type": "選填", "rate": "7%", "img": "img/111B_q17.png", "answer": [{"t": "456"}], "key": "老師固定中間，剩 6 人排 6 位；先扣掉「三男同側」，再扣掉「該對男女相鄰」（此兩情況不會同時發生）。", "kaodian": [{"unit": "排列組合與機率", "title": "考點1 計數原理與排列（有順序）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "老師在正中間，其餘 6 人排 6 個位子共 6!=720 種。"}, {"type": "text", "c": "扣掉三男全在同一側：全在左 3!·3!=36、全在右 36，共 72 → 剩 648。"}, {"type": "text", "c": "再扣掉「該一女一男相鄰」：相鄰只可能在同一側的 (1,2)(2,3)(5,6)(6,7) 四組×2×其餘 4!=192 種；且此時該對同側，另一側湊不出三男，與「三男同側」不重疊。"}, {"type": "math", "c": "648-192=456"}, {"type": "text", "c": "答 456。"}]}, {"subject": "B", "year": "111", "num": 18, "type": "混合題（單選 5 分）", "rate": "70%", "img": "img/111B_q18.png", "answer": [{"t": "(4)　"}, {"m": "\\dfrac{\\pi}{10}"}], "key": "角度換弧度：乘以 π/180。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "math", "c": "18^\\circ=18\\times\\dfrac{\\pi}{180}=\\dfrac{\\pi}{10}"}, {"type": "text", "c": "選 (4)。"}], "stem": "img/111B_stem.png"}, {"subject": "B", "year": "111", "num": 19, "type": "非選擇題（4 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/111B_q19.png", "answer": [{"m": "\\theta_1<\\theta_3<\\theta_2"}], "key": "由題目定義：偏移距離 = 塔高 × sinθ，故 sinθ = 偏移距離 ÷ 塔高；θ 在 [0,90) 時 sin 遞增，比 sinθ 即比 θ。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "偏移距離 = 塔高·sinθ → sinθ = 偏移距離 ÷ 塔高："}, {"type": "math", "c": "\\sin\\theta_1=\\tfrac{2.3}{48}\\approx0.048,\\ \\sin\\theta_2=\\tfrac{2.3}{19}\\approx0.121,\\ \\sin\\theta_3=\\tfrac{4}{57}\\approx0.070"}, {"type": "text", "c": "θ 在 [0°,90°) 時 sin 遞增，故由 sin 大小得 θ₁<θ₃<θ₂。"}], "stem": "img/111B_stem.png"}, {"subject": "B", "year": "111", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/111B_q20.png", "answer": [{"m": "100\\sqrt{6}-240"}, {"t": " 公尺（約 4.95）"}], "key": "偏移距離 = 塔高·sinθ、塔頂到地面 = 塔高·cosθ；先用偏移距離差求塔高，再用 cos 算高度差。", "kaodian": [{"unit": "三角", "title": "考點3 三角測量與平面幾何應用", "url": "../concept-map/115學測數學_三角.html#kp3"}, {"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "設塔高 h（兩塔相等）。sinα=1/5、sinβ=7/25。偏移距離差："}, {"type": "math", "c": "h\\sin\\beta-h\\sin\\alpha=h\\left(\\tfrac{7}{25}-\\tfrac{1}{5}\\right)=h\\cdot\\tfrac{2}{25}=20\\Rightarrow h=250"}, {"type": "text", "c": "塔頂到地面 = h·cosθ。cosα=√(1-1/25)=2√6/5、cosβ=√(1-49/625)=24/25："}, {"type": "math", "c": "h\\cos\\alpha=250\\cdot\\tfrac{2\\sqrt6}{5}=100\\sqrt6,\\quad h\\cos\\beta=250\\cdot\\tfrac{24}{25}=240"}, {"type": "math", "c": "\\text{相差}=100\\sqrt6-240\\approx4.95\\ \\text{公尺}"}], "stem": "img/111B_stem.png"}, {"subject": "A", "year": "112", "num": 1, "type": "單選", "rate": "78%", "img": "img/112_q01.png", "answer": [{"t": "(4)　"}, {"m": "N=2^{8}"}], "key": "連按 √ 三次＝取 1/8 次方；反推 N。", "kaodian": [{"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "../concept-map/115學測數學_指數與對數.html#kp1"}], "steps": [{"type": "text", "c": "連按 √ 鍵三次，相當於取 N 的 1/8 次方（√√√N = N^(1/8)）。"}, {"type": "math", "c": "N^{1/8}=2\\Rightarrow N=2^{8}"}, {"type": "text", "c": "故選 (4)。"}]}, {"subject": "A", "year": "112", "num": 2, "type": "單選", "rate": "59%", "img": "img/112_q02.png", "answer": [{"t": "(5)　"}, {"m": "\\overline{CD}"}], "key": "用切點參數寫切線求 D、E；θ 在直角△ODE 中，tanθ 剛好等於 CD。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}, {"unit": "直線與圓", "title": "考點4 直線與圓的位置：相切、弦長與切線", "url": "../concept-map/115學測數學_直線與圓.html#kp4"}], "steps": [{"type": "text", "c": "設切點 C=(cosφ, sinφ)。切線 x cosφ + y sinφ = 1，交兩軸於 E=(0, 1/sinφ)、D=(1/cosφ, 0)。"}, {"type": "text", "c": "直角三角形 ODE（直角在 O）中，∠OED=θ："}, {"type": "math", "c": "\\tan\\theta=\\dfrac{OD}{OE}=\\dfrac{1/\\cos\\varphi}{1/\\sin\\varphi}=\\tan\\varphi"}, {"type": "text", "c": "另外算得 CD=tanφ（C 在切線上）。故 tanθ = CD，選 (5)。"}]}, {"subject": "A", "year": "112", "num": 3, "type": "單選", "rate": "51%", "img": "img/112_q03.png", "answer": [{"t": "(4)　"}, {"m": "t^2=10^{s}"}], "key": "(s, log t) 幾乎是一條斜率約 1/2 的直線 → log t = s/2。", "kaodian": [{"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "../concept-map/115學測數學_數據分析.html#kp3"}, {"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "../concept-map/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "圖上 (s, log t) 幾乎成一直線，過原點附近、斜率約 1/2。故 log t = (1/2)s："}, {"type": "math", "c": "\\log t=\\dfrac{s}{2}\\Rightarrow t=10^{s/2}\\Rightarrow t^2=10^{s}"}, {"type": "text", "c": "故選 (4)。"}]}, {"subject": "A", "year": "112", "num": 4, "type": "單選", "rate": "44%", "img": "img/112_q04.png", "answer": [{"t": "(1)"}], "key": "第 5 位同時是前段最大與後段最大 → 必為 9；其餘選 4 個放左邊即可。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}, {"unit": "排列組合與機率", "title": "考點1 計數原理與排列（有順序）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "前 5 位遞增、後 5 位遞減，第 5 位是兩段共同的最大 → 必為 9。"}, {"type": "text", "c": "剩下 1~8 這 8 個數，選 4 個放左邊（升冪，唯一排法），其餘 4 個放右邊（降冪）："}, {"type": "math", "c": "\\binom{8}{4}=\\dfrac{8!}{4!\\,4!}"}, {"type": "text", "c": "故選 (1)。"}]}, {"subject": "A", "year": "112", "num": 5, "type": "單選", "rate": "47%", "img": "img/112_q05.png", "answer": [{"t": "(2)"}], "key": "PQ、PR 在平面上 → 外積平行法向量 (2,−3,5)；行列式 = 頂列與 (2,−3,5) 的內積 × 定值。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "../concept-map/115學測數學_空間向量.html#kp3"}, {"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "../concept-map/115學測數學_空間向量.html#kp4"}], "steps": [{"type": "text", "c": "PQ、PR 都在平面上，故 PQ×PR 平行於法向量 (2,−3,5)。每個行列式 = 頂列向量·(PQ×PR) = 頂列與 (2,−3,5) 的內積再乘一個相同的定值。"}, {"type": "text", "c": "比較各頂列與 (2,−3,5) 的內積絕對值：(1) 0、(2) 10、(3) 6、(4) 6、(5) 4。"}, {"type": "math", "c": "(2):\\ (1,-1,1)\\cdot(2,-3,5)=2+3+5=10\\ (\\text{最大})"}, {"type": "text", "c": "故選 (2)。"}]}, {"subject": "A", "year": "112", "num": 6, "type": "單選", "rate": "35%", "img": "img/112_q06.png", "answer": [{"t": "(3)　"}, {"m": "\\dfrac{6}{7}"}], "key": "用「(向量總和)² = 各長度平方和 + 2×兩兩內積和」一次算出所有內積總和。", "kaodian": [{"unit": "空間向量", "title": "考點2 空間向量的內積、夾角與垂直", "url": "../concept-map/115學測數學_空間向量.html#kp2"}, {"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp6"}], "steps": [{"type": "text", "c": "O 為原點，其餘 7 個頂點向量的總和 = (4,4,4)、長度平方和 = 12。兩兩內積的總和："}, {"type": "math", "c": "\\sum_{i<j}\\vec{v_i}\\cdot\\vec{v_j}=\\dfrac{|(4,4,4)|^2-12}{2}=\\dfrac{48-12}{2}=18"}, {"type": "text", "c": "共 C(7,2)=21 對，期望值 = 18/21 = 6/7，選 (3)。"}]}, {"subject": "A", "year": "112", "num": 7, "type": "多選", "rate": "65%（全對率 46%）", "img": "img/112_q07.png", "answer": [{"t": "(3)(5)"}], "key": "甲每滿 3 月 +200、乙每滿 12 月 +1000；逐項比對月薪與累積總薪。", "kaodian": [{"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "../concept-map/115學測數學_數列與級數.html#kp1"}], "steps": [{"type": "text", "c": "起薪同為 S。甲每滿 3 個月調一次 +200、乙每滿 12 個月調一次 +1000。"}, {"type": "text", "c": "(1) 甲第 9 月 = S+400（比第 1 月多 400，不是 600）錯。(2) 第 13 月：甲 S+800 < 乙 S+1000 錯。"}, {"type": "text", "c": "(3) 第 19 月：甲 S+1200 > 乙 S+1000，對。(4) 前 18 月總薪：甲 18S+9000 > 乙 18S+6000，錯。"}, {"type": "text", "c": "(5) 第 3 年（25~36 月）乙都是 S+2000；甲只有第 34、35、36 月為 S+2200 才 > 乙，恰 3 個月，對。故選 (3)(5)。"}]}, {"subject": "A", "year": "112", "num": 8, "type": "多選", "rate": "44%（全對率 29%）", "img": "img/112_q08.png", "answer": [{"t": "(1)(4)"}], "key": "用餘事件：n 次至少中 1 次的機率 pₙ = 1 −(0.9)ⁿ。", "kaodian": [{"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "../concept-map/115學測數學_排列組合與機率.html#kp5"}], "steps": [{"type": "math", "c": "p_n=1-(0.9)^n"}, {"type": "text", "c": "(1) (0.9)^(n+1)<(0.9)^n → p_(n+1)>pₙ，對。(2) p₃=1−0.729=0.271≠0.3，錯。(3) 相鄰差 0.1·(0.9)ⁿ 非定值，不是等差，錯。"}, {"type": "text", "c": "(4) 第一次未中、第二次中 = 0.9×0.1 = 0.09；而 p₂−p₁ = 0.19−0.1 = 0.09，相等，對。"}, {"type": "text", "c": "(5) 至少中 2 次 ≠ 2pₙ（後者可能超過 1），錯。故選 (1)(4)。"}]}, {"subject": "A", "year": "112", "num": 9, "type": "多選", "rate": "46%（全對率 22%）", "img": "img/112_q09.png", "answer": [{"t": "(3)(5)"}], "key": "log₃aₖ =(3k−1)/2；交錯和在 n 偶時為負、n 奇時 =(3n+1)/4。", "kaodian": [{"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "../concept-map/115學測數學_數列與級數.html#kp2"}, {"unit": "指數與對數", "title": "考點5 指對數的應用：成長衰退模型與數列", "url": "../concept-map/115學測數學_指數與對數.html#kp5"}], "steps": [{"type": "text", "c": "aₖ = 3·(3√3)^(k−1)，故 log₃aₖ =(3k−1)/2。交錯和 Sₙ："}, {"type": "math", "c": "n\\text{ 偶}:\\ S_n=-\\dfrac{3n}{4}<0;\\qquad n\\text{ 奇}:\\ S_n=\\dfrac{3n+1}{4}"}, {"type": "text", "c": "要 >18 須 n 為奇數且 (3n+1)/4>18 → n>71/3 → n≥25。選項中 25、27 符合（23 太小；24、26 為偶數）。"}, {"type": "text", "c": "故選 (3)(5)。"}]}, {"subject": "A", "year": "112", "num": 10, "type": "多選", "rate": "45%（全對率 21%）", "img": "img/112_q10.png", "answer": [{"t": "(1)(3)(5)"}], "key": "D=(0,2k) 在 OC、E=(10,8−2k) 在 AB；DE 都在長方形內須 1≤k≤3。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}, {"unit": "直線與圓", "title": "考點5 平面區域與線性規劃", "url": "../concept-map/115學測數學_直線與圓.html#kp5"}], "steps": [{"type": "text", "c": "L 交左邊 OC 於 D=(0, 2k)、交右邊 AB 於 E=(10, 8−2k)，斜率 =(4−2k)/5。"}, {"type": "text", "c": "(1) k=4 代入，L 過 A(10,0)，對。(3) D 在 OC 上須 0≤2k≤6 即 0≤k≤3，對。"}, {"type": "text", "c": "DE 都在長方形內：D 在 OC（0≤k≤3）且 E 在 AB（1≤k≤4）→ 1≤k≤3，此時斜率∈[−2/5, 2/5]。"}, {"type": "math", "c": "(5)\\ \\dfrac{4-2k}{5}=\\dfrac{3}{10}\\Rightarrow k=\\dfrac54\\in[1,3]\\Rightarrow \\text{斜率 }\\tfrac{3}{10}\\text{ 可能（對）}"}, {"type": "text", "c": "(2) L 過 C 時 k=3、斜率 −2/5≠−5/2 錯；(4) k=1/2 時 E=(10,7) 在長方形外 錯。故選 (1)(3)(5)。（見右圖）"}], "fig": "img/112_fig_q10.png"}, {"subject": "A", "year": "112", "num": 11, "type": "多選", "rate": "38%（全對率 17%）", "img": "img/112_q11.png", "answer": [{"t": "(2)(5)"}], "key": "把四個變換矩陣寫出來直接運算比對。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "../concept-map/115學測數學_矩陣.html#kp5"}], "steps": [{"type": "text", "c": "A=順轉90°=[[0,1],[−1,0]]、B=逆轉90°=[[0,−1],[1,0]]、C=對 x=y 鏡射=[[0,1],[1,0]]、D=對 x=−y 鏡射=[[0,−1],[−1,0]]。"}, {"type": "text", "c": "(2) −B=[[0,1],[−1,0]]=A，對。(1) A、C 把 (1,0) 各送到 (0,−1)、(0,1) 不同，錯。(3) 鏡射的逆是自己，D⁻¹=D≠C，錯。(4) AB=I、CD=−I 不等，錯。"}, {"type": "math", "c": "(5)\\ AC=\\begin{bmatrix}1&0\\\\0&-1\\end{bmatrix}=BD\\ (\\text{對})"}, {"type": "text", "c": "故選 (2)(5)。"}]}, {"subject": "A", "year": "112", "num": 12, "type": "多選", "rate": "21%（全對率 6%）", "img": "img/112_q12.png", "answer": [{"t": "(1)(5)"}], "key": "先用疊合把 f 寫成 2sin(x+π/3)，對稱軸在最大/最小處。", "kaodian": [{"unit": "三角", "title": "考點4 三角函數圖形：週期、對稱與疊合", "url": "../concept-map/115學測數學_三角.html#kp4"}, {"unit": "三角", "title": "考點5 和差角與倍角", "url": "../concept-map/115學測數學_三角.html#kp5"}], "steps": [{"type": "math", "c": "f(x)=\\sin x+\\sqrt3\\cos x=2\\sin\\!\\left(x+\\tfrac{\\pi}{3}\\right)"}, {"type": "text", "c": "(1) x=π/6 時 f=2（最大值），是對稱軸，對。(2) 對稱軸有的在最大(f=2)、有的在最小(f=−2)，f(a) 不一定 = f(b)，錯。"}, {"type": "text", "c": "(3) f(x)=√3 → sin(x+π/3)=√3/2，在 [0,2π) 有 2 個解（x=0, π/3）不是 1 個，錯。"}, {"type": "text", "c": "(4) f(x)=1/2 的兩解之和 = 7π/3 > 2π，錯。(5) 4sin²(x/2)=2−2cosx（振幅 2 的餘弦），平移可得 f，對。故選 (1)(5)。"}]}, {"subject": "A", "year": "112", "num": 13, "type": "選填", "rate": "87%", "img": "img/112_q13.png", "answer": [{"t": "選填　咖啡 "}, {"m": "80"}, {"t": " 元"}], "key": "三元一次方程組；取「第1天 − 2×第2天」直接消去，解出咖啡價。", "kaodian": [{"unit": "矩陣", "title": "考點4 一次聯立方程式與高斯消去法", "url": "../concept-map/115學測數學_矩陣.html#kp4"}], "steps": [{"type": "text", "c": "設果汁 x、奶茶 y、咖啡 z 元，列出三天的三個方程式。取（第1天）−2×（第2天）："}, {"type": "math", "c": "(60x{+}80y{+}50z)-2(30x{+}40y{+}30z)=12900-2(6850)\\Rightarrow -10z=-800"}, {"type": "text", "c": "得 z=80，故咖啡每杯 80 元。"}]}, {"subject": "A", "year": "112", "num": 14, "type": "選填", "rate": "67%", "img": "img/112_q14.png", "answer": [{"t": "選填　"}, {"m": "(a,b)=(3,-9)"}], "key": "兩者同為二次 → 商是常數 a；算出餘式，令 x 項係數 0、常數項 6。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "../concept-map/115學測數學_多項式函數.html#kp1"}], "steps": [{"type": "text", "c": "兩者皆二次，商為常數 a。餘式 = 原式 − a·(除式)："}, {"type": "math", "c": "\\text{餘式}=(a^2+b)x+(2a^2-12)"}, {"type": "text", "c": "令 x 係數 = 0、常數 = 6：a²+b=0 且 2a²−12=6 → a²=9 → a=3（a>0）、b=−9。"}, {"type": "math", "c": "(a,b)=(3,\\ -9)"}]}, {"subject": "A", "year": "112", "num": 15, "type": "選填", "rate": "25%", "img": "img/112_q15.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{OB}{OA}=\\dfrac34"}], "key": "設 OA、OB 為垂直坐標軸；由 3AD=8BD 求 D，再用 OC⊥OD。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}], "steps": [{"type": "text", "c": "設 OA=(p,0)、OB=(0,q)（垂直）。則 OC=(3p/5, 2q/5)。由 3(D−A)=8(D−B) 解得 D=(−3p/5, 8q/5)。"}, {"type": "text", "c": "OC⊥OD → OC·OD=0："}, {"type": "math", "c": "-\\dfrac{9p^2}{25}+\\dfrac{16q^2}{25}=0\\Rightarrow \\dfrac{q^2}{p^2}=\\dfrac{9}{16}\\Rightarrow \\dfrac{OB}{OA}=\\dfrac{q}{p}=\\dfrac34"}]}, {"subject": "A", "year": "112", "num": 16, "type": "選填", "rate": "24%", "img": "img/112_q16.png", "answer": [{"t": "選填　"}, {"m": "2\\sqrt2"}], "key": "P 的投影點與 A、B、C 等距 → 投影點是 △ABC 的外心；再算 P 到 E 的距離。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "../concept-map/115學測數學_空間向量.html#kp4"}, {"unit": "空間向量", "title": "考點1 空間坐標、距離與正立方體", "url": "../concept-map/115學測數學_空間向量.html#kp1"}], "steps": [{"type": "text", "c": "P 在 E 上的投影點與 A、B、C 等距 → 該投影點是 △ABC 的外心，解得外心 = (−1,−4,3)。"}, {"type": "text", "c": "P 在 z=1 上、沿法向量 (1,0,1) 投影到外心，得 P=(−3,−4,1)。點到平面 E 的距離："}, {"type": "math", "c": "d=\\dfrac{|x+z-2|}{\\sqrt2}=\\dfrac{|-3+1-2|}{\\sqrt2}=\\dfrac{4}{\\sqrt2}=2\\sqrt2"}]}, {"subject": "A", "year": "112", "num": 17, "type": "選填", "rate": "10%", "img": "img/112_q17.png", "answer": [{"t": "選填　"}, {"m": "\\overline{PQ}=5\\sqrt2"}], "key": "L3 是兩線的公垂線；P、Q 到 L3 的位移都垂直 L3 方向，配畢氏定理。", "kaodian": [{"unit": "空間向量", "title": "考點5 空間中的直線、軌跡與歪斜線", "url": "../concept-map/115學測數學_空間向量.html#kp5"}, {"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "../concept-map/115學測數學_空間向量.html#kp3"}], "steps": [{"type": "text", "c": "L1、L2 方向 (1,−1,1)、(2,1,−1) 互相垂直。兩線的公垂線段長 MN=4√2（M、N 為垂足）。"}, {"type": "text", "c": "P 在 L1、Q 在 L2，到公垂線 L3 距離皆 3；因 P−M、Q−N 都垂直 L3 方向，故 |PM|=|QN|=3，且 MN 垂直於兩方向："}, {"type": "math", "c": "\\overline{PQ}^{\\,2}=\\overline{MN}^{\\,2}+(|PM|^2+|QN|^2)=32+(9+9)=50\\Rightarrow \\overline{PQ}=5\\sqrt2"}]}, {"subject": "A", "year": "112", "num": 18, "type": "混合題（單選 3 分）", "rate": "56%", "img": "img/112_q18.png", "answer": [{"t": "(4)　"}, {"m": "2\\cos\\theta"}], "key": "△OAP 等腰（OA=AP=1），設 P=OP·(cosθ,sinθ)，用 |AP|=1 解出 OP。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "../concept-map/115學測數學_三角.html#kp2"}, {"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "令 ∠AOP=θ。因 AP=OA=1，設 P=OP·(cosθ, sinθ)，由 |AP|=1（P 到 A(1,0) 距離為 1）："}, {"type": "math", "c": "(OP\\cos\\theta-1)^2+(OP\\sin\\theta)^2=1\\Rightarrow OP^2=2\\,OP\\cos\\theta\\Rightarrow OP=2\\cos\\theta"}, {"type": "text", "c": "故選 (4)。"}], "stem": "img/112_stem.png"}, {"subject": "A", "year": "112", "num": 19, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/112_q19.png", "answer": [{"t": "非選　"}, {"m": "Q=\\left(-\\tfrac{36}{25},\\tfrac{48}{25}\\right)"}], "key": "sinθ=3/5→cosθ=4/5；先求 P，再由 ∠POQ=90° 與 OQ=4sinθ 求 Q。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}, {"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "../concept-map/115學測數學_平面向量.html#kp1"}], "steps": [{"type": "text", "c": "cosθ=4/5，OP=2cosθ=8/5，故 P=(8/5)(4/5, 3/5)=(32/25, 24/25)。"}, {"type": "text", "c": "OQ 與 OP 垂直（∠POQ=90°）、方向 (−sinθ, cosθ)；同理在 △OBQ 得 OQ=4sinθ=12/5："}, {"type": "math", "c": "Q=\\dfrac{12}{5}\\left(-\\tfrac35,\\ \\tfrac45\\right)=\\left(-\\dfrac{36}{25},\\ \\dfrac{48}{25}\\right)"}, {"type": "text", "c": "驗證：AP=(7/25, 24/25)、BQ=(14/25, 48/25)=2·AP，得證。（與官方參考答案一致）"}], "stem": "img/112_stem.png"}, {"subject": "A", "year": "112", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/112_q20.png", "answer": [{"t": "非選　A到BQ "}, {"m": "\\dfrac{72}{25}"}, {"t": "、面積 "}, {"m": "\\dfrac{108}{25}"}], "key": "PABQ 是 AP∥BQ 的梯形；A 到 BQ 用點到直線公式，面積 = ½(上底+下底)×高。", "kaodian": [{"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "../concept-map/115學測數學_直線與圓.html#kp2"}, {"unit": "平面向量", "title": "考點4 行列式與平行四邊形面積", "url": "../concept-map/115學測數學_平面向量.html#kp4"}], "steps": [{"type": "text", "c": "由第 19 題，AP∥BQ（皆平行 (7,24)）、|AP|=1、|BQ|=2。直線 BQ 過 B(−2,0)、方向 (7,24)，即 24x−7y+48=0："}, {"type": "math", "c": "d(A,BQ)=\\dfrac{|24(1)-0+48|}{\\sqrt{24^2+7^2}}=\\dfrac{72}{25}"}, {"type": "text", "c": "四邊形 PABQ 是上底 1、下底 2、高 72/25 的梯形："}, {"type": "math", "c": "\\text{面積}=\\dfrac12(1+2)\\cdot\\dfrac{72}{25}=\\dfrac{108}{25}"}, {"type": "text", "c": "故 A 到直線 BQ 距離 = 72/25、四邊形 PABQ 面積 = 108/25。（與官方一致）"}], "stem": "img/112_stem.png"}, {"subject": "B", "year": "112", "num": 1, "type": "單選", "rate": "46%", "img": "img/112B_q01.png", "answer": [{"t": "(1)"}], "key": "「與三次方成正比」就是 y=kx³（k>0）；轉速 x≥0，圖形從原點出發、往上且凹口向上。", "kaodian": [{"unit": "多項式函數", "title": "考點5 三次函數圖形與對稱中心", "url": "../concept-map/115學測數學_多項式函數.html#kp5"}], "steps": [{"type": "text", "c": "用電量與轉速的三次方成正比：y=kx³，k>0。"}, {"type": "text", "c": "x（轉速）≥0，y 隨 x 增大而增大，且是凹口向上（越來越陡）的曲線，通過原點附近。"}, {"type": "text", "c": "只有圖 (1) 符合 x³ 的形狀（先平緩再急升）。選 (1)。"}]}, {"subject": "B", "year": "112", "num": 2, "type": "單選", "rate": "68%", "img": "img/112B_q02.png", "answer": [{"t": "(2)　-4"}], "key": "左乘 [[0,1],[1,0]] 是「上下兩列對調」，右乘 [[1,0],[0,-2]] 是「第二行乘 -2」；對照就能讀出各元。", "kaodian": [{"unit": "矩陣", "title": "考點1 矩陣的意義、相等與乘法★★☆", "url": "../concept-map/115學測數學_矩陣.html#kp1"}, {"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）★★★ 必考", "url": "../concept-map/115學測數學_矩陣.html#kp5"}], "steps": [{"type": "text", "c": "左乘 [[0,1],[1,0]] 把矩陣的兩列對調 → [[c,d],[a,b]]；再右乘 [[1,0],[0,-2]] 把第二行乘 -2 → [[c,-2d],[a,-2b]]。"}, {"type": "math", "c": "\\begin{bmatrix}c & -2d\\\\ a & -2b\\end{bmatrix}=\\begin{bmatrix}3 & -4\\\\ -9 & -7\\end{bmatrix}"}, {"type": "text", "c": "對照：c=3、a=-9、-2d=-4→d=2、-2b=-7→b=7/2。所求 c-2b=3-2·(7/2)=3-7=-4。選 (2)。"}]}, {"subject": "B", "year": "112", "num": 3, "type": "單選", "rate": "56%", "img": "img/112B_q03.png", "answer": [{"t": "(4)　"}, {"m": "\\dfrac{150}{\\cos 22^\\circ}"}], "key": "繩索是斜邊，水平距離 150 是「鄰邊」，俯角 22° 是繩索與水平線的夾角：水平距離 = 繩長 × cos22°。", "kaodian": [{"unit": "三角", "title": "考點3 三角測量與平面幾何應用", "url": "../concept-map/115學測數學_三角.html#kp3"}], "steps": [{"type": "text", "c": "繩索從甲樓頂到乙樓頂，與水平線夾角（俯角）22°。水平距離 150 公尺是這條斜線的水平投影："}, {"type": "math", "c": "150=(\\text{繩長})\\times\\cos22^\\circ\\ \\Rightarrow\\ \\text{繩長}=\\dfrac{150}{\\cos22^\\circ}"}, {"type": "text", "c": "選 (4)。"}]}, {"subject": "B", "year": "112", "num": 4, "type": "單選", "rate": "70%", "img": "img/112B_q04.png", "answer": [{"t": "(3)　(41, 65, 79, 97)"}], "key": "先找出各百分位數對應第幾名（29×百分比，無條件進位）；前 15 名（第 15~29 名）各加 5，看哪幾個位置被加到。", "kaodian": [{"unit": "數據分析", "title": "考點4 加權平均、中位數與資料判讀", "url": "../concept-map/115學測數學_數據分析.html#kp4"}], "steps": [{"type": "text", "c": "29 人。百分位數位置：29×0.25=7.25→第 8 名、29×0.5→第 15 名、29×0.75→第 22 名、29×0.95→第 28 名。原值 41、60、74、92。"}, {"type": "text", "c": "成績最高前 15 名 = 第 15~29 名，各加 5 分。"}, {"type": "text", "c": "第 8 名不在其中 → 41 不變；第 15、22、28 名都在其中 → 60+5=65、74+5=79、92+5=97。"}, {"type": "text", "c": "(a,b,c,d)=(41,65,79,97)。選 (3)。"}]}, {"subject": "B", "year": "112", "num": 5, "type": "單選", "rate": "83%", "img": "img/112B_q05.png", "answer": [{"t": "(5)　號碼小於 10"}], "key": "在「符合條件的球」裡抽到 7 號，機率 = 1 ÷（符合條件的球數）；要機率最大，就找「含 7 號、但總數最少」的條件。", "kaodian": [{"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "../concept-map/115學測數學_排列組合與機率.html#kp4"}, {"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "../concept-map/115學測數學_排列組合與機率.html#kp3"}], "steps": [{"type": "text", "c": "已知條件成立時，抽到 7 號的條件機率 = 1 ÷（滿足條件的球數）。要最大 → 條件集合越小越好（且要含 7）。"}, {"type": "text", "c": "各條件的球數：奇數 50、質數 25、7 的倍數 14、非 5 的倍數 80、小於 10 只有 9 個。"}, {"type": "text", "c": "最小的是「小於 10」（9 個），條件機率 1/9 最大。選 (5)。"}]}, {"subject": "B", "year": "112", "num": 6, "type": "單選", "rate": "54%", "img": "img/112B_q06.png", "answer": [{"t": "(3)　0"}], "key": "算錯的 g÷f 餘式沒有 x² 項，代表 b=a²；正確 f÷g 的 x² 係數 p = a - b/a，代入 b=a² 就變 0。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "../concept-map/115學測數學_多項式函數.html#kp1"}], "steps": [{"type": "text", "c": "f、g 都是三次（a≠0）。g÷f 商式是 a，餘式 = g - a·f =(b-a²)x²+(c-ab)x+(d-ac)= -3x-17。"}, {"type": "text", "c": "比較沒有 x² 項 → b-a²=0，即 b=a²。"}, {"type": "text", "c": "正確的 f÷g：商式 1/a，餘式的 x² 係數 p = a - b/a = a - a²/a = a - a = 0。"}, {"type": "text", "c": "選 (3)。"}]}, {"subject": "B", "year": "112", "num": 7, "type": "單選", "rate": "30%", "img": "img/112B_q07.png", "answer": [{"t": "(4)　長短軸不相等的橢圓"}], "key": "光錐半角 30°。牆與軸夾角 = 半角 → 拋物線；牆、地板互相垂直，兩者與軸的夾角相加 90°，故地板與軸夾角 60°>半角 → 橢圓。", "kaodian": [], "steps": [{"type": "text", "c": "手電筒光錐張角 60°，半角 30°。截痕型態看「平面與軸的夾角」和半角比大小：等於半角 → 拋物線；大於 → 橢圓；小於 → 雙曲線。"}, {"type": "text", "c": "牆壁得到拋物線 → 牆與軸夾角 = 30°。牆與地板互相垂直、軸⊥交界線 L，故牆、地板與軸的夾角相加 =90°，地板與軸夾角 =60°。"}, {"type": "text", "c": "60°>30°（半角），且 ≠90°，故地板上是「長短軸不相等的橢圓」。選 (4)。"}]}, {"subject": "B", "year": "112", "num": 8, "type": "多選", "rate": "69%（全對率 59%）", "img": "img/112B_q08.png", "answer": [{"t": "(2)(4)"}], "key": "A 在偶數倍的 T 開始、B 在奇數倍的 T 開始；30 分鐘後開始播 B，代表 30 是 T 的「奇數倍」。", "kaodian": [{"unit": "數列與級數", "title": "考點4 級數求和與規律、週期", "url": "../concept-map/115學測數學_數列與級數.html#kp4"}], "steps": [{"type": "text", "c": "播放順序 A,B,A,B…，開始播 A 在時刻 0,2T,4T…（偶數倍 T），開始播 B 在 T,3T,5T…（奇數倍 T）。"}, {"type": "text", "c": "經過 30 分鐘剛好開始播 B → 30 =（奇數）×T，即 T 整除 30 且 30/T 為奇數。"}, {"type": "text", "c": "30 的奇數因數對應 T=2,6,10,30。選項中 (2)10（30/10=3）、(4)6（30/6=5）符合。答 (2)(4)。"}]}, {"subject": "B", "year": "112", "num": 9, "type": "多選", "rate": "39%（全對率 16%）", "img": "img/112B_q09.png", "answer": [{"t": "(3)(4)(5)"}], "key": "a=6、b=20/3 為有理數，c=2√10 為無理數，d 為有理數（可為 0）。判斷時記得 d 可以是任何有理數。", "kaodian": [{"unit": "數與式", "title": "考點1 實數系、數的分類與循環小數", "url": "../concept-map/115學測數學_數與式.html#kp1"}, {"unit": "數與式", "title": "考點3 數線上的點、距離、分點與根號估算", "url": "../concept-map/115學測數學_數與式.html#kp3"}], "steps": [{"type": "text", "c": "a=6、b=20/3 有理，c=2√10≈6.32 無理，d 有理。"}, {"type": "text", "c": "(3) 取 d=-6：|d-c|=|-6-2√10|=6+2√10，可能 ✓。"}, {"type": "text", "c": "(4) A、B 中點 =(6+20/3)/2=19/3；比較 (19/3)²=361/9≈40.1 > 40=(2√10)²，故中點在 C 右邊 ✓。"}, {"type": "text", "c": "(5) 與 B 距離<8 的範圍 (20/3-8, 20/3+8)=(-4/3, 44/3)：正整數 1~14 共 14 個、負整數只有 -1 共 1 個 ✓。"}, {"type": "text", "c": "(1) a+b+c+d 含 2√10 為無理 → 錯。(2) d 可為 0，abcd=0 有理 → 錯。答 (3)(4)(5)。"}]}, {"subject": "B", "year": "112", "num": 10, "type": "多選", "rate": "50%（全對率 35%）", "img": "img/112B_q10.png", "answer": [{"t": "(1)(5)"}], "key": "甲每 3 小時×2 → 甲(t)=X·2^((t-12)/3)；乙每 2 小時×2 → 乙(t)=Y·2^((t-12)/2)。18 點相同定出 X=2Y。", "kaodian": [{"unit": "指數與對數", "title": "考點5 指對數的應用：成長衰退模型與數列", "url": "../concept-map/115學測數學_指數與對數.html#kp5"}, {"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "../concept-map/115學測數學_指數與對數.html#kp1"}], "steps": [{"type": "text", "c": "甲(t)=X·2^((t-12)/3)、乙(t)=Y·2^((t-12)/2)。18 點：甲=X·2²=4X、乙=Y·2³=8Y，相同 → 4X=8Y → X=2Y。"}, {"type": "text", "c": "(1) X=2Y>Y ✓。"}, {"type": "text", "c": "(5) 24 點：甲=X·2⁴=16X=32Y、乙=Y·2⁶=64Y，乙=甲的 2 倍 ✓。"}, {"type": "text", "c": "(2) 13 點甲=X·2^(1/3)≠(4/3)X；(3) 15 點乙=Y·2^(3/2)=2√2·Y≠3Y；(4) 19 點乙/甲=2^(1/6)≠1.5，皆錯。答 (1)(5)。"}]}, {"subject": "B", "year": "112", "num": 11, "type": "多選", "rate": "29%（全對率 8%）", "img": "img/112B_q11.png", "answer": [{"t": "(1)(4)"}], "key": "圓與兩軸相切 → 半徑 = a = b；PA=√2(a-c)=a+c，由此得 (a+c)/(a-c)=√2，再逐一檢查。", "kaodian": [{"unit": "直線與圓", "title": "考點3 圓方程式與點的位置", "url": "../concept-map/115學測數學_直線與圓.html#kp3"}, {"unit": "直線與圓", "title": "考點4 直線與圓的位置：相切、弦長與切線", "url": "../concept-map/115學測數學_直線與圓.html#kp4"}], "steps": [{"type": "text", "c": "圓與兩坐標軸相切 → 圓心到兩軸距離都等於半徑，故 a=b=半徑（(1) 正確）。"}, {"type": "text", "c": "P(c,c) 到 A(a,a) 的距離 PA=√2(a-c)=a+c，得 (a+c)/(a-c)=√2。"}, {"type": "text", "c": "(4) b=a，故 (a+c)/(b-c)=(a+c)/(a-c)=√2 ✓。"}, {"type": "text", "c": "(2) P 在 x+y=2c≠0；(3) PA=a+c>a=半徑，P 在圓外；(5) a/c=(1+√2)/(√2-1)=3+2√2 而非 2+3√2，皆錯。答 (1)(4)。"}]}, {"subject": "B", "year": "112", "num": 12, "type": "多選", "rate": "28%（全對率 12%）", "img": "img/112B_q12.png", "answer": [{"t": "(1)(3)"}], "key": "經線是半個大圓（長 πR），赤道是整個大圓（2πR）；緯線圈半徑 = R·cos(緯度)。用圓心角量最短路徑。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "(1) 東經 0° 與 180° 兩條經線合起來剛好是一個大圓 = 赤道長，正確。"}, {"type": "text", "c": "(3) A→B 沿赤道 =60° 弧 = R·(π/3)；D（北緯30°）沿經線到北極 =(90°-30°)=60° 弧 = R·(π/3)，相等 ✓。"}, {"type": "text", "c": "(2) 北緯45°圈長/赤道 = cos45° = √2/2 ≠1/2 → 錯。(4) 北緯30°線半程 = πR·cos30° ≠ 2R·(π/3) → 錯。(5) 北極 N、A、C 三點兩兩距離都是 R√2（正三角形），故 N 看 A、C 的夾角 =60°≠90° → 錯。答 (1)(3)。"}]}, {"subject": "B", "year": "112", "num": 13, "type": "選填", "rate": "45%", "img": "img/112B_q13.png", "answer": [{"m": "\\dfrac{7}{3}"}], "key": "兩邊取 log 把乘冪變成一次方程：設 X=log a、Y=log b，解聯立。", "kaodian": [{"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "../concept-map/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "對 ab²=10⁵、a²b=10³ 兩邊取常用對數，設 X=log a、Y=log b："}, {"type": "math", "c": "\\begin{cases}X+2Y=5\\\\ 2X+Y=3\\end{cases}"}, {"type": "text", "c": "解得 Y=7/3，即 log b = 7/3。"}]}, {"subject": "B", "year": "112", "num": 14, "type": "選填", "rate": "38%", "img": "img/112B_q14.png", "answer": [{"t": "90"}], "key": "a<b<c 成等差 ⟺ 2b=a+c ⟺ a、c 同奇偶（b 自動是中點）；只要數 a、c 的同奇偶配對。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}, {"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "../concept-map/115學測數學_數列與級數.html#kp1"}], "steps": [{"type": "text", "c": "三數成等差且 a<b<c ⟺ b 是 a、c 的中點 ⟺ a、c 同奇偶（b=(a+c)/2 為整數）。"}, {"type": "text", "c": "1~20 中奇數 10 個、偶數 10 個。選同奇偶的兩數 (a<c)："}, {"type": "math", "c": "C(10,2)+C(10,2)=45+45=90"}, {"type": "text", "c": "答 90。"}]}, {"subject": "B", "year": "112", "num": 15, "type": "選填", "rate": "38%", "img": "img/112B_q15.png", "answer": [{"m": "2\\sqrt{2}"}], "key": "每一段長度都是 2，方向每步左轉 15°；P₂P₃ 是第 3 段、P₅P₆ 是第 6 段，兩方向差 (6-3)×15°=45°。", "kaodian": [{"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}], "steps": [{"type": "text", "c": "每段長 2。第 k 段（P_{k-1}P_k）方向 = 起始方向 +(k-1)×15°。"}, {"type": "text", "c": "P₂P₃ 是第 3 段（+2×15°=30°），P₅P₆ 是第 6 段（+5×15°=75°），兩者夾角 =45°。"}, {"type": "math", "c": "\\overrightarrow{P_2P_3}\\cdot\\overrightarrow{P_5P_6}=2\\times2\\times\\cos45^\\circ=2\\sqrt2"}, {"type": "text", "c": "答 2√2。"}]}, {"subject": "B", "year": "112", "num": 16, "type": "選填", "rate": "16%", "img": "img/112B_q16.png", "answer": [{"m": "\\dfrac{625}{24}"}], "key": "把 O 摺到 P，摺痕是 OP 的中垂線；摺進去的三角形就是「O 與摺痕和兩邊界交點」構成的直角三角形。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}, {"unit": "三角", "title": "考點6 三角形面積比、相似與角平分線", "url": "../concept-map/115學測數學_三角.html#kp6"}], "steps": [{"type": "text", "c": "設 O=(0,0)、左邊界為 y 軸、下邊界為 x 軸，P=(6,8)。摺痕是 OP 的中垂線：過中點 (3,4)、斜率 -3/4，即 y=-3/4 x+25/4。"}, {"type": "text", "c": "摺痕交下邊界 (y=0)：x=25/3；交左邊界 (x=0)：y=25/4。摺進去的直角三角形頂點 O、(25/3,0)、(0,25/4)："}, {"type": "math", "c": "\\text{面積}=\\dfrac12\\cdot\\dfrac{25}{3}\\cdot\\dfrac{25}{4}=\\dfrac{625}{24}"}, {"type": "text", "c": "答 625/24。"}]}, {"subject": "B", "year": "112", "num": 17, "type": "選填", "rate": "8%", "img": "img/112B_q17.png", "answer": [{"t": "108"}], "key": "換個角度算：對每個「相鄰位置」數有多少序列在那裡出現 00，再把所有位置加起來，比逐一列序列快。", "kaodian": [{"unit": "數列與級數", "title": "考點4 級數求和與規律、週期", "url": "../concept-map/115學測數學_數列與級數.html#kp4"}, {"unit": "排列組合與機率", "title": "考點1 計數原理與排列（有順序）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "長度 n 的序列有 n-1 個相鄰位置。固定某一個位置兩格都是 0，其餘 n-2 格自由（各 3 種）："}, {"type": "math", "c": "a(n)=(n-1)\\times 3^{\\,n-2}"}, {"type": "text", "c": "驗證 a(3)=2×3=6 ✓。所以"}, {"type": "math", "c": "a(5)=(5-1)\\times3^{3}=4\\times27=108"}, {"type": "text", "c": "答 108。"}]}, {"subject": "B", "year": "112", "num": 18, "type": "混合題（選填 3 分）", "rate": "56%", "img": "img/112B_q18.png", "answer": [{"m": "k=\\dfrac{1}{2}"}], "key": "先求消失點 P=L∩M；電線桿都與 y 軸平行，桿高 =3-3y，用 A₃B₃=2·A₁B₁ 解出 A₃，再比 PA₁、PA₃。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "P=L∩M：x+3y=0 與 2x-3y+9=0，相加 3x+9=0→x=-3、y=1，故 P=(-3,1)。"}, {"type": "text", "c": "桿與 y 軸平行，底座 (x,y) 在 L（x=-3y）、頂端在 M，桿高 =3-3y。A₁ 桿高 3，A₃ 桿高 =6 → 3-3y₃=6→y₃=-1，A₃=(3,-1)。"}, {"type": "math", "c": "\\overrightarrow{PA_1}=(3,-1),\\ \\overrightarrow{PA_3}=(6,-2)\\Rightarrow \\overrightarrow{PA_1}=\\tfrac12\\overrightarrow{PA_3}"}, {"type": "text", "c": "故 k=1/2。"}], "stem": "img/112B_stem.png"}, {"subject": "B", "year": "112", "num": 19, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/112B_q19.png", "answer": [{"t": "P=(-3,1)，B₃=(3,5)"}], "key": "P 是 L、M 的交點；B₃ 與 A₃ 同 x（桿鉛直），代入 M 求出 B₃ 的 y。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "P=L∩M=(-3,1)（如第 18 題）。"}, {"type": "text", "c": "A₃=(3,-1)，桿與 y 軸平行故 B₃ 的 x=3，代入 M：2(3)-3y+9=0 → y=5，得 B₃=(3,5)。"}, {"type": "math", "c": "P=(-3,1),\\quad B_3=(3,5)"}], "stem": "img/112B_stem.png"}, {"subject": "B", "year": "112", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/112B_q20.png", "answer": [{"t": "Q=(1,1)"}], "key": "先由「A₁B₃ 與 A₃B₁ 交點在 A₂B₂ 上」定出中間桿 x=1，得 A₂、B₂；Q 為 A₂B₂ 上 1:2 的分點。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "A₁B₃（過 (0,0)、(3,5)）與 A₃B₁（過 (3,-1)、(0,3)）的交點為 (1, 5/3)，其 x=1 即中間桿位置，故 A₂、B₂ 的 x=1。"}, {"type": "text", "c": "A₂ 在 L：x=1→y=-1/3，A₂=(1,-1/3)；B₂ 在 M：x=1→y=11/3，B₂=(1,11/3)。"}, {"type": "text", "c": "Q 到 A₂ 與到 B₂ 長度比 1:2 → Q 是 A₂B₂ 的 1/3 分點："}, {"type": "math", "c": "Q_y=-\\tfrac13+\\tfrac13\\left(\\tfrac{11}{3}+\\tfrac13\\right)=-\\tfrac13+\\tfrac43=1,\\quad Q=(1,1)"}], "stem": "img/112B_stem.png"}, {"subject": "A", "year": "113", "num": 1, "type": "單選", "rate": "89%", "img": "img/113_q01.png", "answer": [{"t": "(2)"}], "key": "「2 小時剩一半」＝半衰期 2 小時，故 t 小時後剩 (1/2)^(t/2)。", "kaodian": [{"unit": "指數與對數", "title": "考點5 指對數的應用：成長衰退模型與數列", "url": "../concept-map/115學測數學_指數與對數.html#kp5"}, {"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "../concept-map/115學測數學_指數與對數.html#kp1"}], "steps": [{"type": "text", "c": "藥量每 2 小時變成一半，所以 t 小時後剩下 (1/2)^(t/2) 倍。"}, {"type": "math", "c": "4\\text{ 小時}:\\ \\left(\\tfrac12\\right)^{4/2}=\\left(\\tfrac12\\right)^{2}=\\dfrac14"}, {"type": "text", "c": "其餘：3 小時剩 √2/4、6 小時剩 1/8、8 小時剩 1/16、10 小時剩 1/32，都不符。"}, {"type": "text", "c": "只有「4 小時後剩 1/4」正確，選 (2)。"}]}, {"subject": "A", "year": "113", "num": 2, "type": "單選", "rate": "57%", "img": "img/113_q02.png", "answer": [{"t": "(5)　"}, {"m": "\\vec{OE}"}], "key": "外積垂直於相乘的兩向量；在正方體中比對哪個選項與它同方向。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "../concept-map/115學測數學_空間向量.html#kp3"}, {"unit": "空間向量", "title": "考點1 空間坐標、距離與正立方體", "url": "../concept-map/115學測數學_空間向量.html#kp1"}], "steps": [{"type": "text", "c": "設邊長 1，依圖 D 在 O 上方、E 在 A 上方…取 A=(0,1,0)、D=(0,0,1)、G=(1,0,1)。"}, {"type": "math", "c": "\\vec{AD}\\times\\vec{AG}=(0,-1,1)\\times(1,-1,1)=(0,1,1)"}, {"type": "text", "c": "逐一比對五個選項，只有 OE = E−O = (0,1,1) 與它平行。故選 (5)。"}]}, {"subject": "A", "year": "113", "num": 3, "type": "單選", "rate": "31%", "img": "img/113_q03.png", "answer": [{"t": "(1)　1 個"}], "key": "三根成等差 −7, −7+a, −7+2a，寫出 f 後看 f(0) 的正負。", "kaodian": [{"unit": "多項式函數", "title": "考點4 高次方程式：有理根、勘根定理與奇偶函數", "url": "../concept-map/115學測數學_多項式函數.html#kp4"}, {"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "../concept-map/115學測數學_數列與級數.html#kp1"}], "steps": [{"type": "text", "c": "三根為 −7、−7+a、−7+2a，最高次係數 a，故："}, {"type": "math", "c": "f(x)=a(x+7)(x+7-a)(x+7-2a)\\Rightarrow f(0)=a\\cdot 7\\cdot(7-a)(7-2a)"}, {"type": "text", "c": "逐一代 a∈{−6,−4,−2,2,4,6}：只有 a=2 時 f(0)=2·7·5·3>0，其餘皆 <0。"}, {"type": "text", "c": "故只有 1 個 a 使 f(0)>0，選 (1)。"}]}, {"subject": "A", "year": "113", "num": 4, "type": "單選", "rate": "39%", "img": "img/113_q04.png", "answer": [{"t": "(2)　2 個"}], "key": "把式子整理成 sin(x+π/6)−sin x = 1/2，用和差化積變成一個 cos = 定值。", "kaodian": [{"unit": "三角", "title": "考點5 和差角與倍角（解方程與不等式）", "url": "../concept-map/115學測數學_三角.html#kp5"}, {"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "原式即 sin(x+π/6)−sin x = sin(π/6)=1/2。左邊用和差化積："}, {"type": "math", "c": "2\\cos\\!\\left(x+\\tfrac{\\pi}{12}\\right)\\sin\\tfrac{\\pi}{12}=\\tfrac12\\Rightarrow \\cos\\!\\left(x+\\tfrac{\\pi}{12}\\right)=\\dfrac{1}{4\\sin\\frac{\\pi}{12}}"}, {"type": "text", "c": "右邊是介於 0 與 1 的定值，在 0≤x<2π 內 cos 等於此值恰有 2 個解（x=0 與 x=11π/6）。選 (2)。"}]}, {"subject": "A", "year": "113", "num": 5, "type": "單選", "rate": "35%", "img": "img/113_q05.png", "answer": [{"t": "(4)　"}, {"m": "\\left(\\binom{24}{12}\\right)^2"}], "key": "中位數是第 13 個數；兩中位數差 1 只能是 25、26，前後各分 12 個。", "kaodian": [{"unit": "數據分析", "title": "考點1 一維數據：平均、中位數與標準差", "url": "../concept-map/115學測數學_數據分析.html#kp1"}, {"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}], "steps": [{"type": "text", "c": "每組 25 個，中位數是第 13 小。設甲中位數 m、乙中位數 m+1。"}, {"type": "text", "c": "小於 m 的數要 12 個給甲、12 個給乙 → 共 24 個 → m−1=24 → m=25、乙中位數 26。"}, {"type": "text", "c": "於是 1~24（24 個）選 12 個給甲、27~50（24 個）選 12 個給甲，25→甲、26→乙固定："}, {"type": "math", "c": "\\binom{24}{12}\\times\\binom{24}{12}=\\left(\\binom{24}{12}\\right)^2"}, {"type": "text", "c": "故選 (4)。"}]}, {"subject": "A", "year": "113", "num": 6, "type": "單選", "rate": "44%", "img": "img/113_q06.png", "answer": [{"t": "(3)　5 公里"}], "key": "由對稱得 AP=BP 求 cosθ；再用半角公式算 cos(θ/2)，代距離公式。", "kaodian": [{"unit": "三角", "title": "考點3 三角測量與平面幾何應用", "url": "../concept-map/115學測數學_三角.html#kp3"}, {"unit": "三角", "title": "考點5 和差角與倍角", "url": "../concept-map/115學測數學_三角.html#kp5"}], "steps": [{"type": "text", "c": "設 B 為原點、A=(7,0)。A、B 對稱地命中 P，得 AP=BP=7/(2cosθ)=9 → cosθ=7/18。"}, {"type": "text", "c": "用半角：2cos²(θ/2)−1=7/18 → cos(θ/2)=5/6。A 改射西偏北 θ/2、AQ=9，故 Q=(7−9cos(θ/2), 9sin(θ/2))："}, {"type": "math", "c": "\\overline{BQ}=\\sqrt{\\left(7-9\\cos\\tfrac{\\theta}{2}\\right)^2+\\left(9\\sin\\tfrac{\\theta}{2}\\right)^2}=\\sqrt{130-126\\cos\\tfrac{\\theta}{2}}=\\sqrt{130-105}=5"}, {"type": "text", "c": "故 BQ=5 公里，選 (3)。"}]}, {"subject": "A", "year": "113", "num": 7, "type": "多選", "rate": "47%（全對率 8%）", "img": "img/113_q07.png", "answer": [{"t": "(3)(4)"}], "key": "化簡後比對「定義域」是否與 y=log x（x>0）完全一樣。", "kaodian": [{"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "../concept-map/115學測數學_指數與對數.html#kp2"}, {"unit": "指數與對數", "title": "考點4 指數與對數函數的圖形", "url": "../concept-map/115學測數學_指數與對數.html#kp4"}], "steps": [{"type": "text", "c": "(1) y=log(5x)−1/2=log x+(log5−1/2)，因 log5−1/2≠0 → 整條上下平移，不同，錯。"}, {"type": "text", "c": "(2) 2y=log(x²) → y=log|x|，多了 x<0 的分支 → 不同，錯。"}, {"type": "text", "c": "(3) 3y=log(x³)：需 x>0，且 (1/3)·3log x=log x → 完全相同，對。"}, {"type": "text", "c": "(4) x=10^y 即 y=log x → 同一條曲線，對。"}, {"type": "math", "c": "(5)\\ x^3=10^{(y^3)}\\Rightarrow 3\\log x=y^3\\Rightarrow y=\\sqrt[3]{3\\log x}\\neq \\log x\\ (\\text{錯})"}, {"type": "text", "c": "故選 (3)(4)。"}]}, {"subject": "A", "year": "113", "num": 8, "type": "多選", "rate": "66%（全對率 43%）", "img": "img/113_q08.png", "answer": [{"t": "(2)(3)"}], "key": "最大角看餘弦定理；周長是等差；面積用海龍公式判斷遞增。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "../concept-map/115學測數學_三角.html#kp2"}, {"unit": "三角", "title": "考點6 三角形面積比、相似與角平分線", "url": "../concept-map/115學測數學_三角.html#kp6"}, {"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "../concept-map/115學測數學_數列與級數.html#kp1"}], "steps": [{"type": "text", "c": "(1) 最大邊 n+2 對的角由 n²+(n+1)²−(n+2)²=(n−3)(n+1) 判斷：n=2 鈍角、n=3 直角，不全銳角，錯。"}, {"type": "text", "c": "(2) 周長 = 3n+3，每次加 3 → 等差，對。"}, {"type": "math", "c": "(3)\\ \\text{面積}=\\tfrac14(n+1)\\sqrt{3(n+3)(n-1)}\\ \\text{隨 }n\\text{ 遞增（對）}"}, {"type": "text", "c": "(4) T₅(5,6,7) 三高 = 2A/5, 2A/6, 2A/7，比 1/5,1/6,1/7 不成等差，錯。"}, {"type": "text", "c": "(5) 邊越接近正三角形最大角越小：T₃ 最大角 90° < T₂ 最大角(≈104.5°)，錯。故選 (2)(3)。"}]}, {"subject": "A", "year": "113", "num": 9, "type": "多選", "rate": "36%（全對率 12%）", "img": "img/113_q09.png", "answer": [{"t": "(3)"}], "key": "迴歸線過 (x̄,ȳ) 求平均；斜率 = r·(σ_y/σ_x) 反推體重標準差。", "kaodian": [{"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "../concept-map/115學測數學_數據分析.html#kp3"}, {"unit": "數據分析", "title": "考點2 相關係數 r", "url": "../concept-map/115學測數學_數據分析.html#kp2"}], "steps": [{"type": "text", "c": "迴歸線過 (x̄,ȳ)：ȳ_A=2(5.2)−0.6=9.8、ȳ_B=1.5(6)+0.4=9.4，故 (1) ȳ_A<ȳ_B 錯。"}, {"type": "text", "c": "斜率=r·(σ_y/σ_x)：A 得 σ_yA=1、B 得 σ_yB=0.5，σ_yA>σ_yB，(2) 錯。"}, {"type": "math", "c": "(3)\\ |8.6-\\overline{y_A}|=|8.6-9.8|=1.2>1=\\sigma_{yA}\\ (\\text{對})"}, {"type": "text", "c": "(4) P 到 L_A 距離 2/√5≈0.89 > 到 L_B 距離 ≈0.11，錯。"}, {"type": "text", "c": "(5) P 到 A 中心 √1.6 > 到 B 中心 √0.8，錯。故只選 (3)。"}]}, {"subject": "A", "year": "113", "num": 10, "type": "多選", "rate": "45%（全對率 23%）", "img": "img/113_q10.png", "answer": [{"t": "(3)(5)"}], "key": "P 到 x 軸距離 2√3 = 正六邊形的邊心距 → 邊長 4；再逐一算向量與斜率。", "kaodian": [{"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "../concept-map/115學測數學_直線與圓.html#kp2"}, {"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "../concept-map/115學測數學_平面向量.html#kp1"}], "steps": [{"type": "text", "c": "正方形邊 6、一邊在 x 軸上 → 中心 A 高 3。正六邊形右頂點高 = 邊心距 (s√3)/2 = 2√3 → 邊長 s=4，且 P 為六邊形右頂點落在正方形左邊上。"}, {"type": "math", "c": "\\vec{BA}=(a_x-b_x,\\ 3-2\\sqrt3)=(7,\\ 3-2\\sqrt3)\\ ((3)\\ \\text{對})"}, {"type": "text", "c": "(1) A 高 3 < B 高 2√3≈3.46，錯。(2) 六邊形邊長為 4 不是 6，錯。"}, {"type": "math", "c": "(4)\\ \\overline{AP}=\\sqrt{30-12\\sqrt3}\\approx3.04<\\sqrt{10}\\ (\\text{錯});\\ (5)\\ \\text{斜率}=\\dfrac{2\\sqrt3-3}{-3}\\approx-0.15>-\\tfrac{1}{\\sqrt3}\\ (\\text{對})"}, {"type": "text", "c": "故選 (3)(5)。（見右圖）"}], "fig": "img/113_fig_q10.png"}, {"subject": "A", "year": "113", "num": 11, "type": "多選", "rate": "43%（全對率 25%）", "img": "img/113_q11.png", "answer": [{"t": "(2)(3)"}], "key": "行列式 ab−6 判斷解的個數；把 12 種等可能 (a,b) 分類數機率。", "kaodian": [{"unit": "矩陣", "title": "考點4 一次聯立方程式與高斯消去法", "url": "../concept-map/115學測數學_矩陣.html#kp4"}, {"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "../concept-map/115學測數學_排列組合與機率.html#kp4"}], "steps": [{"type": "text", "c": "係數行列式 = ab−6。≠0 有唯一解；=0 時 (a,b)=(6,1) 無限多解、(3,2) 無解。共 6×2=12 種等可能。"}, {"type": "text", "c": "(2) 無解只有 (3,2) → 1/12，對。(3) 唯一解 = 12−2=10 種 → 5/6，對。"}, {"type": "text", "c": "(1) a=b 只有 (1,1),(2,2) → 2/12=1/6≠1/3，錯。(4) 反面(b=2)且有解 = a≠3 共 5 種 → 5/12≠1/2，錯。"}, {"type": "math", "c": "(5)\\ x=\\dfrac{3}{a-3},\\ x>0\\Leftrightarrow a>3\\Rightarrow P=\\dfrac{3}{5}\\neq\\dfrac{2}{5}\\ (\\text{錯})"}, {"type": "text", "c": "故選 (2)(3)。"}]}, {"subject": "A", "year": "113", "num": 12, "type": "多選", "rate": "36%（全對率 11%）", "img": "img/113_q12.png", "answer": [{"t": "(2)(4)(5)"}], "key": "T 的行列式 = 3 固定 → 面積固定；可逆 → 有原像；不變點在 x=0。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "../concept-map/115學測數學_矩陣.html#kp5"}, {"unit": "矩陣", "title": "考點1 矩陣的意義、相等與乘法", "url": "../concept-map/115學測數學_矩陣.html#kp1"}], "steps": [{"type": "text", "c": "T(x,y)=(3x, ax+y)。A(1,0)→(3,a)、B(0,1)→(0,1)、C(−1,0)→(−3,−a)。"}, {"type": "text", "c": "(1) a=0 得三角形 (3,0),(0,1),(−3,0)，等腰但非直角，錯。"}, {"type": "text", "c": "(2) 不變點須 3x=x → x=0；△ABC 上有 B(0,1) 及 (0,0)（邊 AC 上）兩點不動 → 對。"}, {"type": "text", "c": "(3) a>0 時圖形在 x>0 的部分 y>0，不進第四象限 →「必有」錯。"}, {"type": "math", "c": "(4)\\ \\det T=3\\neq0\\ \\text{可逆}\\Rightarrow \\Omega=T^{-1}(\\triangle ABC)\\ \\text{存在（對）};\\quad (5)\\ \\text{面積}=|\\det T|\\times1=3\\ \\text{（定值，對）}"}, {"type": "text", "c": "故選 (2)(4)(5)。"}]}, {"subject": "A", "year": "113", "num": 13, "type": "選填", "rate": "67%", "img": "img/113_q13.png", "answer": [{"t": "選填　"}, {"m": "A:B:C=2:3:5"}], "key": "用兩個加權平均列式解出比例。", "kaodian": [{"unit": "數據分析", "title": "考點4 加權平均、中位數與資料判讀", "url": "../concept-map/115學測數學_數據分析.html#kp4"}], "steps": [{"type": "text", "c": "甲乙平均 280：(100A+400B)/(A+B)=280 → 120B=180A → A:B=2:3。設 A=2k、B=3k。"}, {"type": "text", "c": "三型平均 260：100A+400B+240C=260(A+B+C)，代入得 100k=20C → C=5k。"}, {"type": "math", "c": "A:B:C=2k:3k:5k=2:3:5"}, {"type": "text", "c": "故比為 2:3:5。"}]}, {"subject": "A", "year": "113", "num": 14, "type": "選填", "rate": "38%", "img": "img/113_q14.png", "answer": [{"t": "選填　"}, {"m": "a=-3,\\ b=3"}], "key": "用 x²≡2x−3 把每一項降次，湊出係數全為 0。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "../concept-map/115學測數學_多項式函數.html#kp1"}], "steps": [{"type": "text", "c": "餘式：f≡x+1、g≡x−3、h≡−2；又 x²≡2x−3（mod x²−2x+3）。"}, {"type": "math", "c": "xf(x)\\equiv x(x+1)=x^2+x\\equiv(2x-3)+x=3x-3"}, {"type": "text", "c": "故 xf+ag+bh ≡ (3+a)x+(−3−3a−2b)。要被整除須係數皆 0："}, {"type": "math", "c": "3+a=0,\\ -3-3a-2b=0\\Rightarrow a=-3,\\ b=3"}, {"type": "text", "c": "故 a=−3、b=3。"}]}, {"subject": "A", "year": "113", "num": 15, "type": "選填", "rate": "48%", "img": "img/113_q15.png", "answer": [{"t": "選填　"}, {"m": "25"}], "key": "中獎率 0.4% 反推球數 2500；算第 101 人抽到「剩餘幸運球」的期望。", "kaodian": [{"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp6"}, {"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "../concept-map/115學測數學_排列組合與機率.html#kp3"}], "steps": [{"type": "text", "c": "中獎機率 10/N=0.4% → N=2500 顆球（10 顆幸運）。前 100 人已抽走 1 顆 5000、0 顆 8000。"}, {"type": "text", "c": "剩 2500−100=2400 顆，其中 5000 券 4 顆、8000 券 5 顆。第 101 人抽 1 顆："}, {"type": "math", "c": "E=5000\\cdot\\dfrac{4}{2400}+8000\\cdot\\dfrac{5}{2400}=\\dfrac{60000}{2400}=25"}, {"type": "text", "c": "期望值 25 元。"}]}, {"subject": "A", "year": "113", "num": 16, "type": "選填", "rate": "8%", "img": "img/113_q16.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{2\\sqrt5}{5}"}], "key": "(2,−3) 與 (3,2) 互相垂直、長皆 √13；兩投影長是 L−1、L−2，用畢氏解 L。", "kaodian": [{"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}, {"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "../concept-map/115學測數學_平面向量.html#kp1"}], "steps": [{"type": "text", "c": "(2,−3)⊥(3,2)、長皆 √13。v 在兩方向的投影長分別是 L−1、L−2（L=|v|）。因兩方向垂直："}, {"type": "math", "c": "L^2=(L-1)^2+(L-2)^2\\Rightarrow L^2-6L+5=0\\Rightarrow L=5\\ (L=1\\ \\text{使投影為負，不合})"}, {"type": "text", "c": "故 v = 4·(2,−3)/√13 + 3·(3,2)/√13 = (17,−6)/√13。在 (4,7) 方向的投影長："}, {"type": "math", "c": "\\dfrac{\\vec{v}\\cdot(4,7)}{|(4,7)|}=\\dfrac{26/\\sqrt{13}}{\\sqrt{65}}=\\dfrac{2}{\\sqrt5}=\\dfrac{2\\sqrt5}{5}"}]}, {"subject": "A", "year": "113", "num": 17, "type": "選填", "rate": "5%", "img": "img/113_q17.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{1}{3}"}], "key": "「到 P 距離 |x−y| 的所有點」是一個圓；圓要落在正方形內，等於「半徑 ≤ P 到四邊的最短距離」。", "kaodian": [{"unit": "直線與圓", "title": "考點5 平面區域與線性規劃", "url": "../concept-map/115學測數學_直線與圓.html#kp5"}, {"unit": "數與式", "title": "考點2 絕對值的意義、方程式與不等式", "url": "../concept-map/115學測數學_數與式.html#kp2"}], "steps": [{"type": "text", "c": "到 P 距離 |x−y| 的所有點 = 以 P 為圓心、半徑 r=|x−y| 的圓。圓落在正方形內，就是要："}, {"type": "math", "c": "|x-y|\\le \\min(x,\\,1-x,\\,y,\\,1-y)"}, {"type": "text", "c": "由 x、y 對稱，先看 x≥y 的一半（此時 |x−y|=x−y）。四個不等式化簡後，有效的是 y≥x/2、y≥2x−1，再加上 y≤x："}, {"type": "math", "c": "\\dfrac{x}{2}\\le y\\le x,\\quad y\\ge 2x-1"}, {"type": "text", "c": "這塊剛好是頂點 (0,0)、(2/3, 1/3)、(1,1) 的三角形（三邊分別落在 y=x/2、y=2x−1、y=x 上）。用坐標三角形面積公式："}, {"type": "math", "c": "\\text{面積}=\\dfrac12\\left|\\,0\\!\\left(\\tfrac13-1\\right)+\\tfrac23(1-0)+1\\!\\left(0-\\tfrac13\\right)\\right|=\\dfrac16"}, {"type": "text", "c": "另一半 (x≤y) 由對稱也是 1/6，故區域 R 的面積："}, {"type": "math", "c": "2\\times\\dfrac16=\\dfrac13"}, {"type": "text", "c": "（見右圖）"}], "fig": "img/113_fig_q17.png"}, {"subject": "A", "year": "113", "num": 18, "type": "混合題（單選 3 分）", "rate": "64%", "img": "img/113_q18.png", "answer": [{"t": "(4)　"}, {"m": "\\dfrac{\\sqrt2}{2}"}], "key": "投影點沿法向量方向；求 OQ 與 x 軸的夾角餘弦。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "../concept-map/115學測數學_空間向量.html#kp4"}, {"unit": "空間向量", "title": "考點2 空間向量的內積、夾角與垂直", "url": "../concept-map/115學測數學_空間向量.html#kp2"}], "steps": [{"type": "text", "c": "E: x−z=4，法向量 (1,0,−1)。O 沿法向量投影到 E：Q=(t,0,−t)，代入 x−z=4 → 2t=4 → Q=(2,0,−2)。"}, {"type": "math", "c": "\\cos\\alpha=\\dfrac{\\vec{OQ}\\cdot(1,0,0)}{|\\vec{OQ}|}=\\dfrac{2}{\\sqrt{8}}=\\dfrac{\\sqrt2}{2}"}, {"type": "text", "c": "故選 (4)。"}], "stem": "img/113_stem.png"}, {"subject": "A", "year": "113", "num": 19, "type": "非選擇題（4 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/113_q19.png", "answer": [{"t": "非選　"}, {"m": "a^2\\ge 3(b^2+c^2)"}], "key": "θ≤π/6 使 cosθ≥√3/2，兩邊為正平方後整理。", "kaodian": [{"unit": "空間向量", "title": "考點2 空間向量的內積、夾角與垂直", "url": "../concept-map/115學測數學_空間向量.html#kp2"}, {"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "../concept-map/115學測數學_空間向量.html#kp4"}], "steps": [{"type": "text", "c": "OP=(a,b,c) 與 (1,0,0) 夾角 θ≤π/6，cos 在 [0,π/2] 遞減，故："}, {"type": "math", "c": "\\cos\\theta=\\dfrac{a}{\\sqrt{a^2+b^2+c^2}}\\ge\\cos\\dfrac{\\pi}{6}=\\dfrac{\\sqrt3}{2}"}, {"type": "text", "c": "兩邊為正，平方：a²/(a²+b²+c²)≥3/4 → 4a²≥3(a²+b²+c²)，整理得"}, {"type": "math", "c": "a^2\\ge 3(b^2+c^2)"}, {"type": "text", "c": "得證。（與官方參考答案一致）"}], "stem": "img/113_stem.png"}, {"subject": "A", "year": "113", "num": 20, "type": "非選擇題（8 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/113_q20.png", "answer": [{"t": "非選　"}, {"m": "2-2\\sqrt3\\le c\\le 2+2\\sqrt3"}, {"t": "、最小 "}, {"m": "\\overline{OP}=4\\sqrt3-4"}], "key": "在 E 上 a−c=4、b=0 代入不等式解 c 範圍；OP 配方求最小。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "../concept-map/115學測數學_空間向量.html#kp4"}, {"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "../concept-map/115學測數學_多項式函數.html#kp2"}], "steps": [{"type": "text", "c": "P 在 E 上 → a−c=4（a=c+4）、b=0。代入 a²≥3(b²+c²)=3c²："}, {"type": "math", "c": "(c+4)^2\\ge 3c^2\\Rightarrow c^2-4c-8\\le0\\Rightarrow 2-2\\sqrt3\\le c\\le 2+2\\sqrt3"}, {"type": "text", "c": "這就是 c 的可能範圍。再看 OP 長度："}, {"type": "math", "c": "\\overline{OP}=\\sqrt{a^2+c^2}=\\sqrt{(c+4)^2+c^2}=\\sqrt{2(c+2)^2+8}"}, {"type": "text", "c": "拋物線頂點 c=−2 不在範圍內，故最小發生在左端 c=2−2√3："}, {"type": "math", "c": "\\overline{OP}_{\\min}=\\sqrt{64-32\\sqrt3}=4\\sqrt3-4"}, {"type": "text", "c": "故 c∈[2−2√3, 2+2√3]、OP 最小長度 = 4√3−4 = 4(√3−1)。（與官方一致）"}], "stem": "img/113_stem.png"}, {"subject": "B", "year": "113", "num": 1, "type": "單選", "rate": "58%", "img": "img/113B_q01.png", "answer": [{"t": "(4)　19"}], "key": "共 210 筆資料（值 k 出現 k 次）；第 90 百分位數先算位置 210×0.9=189，落在哪個值。", "kaodian": [{"unit": "數據分析", "title": "考點4 加權平均、中位數與資料判讀", "url": "../concept-map/115學測數學_數據分析.html#kp4"}], "steps": [{"type": "text", "c": "資料共 1+2+…+20=210 筆，值 k 出現 k 次。累積到值 k 的筆數 = k(k+1)/2。"}, {"type": "text", "c": "第 90 百分位數位置 = 210×0.9 = 189（整數，取第 189 與第 190 筆的平均）。"}, {"type": "text", "c": "值 18 累積到 18·19/2=171 筆，值 19 累積到 19·20/2=190 筆，故第 172~190 筆都是 19。"}, {"type": "text", "c": "第 189、190 筆都是 19，平均仍是 19。選 (4)。"}]}, {"subject": "B", "year": "113", "num": 2, "type": "單選", "rate": "49%", "img": "img/113B_q02.png", "answer": [{"t": "(1)　c<0<b<1"}], "key": "1<a<10 → b=log a 介於 0 與 1；再取一次對數 c=log b，對「小於 1 的正數」取 log 會變負。", "kaodian": [{"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "../concept-map/115學測數學_指數與對數.html#kp2"}, {"unit": "指數與對數", "title": "考點4 指數與對數函數的圖形", "url": "../concept-map/115學測數學_指數與對數.html#kp4"}], "steps": [{"type": "text", "c": "a 在 1 與 10 之間，取常用對數：b=log a 介於 log1=0 與 log10=1，即 0<b<1。"}, {"type": "text", "c": "再取一次：c=log b。因 0<b<1，log（小於1的正數）為負，故 c<0。"}, {"type": "text", "c": "合起來 c<0<b<1。選 (1)。"}]}, {"subject": "B", "year": "113", "num": 3, "type": "單選", "rate": "70%", "img": "img/113B_q03.png", "answer": [{"t": "(2)　(7,3)"}], "key": "射線 Q→P(12,10) 不能碰到兩面牆；檢查射線在牆高度 y=6、y=5 時的 x 是否落在牆的範圍內。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "牆 2 在 y=6、x∈[0,9]；牆 1 在 y=5、x∈[10,15]。射線從 Q 到 P(12,10)，在高度 y 的 x 座標可用比例算。"}, {"type": "text", "c": "檢查 (2) Q=(7,3)：射線在 y=6 時 x=7+(12-7)·(6-3)/(10-3)=7+15/7≈9.14>9，避開牆 2；"}, {"type": "text", "c": "在 y=5 時 x=7+5·(5-3)/7=7+10/7≈8.43<10，避開牆 1。兩牆都不擋，可行。"}, {"type": "text", "c": "其餘選項會被其中一牆擋住。選 (2)。"}]}, {"subject": "B", "year": "113", "num": 4, "type": "單選", "rate": "26%", "img": "img/113B_q04.png", "answer": [{"t": "(4)　5"}], "key": "AB 的每個分量都落在 [-1,1]；把 v+AB 兩個分量各自推到極端，再算長度。", "kaodian": [{"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "../concept-map/115學測數學_平面向量.html#kp1"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}], "steps": [{"type": "text", "c": "A、B 的座標都在 [0,1]，故 AB=B-A 的每個分量都在 [-1,1]。"}, {"type": "math", "c": "\\vec{v}+\\vec{AB}=(-2+(b_1-a_1),\\ 3+(b_2-a_2))"}, {"type": "text", "c": "第一分量 -2+(在[-1,1]) ∈[-3,-1]，絕對值最大 3；第二分量 3+(在[-1,1]) ∈[2,4]，最大 4。"}, {"type": "math", "c": "\\left|\\vec{v}+\\vec{AB}\\right|_{\\max}=\\sqrt{3^2+4^2}=5"}, {"type": "text", "c": "選 (4)。"}]}, {"subject": "B", "year": "113", "num": 5, "type": "單選", "rate": "45%", "img": "img/113B_q05.png", "answer": [{"t": "(3)　3"}], "key": "f(x-2)=f(-x-2) 表示對稱軸 x=-2 → b=4；在 [-3,1] 上最小值在頂點、最大值在離頂點較遠的端點 x=1。", "kaodian": [{"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "../concept-map/115學測數學_多項式函數.html#kp2"}], "steps": [{"type": "text", "c": "對稱軸 x=-2（由 f(x-2)=f(-x-2)）→ -b/2=-2 → b=4，f(x)=x²+4x+c，頂點在 x=-2。"}, {"type": "text", "c": "在 [-3,1] 上：最小值 f(-2)=c-4；最大值在離 -2 較遠的端點 x=1，f(1)=c+5。"}, {"type": "math", "c": "\\text{最大}=4\\times\\text{最小}:\\ c+5=4(c-4)\\Rightarrow c=7"}, {"type": "text", "c": "最小值 = c-4 = 3。選 (3)。"}]}, {"subject": "B", "year": "113", "num": 6, "type": "單選", "rate": "37%", "img": "img/113B_q06.png", "answer": [{"t": "(1)　"}, {"m": "\\dfrac{1}{7}"}], "key": "用相似三角形：截線長與樓地板長的比 = 該層到 P 的深度 ÷ 底邊到 P 的深度。先由 1/3 定出間距關係。", "kaodian": [{"unit": "三角", "title": "考點3 三角測量與平面幾何應用", "url": "../concept-map/115學測數學_三角.html#kp3"}], "steps": [{"type": "text", "c": "設 P 到五樓地板深度為 s，各層等距 h。三角形 PAB 底邊（四樓地板）在深度 s+h，在深度 y 的截線長 = 樓地板長 × y/(s+h)。"}, {"type": "text", "c": "五樓地板在 △PAB 截出 1/3：s/(s+h)=1/3 → h=2s。"}, {"type": "text", "c": "△PEF 底邊（二樓地板）在深度 s+3h = s+6s = 7s。五樓地板（深度 s）截出："}, {"type": "math", "c": "\\dfrac{s}{7s}=\\dfrac{1}{7}"}, {"type": "text", "c": "選 (1)。"}]}, {"subject": "B", "year": "113", "num": 7, "type": "單選", "rate": "15%", "img": "img/113B_q07.png", "answer": [{"t": "(3)　(0,9,16,5)"}], "key": "城市最高溫=兩區的較大值：A（<24）恆為 0（東區恆≥24）；D（≥36）恆=5（只有東區有 5 天≥36）；B≤11（東區<30 只有 11 天）。", "kaodian": [{"unit": "數據分析", "title": "考點4 加權平均、中位數與資料判讀", "url": "../concept-map/115學測數學_數據分析.html#kp4"}], "steps": [{"type": "text", "c": "城市每日最高溫 = max(東,西)。東區沒有 <24 的日子（[18,24)=0），故城市最高溫恆 ≥24 → A=0。"}, {"type": "text", "c": "西區沒有 ≥36 的日子，城市 ≥36 只發生在東區 ≥36 的 5 天 → D=5。"}, {"type": "text", "c": "城市在 [24,30)（B）需「東∈[24,30) 且西<30」，而東∈[24,30) 只有 11 天 → B≤11。"}, {"type": "text", "c": "四項還要合計 30。(1)D=0、(2)合計 35、(4)A=3、(5)B=12>11 皆不合；只有 (3)(0,9,16,5) 全部滿足且可建構。選 (3)。"}]}, {"subject": "B", "year": "113", "num": 8, "type": "多選", "rate": "56%（全對率 41%）", "img": "img/113B_q08.png", "answer": [{"t": "(1)(2)(5)"}], "key": "等比的判準是「相鄰兩項比值固定」。交錯正負、反向排列、相鄰三項相乘都仍固定比值；取 log 變等差、3 的次方比值不固定。", "kaodian": [{"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "../concept-map/115學測數學_數列與級數.html#kp2"}], "steps": [{"type": "text", "c": "原數列 a,b,c,d,e 公比 r。(1) a,-b,c,-d,e 相鄰比值都是 -r → 等比 ✓。"}, {"type": "text", "c": "(2) e,d,c,b,a 比值都是 1/r → 等比 ✓。"}, {"type": "text", "c": "(5) abc,bcd,cde 比值 = d/a = r³（下一項）、e/b = r³，固定 → 等比 ✓。"}, {"type": "text", "c": "(3) log a,…,log e 是「等差」（比值不固定）→ 錯。(4) 3ᵃ,3ᵇ,… 比值 3^(b-a)，但 b-a 不固定 → 錯。答 (1)(2)(5)。"}]}, {"subject": "B", "year": "113", "num": 9, "type": "多選", "rate": "29%（全對率 12%）", "img": "img/113B_q09.png", "answer": [{"t": "(2)(5)"}], "key": "被除式 = 除式×商式 + 餘式，且餘式次數要小於除式（<2 次）。把選項化成「(x²+5x+1)×(x³+7x²+x+3)+餘式」的形式檢查。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "../concept-map/115學測數學_多項式函數.html#kp1"}], "steps": [{"type": "text", "c": "設 D=x²+5x+1、Q=x³+7x²+x+3。合格的 f 必須是 D×Q + R，且 R 的次數 <2。"}, {"type": "text", "c": "(2) DQ - x：餘式 -x（次數1）、商式 Q → 正確。"}, {"type": "text", "c": "(5) (Q+1)D - x² = DQ + D - x² = DQ + (5x+1)：餘式 5x+1（次數1）、商式 Q → 正確。"}, {"type": "text", "c": "(1) 商式變成 2Q；(3) DQ+x² 的 x² 不能當餘式（次數不夠低），商式變 Q+1；(4) 商式是 x³+7x²+x+4≠Q。皆錯。答 (2)(5)。"}]}, {"subject": "B", "year": "113", "num": 10, "type": "多選", "rate": "44%（全對率 24%）", "img": "img/113B_q10.png", "answer": [{"t": "(1)(3)(4)"}], "key": "兩點相向、速率 5 與 10：第一次相遇用「合速率」；A 往返一趟 240/? 秒定週期；逐段追蹤相遇位置。", "kaodian": [{"unit": "數列與級數", "title": "考點4 級數求和與規律、週期", "url": "../concept-map/115學測數學_數列與級數.html#kp4"}], "steps": [{"type": "text", "c": "軌道長 120，A 從一端速率 5、B 從另一端速率 10 相向。"}, {"type": "text", "c": "(1) 第一次相遇：合速率 15，時間 120/15=8 秒，A 走 40 → 距端點 40 公分 ✓。"}, {"type": "text", "c": "(3) A 回到出發點需 240/5=48 秒；B 週期 240/10=24 秒，48=2×24，B 也回到出發點 ✓。"}, {"type": "text", "c": "(4) 追蹤到第二次相遇在 t=24 秒、位置 x=120（端點上）✓。"}, {"type": "text", "c": "(2) A 的週期是 48 秒不是 24 → 錯。(5) 一個週期內相遇位置只有 x=40 與 x=120 共 2 個 → 錯。答 (1)(3)(4)。"}]}, {"subject": "B", "year": "113", "num": 11, "type": "多選", "rate": "31%（全對率 15%）", "img": "img/113B_q11.png", "answer": [{"t": "(1)(4)(5)"}], "key": "平均減碳 5% 是「幾何平均」不是算術平均；各年 (1+成長率) 連乘 = Y/X = 0.95⁴。", "kaodian": [{"unit": "指數與對數", "title": "考點5 指對數的應用：成長衰退模型與數列", "url": "../concept-map/115學測數學_指數與對數.html#kp5"}, {"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "../concept-map/115學測數學_數列與級數.html#kp2"}], "steps": [{"type": "text", "c": "(1) 第2年成長率 -0.07 = (A-X)/X → A=0.93X ✓。"}, {"type": "text", "c": "(4) Y/X=0.95⁴，開 4 次方 -1 = 0.95-1 = -0.05 ✓（這才是每年平均變化率）。"}, {"type": "text", "c": "(5) 各年 (1+成長率) 連乘 = Y/X：0.93(1+p)(1+q)(1+r)=0.95⁴ ✓。"}, {"type": "text", "c": "(2) 0.95⁴≈0.8145>0.8，故 Y≤0.8X 錯。(3) 成長率的算術平均不等於 -0.05（平均是幾何的）→ 錯。答 (1)(4)(5)。"}]}, {"subject": "B", "year": "113", "num": 12, "type": "多選", "rate": "49%（全對率 26%）", "img": "img/113B_q12.png", "answer": [{"t": "(1)(4)"}], "key": "每格：留原地 1/2、往兩個合法鄰格各 1/4。用對角線對稱（B、C 對稱）與「在對角線 A、D 的機率和固定」判斷。", "kaodian": [{"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "../concept-map/115學測數學_排列組合與機率.html#kp3"}], "steps": [{"type": "text", "c": "從 A：1/4 到 B、1/4 到 C、1/2 停留（上、左出界）。各格同理。起點 A。"}, {"type": "text", "c": "(1) b₁ = 從 A 往右到 B = 1/4 ✓。"}, {"type": "text", "c": "(4) 棋盤沿對角線 A–D 對稱，起點 A 在對角線上，故 B、C 機率恆相等，b₉₉=c₉₉ ✓。"}, {"type": "text", "c": "算得 (2) b₂=1/4≠1/8 錯。設 sₙ=aₙ+dₙ（在對角線的機率），可推 s_{n+1}=½sₙ+½(1-sₙ)=½ 恆定，故 a+d 一直是 1/2 → (3)=3/4 錯、(5)>1/2 錯。答 (1)(4)。"}]}, {"subject": "B", "year": "113", "num": 13, "type": "選填", "rate": "63%", "img": "img/113B_q13.png", "answer": [{"t": "c−3d = −1"}], "key": "把 [2a+1, 2b+1] 拆成 2[a,b]+[1,1]，矩陣乘法可分配，直接用已知的 M[a,b]=[1,0]。", "kaodian": [{"unit": "矩陣", "title": "考點1 矩陣的意義、相等與乘法★★☆", "url": "../concept-map/115學測數學_矩陣.html#kp1"}], "steps": [{"type": "text", "c": "設 M=[[1,-1],[3,-2]]。已知 M[a;b]=[1;0]。所求："}, {"type": "math", "c": "M\\begin{bmatrix}2a+1\\\\2b+1\\end{bmatrix}=2M\\begin{bmatrix}a\\\\b\\end{bmatrix}+M\\begin{bmatrix}1\\\\1\\end{bmatrix}=2\\begin{bmatrix}1\\\\0\\end{bmatrix}+\\begin{bmatrix}0\\\\1\\end{bmatrix}=\\begin{bmatrix}2\\\\1\\end{bmatrix}"}, {"type": "text", "c": "（其中 M[1;1]=[1-1; 3-2]=[0;1]）。故 c=2、d=1，c-3d=2-3=-1。"}]}, {"subject": "B", "year": "113", "num": 14, "type": "選填", "rate": "23%", "img": "img/113B_q14.png", "answer": [{"m": "\\dfrac{2}{7}"}], "key": "設全體 =1，用「只報 A=3/10」與「報 A 者中 5/8 也報 B」回推各區塊人數，再算「只報 B ÷ 報 B」。", "kaodian": [{"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "../concept-map/115學測數學_排列組合與機率.html#kp4"}], "steps": [{"type": "text", "c": "設全體 =1。報 A 者中 3/8 是只報 A（另 5/8 也報 B），故報 A 總數 a 滿足 (3/8)a=3/10 → a=4/5。"}, {"type": "text", "c": "兩科都報 = (5/8)(4/5)=1/2；只報 A=3/10。因每人至少報一科，只報 B = 1 - 3/10 - 1/2 = 1/5。"}, {"type": "text", "c": "報 B 總數 = 兩科都報 + 只報 B = 1/2 + 1/5 = 7/10。所求比例："}, {"type": "math", "c": "\\dfrac{1/5}{7/10}=\\dfrac{2}{7}"}, {"type": "text", "c": "答 2/7。"}]}, {"subject": "B", "year": "113", "num": 15, "type": "選填", "rate": "28%", "img": "img/113B_q15.png", "answer": [{"m": "\\overrightarrow{Q_1Q_2}=3\\,\\overrightarrow{P_1Q_1}-6\\,\\overrightarrow{P_2Q_2}"}], "key": "把 Q₁、Q₂ 用 P₁、P₂、R 表示，Q₁Q₂=Q₂-Q₁ 展開後，再湊回 P₁Q₁ 與 P₂Q₂。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}, {"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "../concept-map/115學測數學_平面向量.html#kp1"}], "steps": [{"type": "text", "c": "由 P₁R=4P₁Q₁ 得 P₁Q₁=¼(R-P₁)，即 Q₁=¾P₁+¼R；由 P₂R=7P₂Q₂ 得 Q₂=6/7 P₂+1/7 R。"}, {"type": "math", "c": "\\overrightarrow{Q_1Q_2}=Q_2-Q_1=-\\tfrac34 P_1+\\tfrac67 P_2-\\tfrac{3}{28}R"}, {"type": "text", "c": "而 P₁Q₁=¼R-¼P₁、P₂Q₂=1/7 R-1/7 P₂。設 Q₁Q₂=αP₁Q₁+βP₂Q₂，比對 P₁、P₂ 係數得 α=3、β=-6（R 係數也吻合）。"}, {"type": "math", "c": "\\overrightarrow{Q_1Q_2}=3\\,\\overrightarrow{P_1Q_1}-6\\,\\overrightarrow{P_2Q_2}"}]}, {"subject": "B", "year": "113", "num": 16, "type": "選填", "rate": "15%", "img": "img/113B_q16.png", "answer": [{"m": "\\dfrac{4\\pi}{3}"}], "key": "球半徑 2；先找赤道上距 A 最遠的點 P，再用空間兩點距離＋餘弦定理求圓心角 ∠AOP，弧長 = 半徑 × 弧度角。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "../concept-map/115學測數學_三角.html#kp2"}], "steps": [{"type": "text", "c": "半徑 R=2（|OA|=|ON|=2）。赤道點 (2cosθ,2sinθ,0) 到 A 的距離平方 = 8-2(√3cosθ+sinθ)，用疊合 √3cosθ+sinθ=2cos(θ-30°)，其最小值 -2 時最遠，得 P=(-√3,-1,0)。"}, {"type": "text", "c": "△AOP 中 OA=OP=2，用空間兩點距離求 AP：AP²=12，即 AP=2√3。再用餘弦定理求圓心角："}, {"type": "math", "c": "\\cos\\angle AOP=\\dfrac{OA^2+OP^2-AP^2}{2\\cdot OA\\cdot OP}=\\dfrac{4+4-12}{8}=-\\dfrac12\\Rightarrow \\angle AOP=120^\\circ=\\dfrac{2\\pi}{3}"}, {"type": "text", "c": "120°<180°，此即劣弧。弧長 = R×弧度："}, {"type": "math", "c": "2\\times\\dfrac{2\\pi}{3}=\\dfrac{4\\pi}{3}"}]}, {"subject": "B", "year": "113", "num": 17, "type": "選填", "rate": "1%", "img": "img/113B_q17.png", "answer": [{"t": "76"}], "key": "三角形三內角 ∝ 三段弧的格數 a,b,c（a+b+c=12）；三角成等差 ⟺ a,b,c 成等差 ⟺ 中位數 =4。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}, {"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "../concept-map/115學測數學_數列與級數.html#kp1"}], "steps": [{"type": "text", "c": "12 等分點，內接三角形三內角 = 15a°,15b°,15c°，其中 a,b,c 為三段弧的格數，a+b+c=12。"}, {"type": "text", "c": "三內角成等差 ⟺ a,b,c（排序後）成等差 ⟺ 中間數 =12/3=4。故弧格 = {p,4,r}、p+r=8：{1,4,7}、{2,4,6}、{3,4,5}、{4,4,4}。"}, {"type": "text", "c": "各弧組對應的三角形個數（12 點）：三數相異 =24 個，全相同 =4 個："}, {"type": "math", "c": "24+24+24+4=76"}, {"type": "text", "c": "答 76。"}]}, {"subject": "B", "year": "113", "num": 18, "type": "混合題（單選 3 分）", "rate": "64%", "img": "img/113B_q18.png", "answer": [{"t": "(4)　十四面體"}], "key": "把長方體 8 個角都用「通過三鄰邊中點」的截面削掉：原 6 個面各留 1 面 + 新增 8 個三角面。", "kaodian": [], "steps": [{"type": "text", "c": "長方體原有 6 面、8 頂點。每個角的截面通過該角三鄰邊的「中點」，相鄰兩角的截面正好在同一條邊的中點相接。"}, {"type": "text", "c": "結果：原 6 個面各縮成 1 個面（共 6 面）＋ 每個被削的角新增 1 個三角面（共 8 面）。"}, {"type": "math", "c": "6+8=14"}, {"type": "text", "c": "是十四面體。選 (4)。"}], "stem": "img/113B_stem.png"}, {"subject": "B", "year": "113", "num": 19, "type": "非選擇題（4 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/113B_q19.png", "answer": [{"m": "4\\sqrt{65}"}], "key": "△BCD 三邊 BC=8、BD=DC=9 是等腰三角形；用底 8、求高再算面積。", "kaodian": [{"unit": "三角", "title": "考點6 三角形面積比、相似與角平分線", "url": "../concept-map/115學測數學_三角.html#kp6"}], "steps": [{"type": "text", "c": "△BCD 為等腰（BD=DC=9，底 BC=8）。D 到 BC 的高："}, {"type": "math", "c": "h=\\sqrt{9^2-4^2}=\\sqrt{81-16}=\\sqrt{65}"}, {"type": "math", "c": "\\triangle BCD=\\dfrac12\\times8\\times\\sqrt{65}=4\\sqrt{65}"}], "stem": "img/113B_stem.png"}, {"subject": "B", "year": "113", "num": 20, "type": "非選擇題（8 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/113B_q20.png", "answer": [{"t": "AD=7，體積="}, {"m": "\\dfrac{112}{3}"}, {"t": "，高="}, {"m": "\\dfrac{28\\sqrt{65}}{65}"}], "key": "把 A 放原點，B、C、D 正好是三條稜邊的中點、落在三軸上（兩兩垂直）；解出邊長後，用「三邊垂直的角錐體積=三邊乘積÷6」算體積，再由體積反求高。", "kaodian": [], "steps": [{"type": "text", "c": "以 A 為原點，B、C、D 是 A 出發三稜邊的中點，設 B=(a,0,0)、D=(0,b,0)、C=(0,0,c)。"}, {"type": "text", "c": "由 BC=8、BD=9、DC=9：a²+c²=64、a²+b²=81、b²+c²=81 → a=c=4√2、b=7。"}, {"type": "text", "c": "AD = b = 7。體積（三邊互相垂直）："}, {"type": "math", "c": "V=\\dfrac{1}{6}\\,abc=\\dfrac{1}{6}(4\\sqrt2)(7)(4\\sqrt2)=\\dfrac{112}{3}"}, {"type": "text", "c": "以 △BCD（面積 4√65）為底，用 V=⅓×底面積×高 反求高："}, {"type": "math", "c": "h=\\dfrac{3V}{\\triangle BCD}=\\dfrac{3\\cdot\\frac{112}{3}}{4\\sqrt{65}}=\\dfrac{28}{\\sqrt{65}}=\\dfrac{28\\sqrt{65}}{65}"}], "stem": "img/113B_stem.png"}, {"subject": "A", "year": "114", "num": 1, "type": "單選", "rate": "57%", "img": "img/114_q01.png", "answer": [{"t": "(5)　"}, {"m": "k=6"}], "key": "「獨立」代表 P(藍 且 1號)=P(藍)×P(1號)，列式解 k。", "kaodian": [{"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "../concept-map/115學測數學_排列組合與機率.html#kp5"}, {"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "../concept-map/115學測數學_排列組合與機率.html#kp3"}], "steps": [{"type": "text", "c": "球總數 = 藍(2+3) + 綠(4+k) = 9+k。其中藍球 5 顆、1 號球 (2+4)=6 顆、又藍又 1 號的 2 顆。"}, {"type": "text", "c": "兩事件獨立，機率相乘："}, {"type": "math", "c": "\\dfrac{2}{9+k}=\\dfrac{5}{9+k}\\times\\dfrac{6}{9+k}"}, {"type": "text", "c": "兩邊乘 (9+k)²：2(9+k)=30 → 9+k=15 → k=6。選 (5)。"}]}, {"subject": "A", "year": "114", "num": 2, "type": "單選", "rate": "62%", "img": "img/114_q02.png", "answer": [{"t": "(2)　6"}], "key": "直線與兩軸圍成的直角三角形，兩股是 x 截距與 y 截距；面積差列方程。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}, {"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "../concept-map/115學測數學_直線與圓.html#kp2"}], "steps": [{"type": "text", "c": "L1、L2 都過 x 軸上的 P(a,0)，與兩軸圍成直角三角形。一股是 a，另一股是 y 截距。"}, {"type": "text", "c": "L1 斜率 -4/3：y 截距 4a/3，面積 = ½·a·(4a/3)=2a²/3。"}, {"type": "text", "c": "L2 斜率 -3/2：y 截距 3a/2，面積 = ½·a·(3a/2)=3a²/4。"}, {"type": "math", "c": "\\left|\\dfrac{2a^2}{3}-\\dfrac{3a^2}{4}\\right|=\\dfrac{a^2}{12}=3\\Rightarrow a^2=36\\Rightarrow a=6"}, {"type": "text", "c": "故 a=6，選 (2)。"}]}, {"subject": "A", "year": "114", "num": 3, "type": "單選", "rate": "60%", "img": "img/114_q03.png", "answer": [{"t": "(4)　"}, {"m": "4\\times 5!\\times 4!\\times 3!"}], "key": "三類各自「捆綁」→ 內部排列 × 三捆的排列，再扣掉不合規定者。", "kaodian": [{"unit": "排列組合與機率", "title": "考點1 計數原理與排列（有順序）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "同類綁在一起，內部各自排列：鋼琴 5!、小提琴 4!、歌唱 3!。"}, {"type": "text", "c": "三個「捆包」排成一列共 3!=6 種。限制：歌唱要在鋼琴之後或小提琴之後，也就是歌唱「不能排最前面」。"}, {"type": "text", "c": "歌唱排最前面的有 2 種（歌–鋼–提、歌–提–鋼），扣掉後剩 6−2=4 種捆包排法。"}, {"type": "math", "c": "4\\times 5!\\times 4!\\times 3!"}, {"type": "text", "c": "故選 (4)。"}]}, {"subject": "A", "year": "114", "num": 4, "type": "單選", "rate": "44%", "img": "img/114_q04.png", "answer": [{"t": "(3)　90"}], "key": "對每個整數 x，數「曲線 y=log₂x 下方、x 軸上方」的整數 y 有幾個，再相加。", "kaodian": [{"unit": "指數與對數", "title": "考點4 指數與對數函數的圖形", "url": "../concept-map/115學測數學_指數與對數.html#kp4"}, {"unit": "指數與對數", "title": "考點3 常用對數：科學記號、位數與首位", "url": "../concept-map/115學測數學_指數與對數.html#kp3"}], "steps": [{"type": "text", "c": "區域由 y=log₂x、x 軸、x=61/2(=30.5) 圍成。內部格子點：整數 x 由 2 到 30，對每個 x 數 1≤y<log₂x 的整數 y。"}, {"type": "text", "c": "x=17~30 時 log₂x 在 4~5 間各 4 個；x=9~16 各 3 個；x=5~8 各 2 個；x=3,4 各 1 個；x=2 為 0 個。"}, {"type": "math", "c": "2\\times 1+4\\times 2+8\\times 3+14\\times 4=2+8+24+56=90"}, {"type": "text", "c": "共 90 個，選 (3)。（見右圖）"}], "fig": "img/114_fig_q04.png"}, {"subject": "A", "year": "114", "num": 5, "type": "單選", "rate": "30%", "img": "img/114_q05.png", "answer": [{"t": "(1)　"}, {"m": "\\dfrac{1}{3}"}], "key": "用倍角公式把兩個不等式各自因式分解，再取交集。", "kaodian": [{"unit": "三角", "title": "考點5 和差角與倍角（解方程與不等式）", "url": "../concept-map/115學測數學_三角.html#kp5"}, {"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "sin2θ>sinθ：2sinθcosθ−sinθ>0 → sinθ(2cosθ−1)>0。"}, {"type": "text", "c": "cos2θ>cosθ：2cos²θ−cosθ−1>0 →(2cosθ+1)(cosθ−1)>0。因 cosθ−1≤0，需 cosθ<−1/2，得 θ∈(2π/3, 4π/3)。"}, {"type": "text", "c": "在此範圍 2cosθ−1<0，故第一式需 sinθ<0，即 θ∈(π, 2π)。取交集："}, {"type": "math", "c": "\\left(\\dfrac{2\\pi}{3},\\dfrac{4\\pi}{3}\\right)\\cap(\\pi,2\\pi)=\\left(\\pi,\\dfrac{4\\pi}{3}\\right)"}, {"type": "text", "c": "寫成 aπ<θ<bπ 即 a=1、b=4/3，b−a=1/3。選 (1)。"}]}, {"subject": "A", "year": "114", "num": 6, "type": "單選", "rate": "35%", "img": "img/114_q06.png", "answer": [{"t": "(3)　"}, {"m": "2\\sqrt{10}"}], "key": "兩兩垂直 → 體積=|u||v||w|；用內積把長度一個個湊出來。", "kaodian": [{"unit": "空間向量", "title": "考點2 空間向量的內積、夾角與垂直", "url": "../concept-map/115學測數學_空間向量.html#kp2"}, {"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "../concept-map/115學測數學_空間向量.html#kp3"}], "steps": [{"type": "text", "c": "u,v,w 兩兩垂直（內積 0）。因此 |u−v|²=|u|²+|v|²，|v−w|²=|v|²+|w|²："}, {"type": "math", "c": "|\\vec{u}-\\vec{v}|^2=4+1+0=5,\\qquad |\\vec{v}-\\vec{w}|^2=1+4+9=14"}, {"type": "text", "c": "再算 (u−v)·(v−w)，展開後因垂直只剩 −|v|²："}, {"type": "math", "c": "(\\vec{u}-\\vec{v})\\cdot(\\vec{v}-\\vec{w})=(2)(-1)+(-1)(2)+0=-4=-|\\vec{v}|^2\\Rightarrow |\\vec{v}|^2=4"}, {"type": "text", "c": "於是 |u|²=5−4=1、|w|²=14−4=10。體積 = √1·√4·√10 = 2√10，選 (3)。"}]}, {"subject": "A", "year": "114", "num": 7, "type": "多選", "rate": "66%（全對率 44%）", "img": "img/114_q07.png", "answer": [{"t": "(2)(4)"}], "key": "算出 b_n 的遞迴，會發現它是公比 1/3 的等比數列。", "kaodian": [{"unit": "數列與級數", "title": "考點3 遞迴數列：構造等比與數學歸納法", "url": "../concept-map/115學測數學_數列與級數.html#kp3"}, {"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "../concept-map/115學測數學_數列與級數.html#kp2"}], "steps": [{"type": "text", "c": "由 3a_{n+1}=a_n+n、a_1=2 得 a_2=1，故 (1) a_2=2 錯。"}, {"type": "text", "c": "b_n=a_n−n/2+3/4，算得 b_1=9/4、b_2=3/4，(2) 對。代入化簡得遞迴："}, {"type": "math", "c": "b_{n+1}=\\dfrac{1}{3}b_n\\ \\Rightarrow\\ b_n=\\dfrac{9}{4}\\left(\\dfrac{1}{3}\\right)^{n-1}"}, {"type": "text", "c": "公比是 1/3 不是 2/3，(3) 錯。"}, {"type": "math", "c": "(5)\\ b_{10}=\\dfrac{9}{4}\\cdot\\dfrac{1}{3^{9}}=\\dfrac{1}{8748}\\approx 1.14\\times10^{-4}>10^{-4}\\ (\\text{錯})"}, {"type": "text", "c": "(4) 由 a_n=b_n+n/2−3/4 代入，3ⁿa_n=[27+3ⁿ(2n−3)]/4 恆為正整數，對。故選 (2)(4)。"}]}, {"subject": "A", "year": "114", "num": 8, "type": "多選", "rate": "48%（全對率 25%）", "img": "img/114_q08.png", "answer": [{"t": "(3)(5)"}], "key": "兩邊化成同底 2 的次方，指數相等後整理成一個圓。", "kaodian": [{"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "../concept-map/115學測數學_指數與對數.html#kp1"}, {"unit": "直線與圓", "title": "考點4 直線與圓的位置：相切、弦長與切線", "url": "../concept-map/115學測數學_直線與圓.html#kp4"}], "steps": [{"type": "math", "c": "\\dfrac{2^{x^2}}{8}=\\dfrac{4^{x}}{2^{y^2}}\\Rightarrow 2^{x^2-3}=2^{2x-y^2}\\Rightarrow x^2-3=2x-y^2"}, {"type": "math", "c": "(x-1)^2+y^2=4\\quad(\\text{圓心 }(1,0)\\text{、半徑 }2)"}, {"type": "text", "c": "(3) 圖形是圓，對。(1) x=3 代入得 y=0 只有 1 解，錯。(2) 圓心不在原點，對 (−a,−b) 不對稱，錯。"}, {"type": "text", "c": "(4) 圓心到 x+y=4 的距離 = 3/√2 ≈ 2.12 > 2，直線與圓不相交，錯。"}, {"type": "math", "c": "(5)\\ x-y=(1+2\\cos\\theta)-2\\sin\\theta\\le 1+2\\sqrt{2}\\ (\\text{對})"}, {"type": "text", "c": "故選 (3)(5)。"}]}, {"subject": "A", "year": "114", "num": 9, "type": "多選", "rate": "44%（全對率 20%）", "img": "img/114_q09.png", "answer": [{"t": "(2)(4)(5)"}], "key": "「有沒有實根」看判別式：≥0 有、<0 沒有。", "kaodian": [{"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "../concept-map/115學測數學_多項式函數.html#kp2"}, {"unit": "多項式函數", "title": "考點3 多項式方程式與不等式的解法", "url": "../concept-map/115學測數學_多項式函數.html#kp3"}], "steps": [{"type": "text", "c": "有實根：b²−4c≥0；沒實根：(b+2)²−4c<0。兩式相減：(b+2)²−b²<0 → 4b+4<0 → b<−1，(2) 對。"}, {"type": "text", "c": "又 4c>(b+2)²≥0 → c>0，故 (1) c<0 錯。"}, {"type": "text", "c": "(4) 判別式 (b+2)²+4c，因 c>0 一定 >0 → 有實根，對。"}, {"type": "math", "c": "(5)\\ (b-2)^2-4c\\ge (b-2)^2-b^2=4(1-b)>0\\ (\\because b<-1)\\Rightarrow \\text{有實根（對）}"}, {"type": "text", "c": "(3) 取 b=−3, c=2：(b+1)²−4c=4−8<0 無實根，故不一定成立 → 錯。故選 (2)(4)(5)。"}]}, {"subject": "A", "year": "114", "num": 10, "type": "多選", "rate": "38%（全對率 17%）", "img": "img/114_q10.png", "answer": [{"t": "(1)(4)(5)"}], "key": "sinπx 週期 2、左右對稱；y=k(0<k<1) 在 (0,1) 與 (2,3) 各交兩點，共 4 點。", "kaodian": [{"unit": "三角", "title": "考點4 三角函數圖形：週期、對稱與疊合", "url": "../concept-map/115學測數學_三角.html#kp4"}], "steps": [{"type": "text", "c": "y=sinπx 在 (0,1) 與 (2,3) 各是一個上凸的波峰。水平線 y=k（0<k<1）在兩段各交 2 點，共 4 個交點：x1,x2∈(0,1)、x3,x4∈(2,3)。"}, {"type": "text", "c": "(1) 要有 x1,x2 在 (0,1)，必須 k>0，對。(2) 交點其實有 4 個不是 3 個，錯。(3) 由對稱 x1+x2=1（對稱於 0.5），不是 <1，錯。"}, {"type": "math", "c": "(4)\\ 2\\overline{PQ}=\\overline{QR}:\\ (x_2-x_1)=2t,\\ (x_3-x_2)=2-2t\\Rightarrow t=\\tfrac13,\\ k=\\cos\\tfrac{\\pi}{3}=\\tfrac12\\ (\\text{對})"}, {"type": "math", "c": "(5)\\ x_1+x_2+x_3+x_4=1+5=6>5\\ (\\text{對})"}, {"type": "text", "c": "故選 (1)(4)(5)。（見右圖）"}], "fig": "img/114_fig_q10.png"}, {"subject": "A", "year": "114", "num": 11, "type": "多選", "rate": "38%（全對率 17%）", "img": "img/114_q11.png", "answer": [{"t": "(3)(4)(5)"}], "key": "餘弦定理求角；用坐標定出各點，求角平分線與 CD 的交點比例。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}, {"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "../concept-map/115學測數學_三角.html#kp2"}], "steps": [{"type": "math", "c": "\\cos\\angle BAC=\\dfrac{AB^2+AC^2-BC^2}{2\\cdot AB\\cdot AC}=\\dfrac{36+25-16}{60}=\\dfrac{3}{4}\\ ((3)\\ \\text{對})"}, {"type": "text", "c": "設 A 為原點，求出 C=(15/4, 5√7/4)、D=AB 中點=(3,0)。B 的角平分線與 CD 交於 P，解得 P 分 CD 使 CP:PD=4:3。"}, {"type": "text", "c": "所以 CP=(4/7)CD（不是 3/7），(1) 錯。"}, {"type": "math", "c": "\\vec{AP}=\\dfrac{2}{7}\\vec{AB}+\\dfrac{3}{7}\\vec{AC}\\ (\\text{係數與 (2) 剛好相反，(2) 錯})"}, {"type": "math", "c": "[\\triangle ACP]=\\dfrac{15}{14}\\sqrt{7}\\ ((4)\\ \\text{對}),\\qquad \\vec{AP}\\cdot\\vec{AC}=\\dfrac{120}{7}\\ ((5)\\ \\text{對})"}, {"type": "text", "c": "故選 (3)(4)(5)。"}]}, {"subject": "A", "year": "114", "num": 12, "type": "多選", "rate": "22%（全對率 2%）", "img": "img/114_q12.png", "answer": [{"t": "(1)(3)(4)(5)"}], "key": "u=100−x、v=y÷1000 都是直線變換；標準差看斜率絕對值，注意單位換算。", "kaodian": [{"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "../concept-map/115學測數學_數據分析.html#kp3"}, {"unit": "數據分析", "title": "考點1 一維數據：平均、中位數與標準差", "url": "../concept-map/115學測數學_數據分析.html#kp1"}], "steps": [{"type": "text", "c": "甲+乙=100，故 u=100−x，(1) 對。1 微米 = 1000 奈米，所以 v(微米)=y(奈米)/1000，(2) 說 1000y 錯。"}, {"type": "text", "c": "(3) u=100−x 斜率 −1（絕對值 1），標準差不變，對。"}, {"type": "math", "c": "v=\\dfrac{21.3x-40}{1000},\\ x=100-u\\Rightarrow v=2.09-0.0213u\\Rightarrow b=2.09\\ ((4)\\ \\text{對})"}, {"type": "text", "c": "(5) 新增的點恰在迴歸線上（殘差 0），加進去不會改變最小平方線，對。故選 (1)(3)(4)(5)。"}]}, {"subject": "A", "year": "114", "num": 13, "type": "選填", "rate": "48%", "img": "img/114_q13.png", "answer": [{"t": "選填　"}, {"m": "(-6,\\ 3)"}], "key": "用商式寫出 f；at³+bt 是奇函數，對稱中心就在平移後的原點。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "../concept-map/115學測數學_多項式函數.html#kp1"}, {"unit": "多項式函數", "title": "考點5 三次函數圖形與對稱中心", "url": "../concept-map/115學測數學_多項式函數.html#kp5"}], "steps": [{"type": "text", "c": "q(x) 在 x=−6 有最大值 8，故 q(x)=a(x+6)²+8（a<0）。又 f(x)=(x+6)q(x)+3："}, {"type": "math", "c": "f(x)=a(x+6)^3+8(x+6)+3"}, {"type": "text", "c": "令 t=x+6，f=at³+8t+3。at³+8t 是奇函數（對稱於 t=0），所以對稱中心在 t=0（即 x=−6），該處 f=3。"}, {"type": "math", "c": "\\text{對稱中心}=(-6,\\ 3)"}, {"type": "text", "c": "故答案 (−6, 3)。"}]}, {"subject": "A", "year": "114", "num": 14, "type": "選填", "rate": "33%", "img": "img/114_q14.png", "answer": [{"t": "選填　"}, {"m": "a+b+c=-11"}], "key": "點到平面距離公式；用 a,b,c<0 判斷絕對值內的正負，再解聯立。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "../concept-map/115學測數學_空間向量.html#kp4"}], "steps": [{"type": "text", "c": "點到平面距離 = |把點代入|/|法向量|。三平面法向量長度為 5、5、3："}, {"type": "math", "c": "\\dfrac{|4b+3c-2|}{5}=6,\\quad \\dfrac{|3b+4c+5|}{5}=6,\\quad \\dfrac{|a+2b+2c+2|}{3}=6"}, {"type": "text", "c": "因 a,b,c<0，各絕對值內為負，得 4b+3c=−28、3b+4c=−35，解出 b=−1、c=−8。"}, {"type": "math", "c": "a+2b+2c+2=a-16=-18\\Rightarrow a=-2\\Rightarrow a+b+c=-11"}, {"type": "text", "c": "故 a+b+c=−11。"}]}, {"subject": "A", "year": "114", "num": 15, "type": "選填", "rate": "16%", "img": "img/114_q15.png", "answer": [{"t": "選填　"}, {"m": "405"}], "key": "分「第幾次才湊滿 3 個正面」四種情形算機率，再乘花費求期望值。", "kaodian": [{"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp6"}, {"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "../concept-map/115學測數學_排列組合與機率.html#kp3"}], "steps": [{"type": "text", "c": "每次正面機率 1/2。四種結果的機率："}, {"type": "math", "c": "P_{240}=\\left(\\tfrac12\\right)^3=\\tfrac18,\\quad P_{320}=\\binom{3}{2}\\tfrac1{8}\\cdot\\tfrac12=\\tfrac{3}{16},\\quad P_{400}=\\binom{4}{2}\\tfrac1{16}\\cdot\\tfrac12=\\tfrac{3}{16}"}, {"type": "math", "c": "P_{480}=P(\\text{5 次}\\le 2\\text{ 正})=\\dfrac{1+5+10}{32}=\\dfrac12"}, {"type": "math", "c": "E=240\\cdot\\tfrac18+320\\cdot\\tfrac3{16}+400\\cdot\\tfrac3{16}+480\\cdot\\tfrac12=30+60+75+240=405"}, {"type": "text", "c": "期望花費 405 元。"}]}, {"subject": "A", "year": "114", "num": 16, "type": "選填", "rate": "18%", "img": "img/114_q16.png", "answer": [{"t": "選填　"}, {"m": "\\overline{AB}=\\dfrac{24}{5}"}], "key": "圓心到 L1 距離 1 定出 m；L2 相切定出半徑；再用弦長公式。", "kaodian": [{"unit": "直線與圓", "title": "考點4 直線與圓的位置：相切、弦長與切線", "url": "../concept-map/115學測數學_直線與圓.html#kp4"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "L1 過 (3,1) 斜率 m。圓心 O 到 L1 距離為 1："}, {"type": "math", "c": "\\dfrac{|1-3m|}{\\sqrt{m^2+1}}=1\\Rightarrow 8m^2-6m=0\\Rightarrow m=\\dfrac34\\ (m=0\\ \\text{不合})"}, {"type": "text", "c": "則 L2 斜率 −3/4，方程式 3x+4y−13=0。Γ 與 L2 相切 → 半徑 = 圓心到 L2 的距離："}, {"type": "math", "c": "r=\\dfrac{|-13|}{\\sqrt{9+16}}=\\dfrac{13}{5}"}, {"type": "math", "c": "\\overline{AB}=2\\sqrt{r^2-1}=2\\sqrt{\\dfrac{169}{25}-1}=2\\cdot\\dfrac{12}{5}=\\dfrac{24}{5}"}]}, {"subject": "A", "year": "114", "num": 17, "type": "選填", "rate": "14%", "img": "img/114_q17.png", "answer": [{"t": "選填　"}, {"m": "\\overline{CD}=3+\\sqrt{2}"}], "key": "餘弦定理求 AC 與外接圓半徑；把弦長換成圓心角，用和角求 CD。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "../concept-map/115學測數學_三角.html#kp2"}, {"unit": "三角", "title": "考點7 圓周角與二面角中的三角", "url": "../concept-map/115學測數學_三角.html#kp7"}, {"unit": "三角", "title": "考點5 和差角與倍角", "url": "../concept-map/115學測數學_三角.html#kp5"}], "steps": [{"type": "math", "c": "AC^2=3^2+3^2-2\\cdot3\\cdot3\\cdot\\left(-\\tfrac18\\right)=\\tfrac{81}{4}\\Rightarrow AC=\\tfrac92,\\ \\sin\\angle ABC=\\tfrac{3\\sqrt7}{8}"}, {"type": "math", "c": "2R=\\dfrac{AC}{\\sin\\angle ABC}=\\dfrac{12}{\\sqrt7}"}, {"type": "text", "c": "把弦 AB=BC=3、BD=4 都換成對應的圓心角。取滿足 AD≤CD 的一側，CD 對應的圓心角為 (α+β)，其中 sin(α/2)=√7/4、sin(β/2)=√7/3。用和角公式："}, {"type": "math", "c": "\\overline{CD}=2R\\sin\\tfrac{\\alpha+\\beta}{2}=\\dfrac{12}{\\sqrt7}\\cdot\\dfrac{\\sqrt{14}+3\\sqrt7}{12}=\\sqrt2+3"}, {"type": "text", "c": "故 CD=3+√2。"}]}, {"subject": "A", "year": "114", "num": 18, "type": "混合題（單選 3 分）", "rate": "58%", "img": "img/114_q18.png", "answer": [{"t": "(2)　"}, {"m": "c=-1"}], "key": "旋轉矩陣角度可疊加；A² 對應旋轉 2θ，比對出角度。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "../concept-map/115學測數學_矩陣.html#kp5"}, {"unit": "矩陣", "title": "考點2 矩陣的高次方 Aⁿ", "url": "../concept-map/115學測數學_矩陣.html#kp2"}], "steps": [{"type": "text", "c": "A 是逆時針旋轉某銳角 θ 的旋轉矩陣，則 A²=旋轉 2θ。比對 A²=[[0,c],[1,d]] 與 [[cos2θ,−sin2θ],[sin2θ,cos2θ]]："}, {"type": "math", "c": "\\sin 2\\theta=1,\\ \\cos 2\\theta=0\\Rightarrow 2\\theta=90^\\circ\\Rightarrow \\theta=45^\\circ"}, {"type": "math", "c": "A^2=\\begin{bmatrix}0&-1\\\\1&0\\end{bmatrix}\\Rightarrow c=-1,\\ d=0"}, {"type": "text", "c": "故 c=−1，選 (2)。"}], "stem": "img/114_stem.png"}, {"subject": "A", "year": "114", "num": 19, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/114_q19.png", "answer": [{"t": "非選　"}, {"m": "Q=(-\\sqrt2,\\,0)"}, {"t": "，夾角 60°"}], "key": "A³ 是旋轉 135°、B⁴ 是旋轉 120°；旋轉只改方向角、不改長度。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "../concept-map/115學測數學_矩陣.html#kp5"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}], "steps": [{"type": "text", "c": "由 A²=旋轉90° 得 A=旋轉45°；由 B³=旋轉90° 得 B=旋轉30°。P(1,1) 在方向 45°、長 √2。"}, {"type": "math", "c": "Q=A^3(P):\\ \\text{方向 }45^\\circ+135^\\circ=180^\\circ\\Rightarrow Q=(-\\sqrt2,\\ 0)"}, {"type": "text", "c": "再經 B⁴=旋轉120°：R 的方向角 =180°+120°=300°、長 √2，故 R=(√2/2, −√6/2)。"}, {"type": "math", "c": "\\vec{OR}\\cdot(1,0)=\\dfrac{\\sqrt2}{2},\\ |\\vec{OR}|=\\sqrt2\\Rightarrow \\cos\\theta=\\dfrac12\\Rightarrow \\theta=60^\\circ"}, {"type": "text", "c": "故 Q=(−√2, 0)，OR 與 (1,0) 的夾角為 60°。（與官方參考答案一致）"}], "stem": "img/114_stem.png"}, {"subject": "A", "year": "114", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/114_q20.png", "answer": [{"t": "非選　"}, {"m": "\\angle OSP=60^\\circ"}, {"t": "、"}, {"m": "S=\\left(-\\tfrac{\\sqrt3}{3},1\\right)"}], "key": "OQ 沿 x 軸 → L 是水平線 y=1；求 L 與直線 OR 的交點 S，再算夾角。", "kaodian": [{"unit": "矩陣", "title": "考點5 平面線性變換（旋轉、鏡射、伸縮、推移）", "url": "../concept-map/115學測數學_矩陣.html#kp5"}, {"unit": "平面向量", "title": "考點5 向量的旋轉與坐標應用", "url": "../concept-map/115學測數學_平面向量.html#kp5"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "由第 19 題，Q=(−√2, 0) 在 x 軸上，故直線 OQ 就是 x 軸。L 過 P(1,1) 且平行 OQ → L: y=1。"}, {"type": "text", "c": "直線 OR 方向 (√2/2, −√6/2) ∝ (1, −√3)，方程式 y=−√3 x。與 y=1 交於："}, {"type": "math", "c": "S=\\left(-\\dfrac{1}{\\sqrt3},\\ 1\\right)=\\left(-\\dfrac{\\sqrt3}{3},\\ 1\\right)"}, {"type": "text", "c": "在 S 算 ∠OSP：SP 沿 +x 方向，SO=(1/√3, −1)。"}, {"type": "math", "c": "\\cos\\angle OSP=\\dfrac{\\vec{SO}\\cdot(1,0)}{|\\vec{SO}|}=\\dfrac{1/\\sqrt3}{2/\\sqrt3}=\\dfrac12\\Rightarrow \\angle OSP=60^\\circ"}, {"type": "text", "c": "故 ∠OSP=60°、S=(−√3/3, 1)。（與官方參考答案一致）"}], "stem": "img/114_stem.png"}, {"subject": "B", "year": "114", "num": 1, "type": "單選", "rate": "55%", "img": "img/114B_q01.png", "answer": [{"t": "(3)　2 個"}], "key": "|P-1|+|P-4| 的最小值就是 1 到 4 的距離 3；要它等於 4（比 3 大），P 必落在 1、4 兩點之外。", "kaodian": [{"unit": "數與式", "title": "考點3 數線上的點、距離、分點與根號估算", "url": "../concept-map/115學測數學_數與式.html#kp3"}], "steps": [{"type": "text", "c": "數線上 P 到 1、到 4 的距離和，最小是 1 與 4 的距離 3（P 落在 1~4 之間時）。題目要和 =4>3，所以 P 在區間 [1,4] 之外。"}, {"type": "text", "c": "若 P<1：(1-P)+(4-P)=5-2P=4 → P=1/2（成立）。"}, {"type": "text", "c": "若 P>4：(P-1)+(P-4)=2P-5=4 → P=9/2（成立）。"}, {"type": "text", "c": "共 2 個。選 (3)。"}]}, {"subject": "B", "year": "114", "num": 2, "type": "單選", "rate": "77%", "img": "img/114B_q02.png", "answer": [{"t": "(4)　5"}], "key": "所求就是 A 的第一行。可用矩陣乘法的線性（把它拆成題目兩行的和），或用反方陣 A=BM⁻¹，兩法都行。", "kaodian": [{"unit": "矩陣", "title": "考點1 矩陣的意義、相等與乘法★★☆", "url": "../concept-map/115學測數學_矩陣.html#kp1"}, {"unit": "矩陣", "title": "考點3 反方陣與解矩陣方程式★★☆", "url": "../concept-map/115學測數學_矩陣.html#kp3"}], "steps": [{"type": "text", "c": "把題目那個 2×2 矩陣的兩行分別代入，得到 A 對兩個向量的作用："}, {"type": "math", "c": "A\\begin{bmatrix}1\\\\-1\\end{bmatrix}=\\begin{bmatrix}4\\\\-2\\\\3\\end{bmatrix},\\qquad A\\begin{bmatrix}0\\\\1\\end{bmatrix}=\\begin{bmatrix}-6\\\\1\\\\5\\end{bmatrix}"}, {"type": "text", "c": "【法一】矩陣乘法有線性。所求向量可拆成上面兩個向量的和："}, {"type": "math", "c": "\\begin{bmatrix}1\\\\0\\end{bmatrix}=\\begin{bmatrix}1\\\\-1\\end{bmatrix}+\\begin{bmatrix}0\\\\1\\end{bmatrix}"}, {"type": "math", "c": "A\\begin{bmatrix}1\\\\0\\end{bmatrix}=A\\begin{bmatrix}1\\\\-1\\end{bmatrix}+A\\begin{bmatrix}0\\\\1\\end{bmatrix}=\\begin{bmatrix}4\\\\-2\\\\3\\end{bmatrix}+\\begin{bmatrix}-6\\\\1\\\\5\\end{bmatrix}=\\begin{bmatrix}-2\\\\-1\\\\8\\end{bmatrix}"}, {"type": "math", "c": "\\begin{bmatrix}a\\\\b\\\\c\\end{bmatrix}=\\begin{bmatrix}-2\\\\-1\\\\8\\end{bmatrix}\\Rightarrow a+b+c=-2-1+8=5"}, {"type": "text", "c": "【法二】用反方陣。設題目的 2×2 矩陣為 M、3×2 乘積為 B，由 AM=B 右乘 M⁻¹ 得 A=BM⁻¹："}, {"type": "math", "c": "M=\\begin{bmatrix}1&0\\\\-1&1\\end{bmatrix},\\quad M^{-1}=\\begin{bmatrix}1&0\\\\1&1\\end{bmatrix}"}, {"type": "math", "c": "A\\begin{bmatrix}1\\\\0\\end{bmatrix}=B\\,M^{-1}\\begin{bmatrix}1\\\\0\\end{bmatrix}=\\begin{bmatrix}4&-6\\\\-2&1\\\\3&5\\end{bmatrix}\\begin{bmatrix}1\\\\1\\end{bmatrix}=\\begin{bmatrix}-2\\\\-1\\\\8\\end{bmatrix}"}, {"type": "text", "c": "同樣得 a+b+c=5。選 (4)。"}]}, {"subject": "B", "year": "114", "num": 3, "type": "單選", "rate": "55%", "img": "img/114B_q03.png", "answer": [{"t": "(3)　"}, {"m": "\\log(a^2)"}], "key": "½<a<1 → log a 是負的；log(a²)=2·log a 是它的兩倍（更負）；1<b<2 → log b 是小正數，1/log b 是大正數。", "kaodian": [{"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "../concept-map/115學測數學_指數與對數.html#kp2"}, {"unit": "指數與對數", "title": "考點4 指數與對數函數的圖形", "url": "../concept-map/115學測數學_指數與對數.html#kp4"}], "steps": [{"type": "text", "c": "a 在 ½ 與 1 之間 → log a 為負（log 是常用對數，log1=0）。"}, {"type": "math", "c": "\\log(a^2)=2\\log a<\\log a<0"}, {"type": "text", "c": "所以 log(a²) 比 log a 更小（更負）。"}, {"type": "text", "c": "另一邊 b 在 1 與 2 之間 → log b 是小正數 >0，1/log b 是大正數。"}, {"type": "text", "c": "由小到大：log(a²) < log a < 0 < log b < 1/log b，最小的是 log(a²)。選 (3)。"}]}, {"subject": "B", "year": "114", "num": 4, "type": "單選", "rate": "35%", "img": "img/114B_q04.png", "answer": [{"t": "(4)　"}, {"m": "\\dfrac{9}{16}"}], "key": "抽 4 次剛好出現 3 種款式 → 一定是「某一種抽到 2 次、另兩種各 1 次」；先選是哪 3 種、哪種重複，再排位置。", "kaodian": [{"unit": "排列組合與機率", "title": "考點3 古典機率：好的情形 ÷ 全部情形", "url": "../concept-map/115學測數學_排列組合與機率.html#kp3"}, {"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}], "steps": [{"type": "text", "c": "每次從 4 種等機率抽 1 個，抽 4 次，全部情形 4⁴=256。"}, {"type": "text", "c": "恰 3 種：先選出現的 3 種 C(4,3)=4；這 3 種要湊 4 次，必是一種 2 次、另兩種各 1 次——選哪種重複 3 種；4 個位置排 {X,X,Y,Z} 有 4!/2!=12 種："}, {"type": "math", "c": "\\text{好的情形}=C(4,3)\\times 3\\times \\dfrac{4!}{2!}=4\\times3\\times12=144"}, {"type": "math", "c": "P=\\dfrac{144}{256}=\\dfrac{9}{16}"}, {"type": "text", "c": "選 (4)。"}]}, {"subject": "B", "year": "114", "num": 5, "type": "單選", "rate": "30%", "img": "img/114B_q05.png", "answer": [{"t": "(1)　雙曲線"}], "key": "平面切圓錐的截痕，看「平面與軸的夾角」和「圓錐半角」誰大：平面平行於軸（夾角 0°）小於半角，得雙曲線。", "kaodian": [], "steps": [{"type": "text", "c": "M 繞 L 轉一圈得直圓錐面，半角（軸 L 到母線 M）=24°。"}, {"type": "text", "c": "平面 E 與軸 L 平行 → E 與軸的夾角 =0°，小於半角 24°。"}, {"type": "text", "c": "截痕判別：平面與軸夾角 < 半角 → 雙曲線（平面同時切到圓錐的上下兩葉）。選 (1)。"}]}, {"subject": "B", "year": "114", "num": 6, "type": "單選", "rate": "56%", "img": "img/114B_q06.png", "answer": [{"t": "(2)　a>c>b"}], "key": "代入能讓兩項歸零的 x（1、3、4），每次只剩一項，馬上解出 a、b、c。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "../concept-map/115學測數學_多項式函數.html#kp1"}], "steps": [{"type": "text", "c": "f(x)=x²。分別代入讓兩項變 0 的 x："}, {"type": "math", "c": "x=1:\\ c(1-3)(1-4)=6c=1\\Rightarrow c=\\tfrac16"}, {"type": "math", "c": "x=3:\\ b(3-1)(3-4)=-2b=9\\Rightarrow b=-\\tfrac92"}, {"type": "math", "c": "x=4:\\ a(4-1)(4-3)=3a=16\\Rightarrow a=\\tfrac{16}{3}"}, {"type": "text", "c": "比大小：a=16/3≈5.33 > c=1/6 > b=-4.5，即 a>c>b。選 (2)。"}]}, {"subject": "B", "year": "114", "num": 7, "type": "單選", "rate": "23%", "img": "img/114B_q07.png", "answer": [{"t": "(4)　D"}], "key": "透視中，鉛直柱子的實際高度正比於「柱頂-柱底」÷「地平線 y - 柱底 y」；用 A、F 高度相等驗證這個比值，再比出最大。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}], "steps": [{"type": "text", "c": "地平線在消失點 V=(4,9) 的高度 y=9。實際高度 ∝（畫面上柱高）÷（柱底到地平線的距離）=（頂 y - 底 y）÷（9 - 底 y）。"}, {"type": "text", "c": "先驗證 A、F：兩者都是 (8-6)/(9-6)=2/3，相等 ✓，符合題目。"}, {"type": "text", "c": "逐柱計算：A=2/3、B=3/9=1/3、C=3/6=1/2、D=3/4、E=4/8=1/2、F=2/3。"}, {"type": "text", "c": "最大的是 D=3/4。選 (4)。"}]}, {"subject": "B", "year": "114", "num": 8, "type": "多選", "rate": "43%（全對率 25%）", "img": "img/114B_q08.png", "answer": [{"t": "(1)(5)"}], "key": "y=x³-x 是奇函數（對稱原點）；判斷平移、鏡射要看「形狀」是否一樣：有沒有起伏（局部極值）。", "kaodian": [{"unit": "多項式函數", "title": "考點5 三次函數圖形與對稱中心", "url": "../concept-map/115學測數學_多項式函數.html#kp5"}], "steps": [{"type": "text", "c": "(1)：f(-x)=-x³+x=-f(x)，奇函數 → 圖形對稱於原點，正確。"}, {"type": "text", "c": "(5)：對 y 軸鏡射是把 x 換成 -x：y=(-x)³-(-x)=-x³+x，正好是選項的函數，正確。"}, {"type": "text", "c": "(2)：x≈0 時 y=x³-x≈-x（不是 y=x），錯。"}, {"type": "text", "c": "(3)：y=x³+x（斜率 3x²+1>0）一路遞增沒有起伏；y=x³-x 有局部高低點，形狀不同，平移不能重合，錯。"}, {"type": "text", "c": "(4)：對 x 軸鏡射得 y=-x³+x，不是 y=x³+x，錯。答 (1)(5)。"}]}, {"subject": "B", "year": "114", "num": 9, "type": "多選", "rate": "52%（全對率 30%）", "img": "img/114B_q09.png", "answer": [{"t": "(2)(3)(4)"}], "key": "OP=αOA+βOB 且 0≤α,β≤1，代表 P 落在以 OA、OB 為兩邊的平行四邊形內；逐一解 α、β 看是否都在 0~1。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}, {"unit": "平面向量", "title": "考點1 向量的表示、運算與平行", "url": "../concept-map/115學測數學_平面向量.html#kp1"}], "steps": [{"type": "text", "c": "把 P=(2,2) 寫成 αA+βB，解出 α、β，看是否都落在 [0,1]。"}, {"type": "text", "c": "(2) A(3,2),B(3,4)：得 α=β=1/3，成立 ✓。"}, {"type": "text", "c": "(3) A(3,4),B(4,-1)：得 α=10/19、β=2/19，成立 ✓。"}, {"type": "text", "c": "(4) A(1,2),B(2,1)：得 α=β=2/3，成立 ✓。"}, {"type": "text", "c": "(1) A(2,-3),B(-4,3)：解得 β=-5/3<0，不合。(5) A(1,-1),B(1,1)：解得 β=2>1，不合。答 (2)(3)(4)。"}]}, {"subject": "B", "year": "114", "num": 10, "type": "多選", "rate": "46%（全對率 21%）", "img": "img/114B_q10.png", "answer": [{"t": "(1)(2)(5)"}], "key": "總用時 = 次數 × 平均；標準差大不代表全距大；標準差 0.3 卻要求全部落在寬 0.2 的區間是不可能的。", "kaodian": [{"unit": "數據分析", "title": "考點1 一維數據：平均、中位數與標準差", "url": "../concept-map/115學測數學_數據分析.html#kp1"}], "steps": [{"type": "text", "c": "(1)：每次殺球平均 甲1.2、乙1.5、丙1.7、丁1.2，丙最多，正確。"}, {"type": "text", "c": "(2)：總用時 = 次數×平均：甲30、乙21、丙34、丁36，丁最多，正確。"}, {"type": "text", "c": "(5)：乙平均1.5、標準差0.3。若全部落在 [1.4,1.6]，離平均最多差 0.1，標準差就 ≤0.1，與 0.3 矛盾 → 不可能，正確。"}, {"type": "text", "c": "(3)：甲、丁平均都1.2 但標準差不同（0.5、0.4），不可能每次都相同，錯。"}, {"type": "text", "c": "(4)：標準差大不代表全距（最大-最小）大，無法斷定，錯。答 (1)(2)(5)。"}]}, {"subject": "B", "year": "114", "num": 11, "type": "多選", "rate": "47%（全對率 23%）", "img": "img/114B_q11.png", "answer": [{"t": "(1)(3)(4)"}], "key": "球面最短路徑用「圓心角」量：離北極的角 = 90°-緯度；經度 0° 與 180° 兩條經線接成一個大圓（過南北極）。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "以圓心角度量（半徑 R）。A、B 都在北緯60° → 離北極都 30°，故北極到 A =北極到 B，(1) 正確。"}, {"type": "text", "c": "A、E 都在經度 0° 的同一條經線（大圓）上，C（北緯30°）在 A（北緯60°）與 E（赤道）之間，故 A→E 必過 C，(3) 正確。"}, {"type": "text", "c": "C(0°,30°N)、D(180°,30°N) 在「0°–180°」經線大圓上，過北極的一段 =60°+60°=120°，比過南極短，故 C→D 必過北極，(4) 正確。"}, {"type": "text", "c": "(2)：A→B（過北極）=30°+30°=60°，C→D=120°，不相等，錯。"}, {"type": "text", "c": "(5)：E→北極 =90°、C→D=120°，比為 90:120=3:4，不是 2:3，錯。答 (1)(3)(4)。"}]}, {"subject": "B", "year": "114", "num": 12, "type": "多選", "rate": "29%（全對率 6%）", "img": "img/114B_q12.png", "answer": [{"t": "(1)(2)"}], "key": "首項1、末項81，公差 d 要讓 8（=9-1）與 80（=81-1）都是 d 的整數倍；設 8=md，得項數 n=10m+1。", "kaodian": [{"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "../concept-map/115學測數學_數列與級數.html#kp1"}], "steps": [{"type": "text", "c": "首項1、末項81，(n-1)d=80。9 也在數列 → 8=md（m 為正整數），兩式相除得 (n-1)/m=10，故 n=10m+1、d=8/m。"}, {"type": "text", "c": "由 n≤100 得 m=1~9，共 9 個數列，n=11,21,…,91 全是奇數 → (1) 正確。"}, {"type": "text", "c": "41 是否在數列：41-1=40=5m·d（因 d=8/m，5m·d=40），是第 (5m+1) 項，一定在 → (2) 正確。"}, {"type": "text", "c": "(3)：m=3 時 d=8/3 不是整數，錯。(4)：共 9 個不是 10，錯。(5)：n 為 7 倍數者有 21 與 91，不只 21，錯。答 (1)(2)。"}]}, {"subject": "B", "year": "114", "num": 13, "type": "選填", "rate": "44%", "img": "img/114B_q13.png", "answer": [{"t": "0.51"}], "key": "「至少一個有空位」用餘事件最快：1 -（兩個都沒空位）。", "kaodian": [{"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "../concept-map/115學測數學_排列組合與機率.html#kp5"}], "steps": [{"type": "text", "c": "兩停車場沒空位的機率各 0.7 且獨立。至少一個有空位 = 1 -（兩個都沒空位）："}, {"type": "math", "c": "1-0.7\\times0.7=1-0.49=0.51"}, {"type": "text", "c": "答 0.51。"}]}, {"subject": "B", "year": "114", "num": 14, "type": "選填", "rate": "17%", "img": "img/114B_q14.png", "answer": [{"m": "\\dfrac{5}{6}"}], "key": "y=mx 過原點 O，而 O 剛好在底邊 BC 上；用「切出含 C 的小三角形面積 = 一半」列式求 m。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}, {"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "../concept-map/115學測數學_直線與圓.html#kp2"}], "steps": [{"type": "text", "c": "三角形 ABC：A(0,2)、B(-1,0)、C(4,0)，面積 =½·|BC|·高 =½·5·2=5，一半是 2.5。"}, {"type": "text", "c": "y=mx 過原點 O(0,0)（在 BC 上），交 AC 於 P。P 在 AC 上：AC 從 (0,2) 到 (4,0) 參數化 (4t, 2-2t)，代 y=mx 得 t=1/(1+2m)。"}, {"type": "text", "c": "含 C 的三角形 OPC 面積 =½·OC·(P 的高)=½·4·(2-2t)=4-4t，令 =2.5："}, {"type": "math", "c": "4-4t=2.5\\Rightarrow t=\\tfrac38,\\quad \\tfrac{1}{1+2m}=\\tfrac38\\Rightarrow m=\\dfrac56"}, {"type": "text", "c": "答 5/6。"}]}, {"subject": "B", "year": "114", "num": 15, "type": "選填", "rate": "25%", "img": "img/114B_q15.png", "answer": [{"t": "36"}], "key": "2 位翻譯剛好一部門一位（2 種）；剩下 3 工程師+3 助理各挑 3 人到研發，扣掉「某部門沒工程師」的情況。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}], "steps": [{"type": "text", "c": "每部門要 1 位翻譯，剛好 2 位翻譯各去一部門：2 種。"}, {"type": "text", "c": "其餘 3 工程師+3 助理，研發還要 3 人（測試自動得另 3 人）。從 6 人選 3 給研發 C(6,3)=20，扣掉「研發全助理（工程師 0）」與「研發全工程師（測試工程師 0）」各 1 種："}, {"type": "math", "c": "20-1-1=18"}, {"type": "text", "c": "總數 =2×18=36。答 36。"}]}, {"subject": "B", "year": "114", "num": 16, "type": "選填", "rate": "43%", "img": "img/114B_q16.png", "answer": [{"m": "\\dfrac{\\sqrt{6}}{2}"}], "key": "牆角三邊兩兩垂直，當坐標軸；A、B、C 放到三軸上，先用空間兩點距離求三角形三邊，再用餘弦定理求 ∠CAB。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "../concept-map/115學測數學_三角.html#kp2"}], "steps": [{"type": "text", "c": "牆角 O 為原點，三條垂直交界線當 x、y、z 軸。A、B、C 與 O 距離 20、20、10，放成 A(20,0,0)、B(0,20,0)、C(0,0,10)。"}, {"type": "text", "c": "用空間兩點距離公式求 △CAB 的三邊："}, {"type": "math", "c": "AB=\\sqrt{20^2+20^2}=20\\sqrt2,\\quad AC=\\sqrt{20^2+10^2}=10\\sqrt5,\\quad BC=\\sqrt{20^2+10^2}=10\\sqrt5"}, {"type": "text", "c": "在 △CAB 對頂點 A 用餘弦定理："}, {"type": "math", "c": "\\cos\\angle CAB=\\dfrac{AB^2+AC^2-BC^2}{2\\cdot AB\\cdot AC}=\\dfrac{800+500-500}{2\\cdot20\\sqrt2\\cdot10\\sqrt5}=\\dfrac{2}{\\sqrt{10}}"}, {"type": "text", "c": "再由 sin²=1-cos²=6/10 換成 tan："}, {"type": "math", "c": "\\tan\\angle CAB=\\dfrac{\\sqrt{6}/\\sqrt{10}}{2/\\sqrt{10}}=\\dfrac{\\sqrt6}{2}"}, {"type": "text", "c": "答 √6/2。"}]}, {"subject": "B", "year": "114", "num": 17, "type": "選填", "rate": "11%", "img": "img/114B_q17.png", "answer": [{"t": "13"}], "key": "先找出「紅、綠同時暗」的所有時刻（週期 lcm=24 內），再要求那些時刻藍燈都亮著，逼出 k 的最小值。", "kaodian": [{"unit": "數列與級數", "title": "考點4 級數求和與規律、週期", "url": "../concept-map/115學測數學_數列與級數.html#kp4"}], "steps": [{"type": "text", "c": "紅週期 6，暗在 t mod6∈[3,4)；綠週期 8，暗在 t mod8∈[6,8)；藍週期 15，暗在 t mod15∈[k,15)。"}, {"type": "text", "c": "紅、綠同時暗的時刻（週期 120 內）為 [15,16),[39,40),[63,64),[87,88),[111,112)，換算 t mod15 分別落在 [0,1),[9,10),[3,4),[12,13),[6,7)。"}, {"type": "text", "c": "要面板一直有燈亮 → 這些時刻藍燈都要亮（t mod15<k）。其中最大到 13（區間 [12,13)），故 k 至少要 13："}, {"type": "math", "c": "k_{\\min}=13"}, {"type": "text", "c": "答 13。"}]}, {"subject": "B", "year": "114", "num": 18, "type": "混合題（單選 3 分）", "rate": "49%", "img": "img/114B_q18.png", "answer": [{"t": "(3)　"}, {"m": "4(1+0.04)^{15}"}], "key": "地面 UVI = 400÷100 = 4；每上升 300 公尺乘一次 1.04，4500÷300 = 15 次，是等比連乘。", "kaodian": [{"unit": "指數與對數", "title": "考點5 指對數的應用：成長衰退模型與數列", "url": "../concept-map/115學測數學_指數與對數.html#kp5"}, {"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "../concept-map/115學測數學_數列與級數.html#kp2"}], "steps": [{"type": "text", "c": "1 單位 UVI=每平方公尺 100 焦耳，地面收到 400 焦耳 → 地面 UVI =400/100=4。"}, {"type": "text", "c": "高度每升 300 公尺，UVI ×(1+4%)=×1.04。升到 4500 公尺共 4500/300=15 次："}, {"type": "math", "c": "\\text{UVI}=4\\times(1+0.04)^{15}"}, {"type": "text", "c": "選 (3)。"}], "stem": "img/114B_stem.png"}, {"subject": "B", "year": "114", "num": 19, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/114B_q19.png", "answer": [{"t": "a=8，"}, {"m": "b=\\dfrac{\\pi}{12}"}], "key": "f(12)=0 且日照時 f>0，代表 12 是 sin 的第一個零點 → 12b=π；再用 f(2)=4 求 a。", "kaodian": [{"unit": "三角", "title": "考點4 三角函數圖形：週期、對稱與疊合", "url": "../concept-map/115學測數學_三角.html#kp4"}], "steps": [{"type": "text", "c": "f(x)=a sin(bx)，f(0)=0 自動成立。日照時 f>0、f(12)=0，所以 12 是 sin 從 0 之後第一個零點："}, {"type": "math", "c": "12b=\\pi\\Rightarrow b=\\dfrac{\\pi}{12}"}, {"type": "text", "c": "再用日出後 2 小時 UVI=4，即 f(2)=4："}, {"type": "math", "c": "a\\sin\\!\\left(2\\cdot\\tfrac{\\pi}{12}\\right)=a\\sin\\tfrac{\\pi}{6}=\\tfrac{a}{2}=4\\Rightarrow a=8"}, {"type": "text", "c": "答 a=8，b=π/12。"}], "stem": "img/114B_stem.png"}, {"subject": "B", "year": "114", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/114B_q20.png", "answer": [{"m": "3\\le t\\le 4\\ \\text{或}\\ 8\\le t\\le 9"}], "key": "把 4√2≤f(t)≤4√3 化成 √2/2≤sin(πt/12)≤√3/2，找出角度落在哪兩段，再換回 t。", "kaodian": [{"unit": "三角", "title": "考點4 三角函數圖形：週期、對稱與疊合", "url": "../concept-map/115學測數學_三角.html#kp4"}, {"unit": "三角", "title": "考點5 和差角與倍角（解方程與不等式）", "url": "../concept-map/115學測數學_三角.html#kp5"}], "steps": [{"type": "text", "c": "由第 19 題 f(t)=8 sin(πt/12)。要 4√2 ≤ 8 sin(πt/12) ≤ 4√3，兩邊除以 8："}, {"type": "math", "c": "\\dfrac{\\sqrt2}{2}\\le \\sin\\!\\left(\\tfrac{\\pi t}{12}\\right)\\le \\dfrac{\\sqrt3}{2}"}, {"type": "text", "c": "令 θ=πt/12（t∈[0,12] → θ∈[0,π]）。sinθ 介於 √2/2 與 √3/2 的角度為："}, {"type": "math", "c": "\\theta\\in\\left[\\tfrac{\\pi}{4},\\tfrac{\\pi}{3}\\right]\\cup\\left[\\tfrac{2\\pi}{3},\\tfrac{3\\pi}{4}\\right]"}, {"type": "text", "c": "換回 t=12θ/π："}, {"type": "math", "c": "3\\le t\\le 4\\quad\\text{或}\\quad 8\\le t\\le 9"}, {"type": "text", "c": "答：日出後 3~4 小時，或 8~9 小時。"}], "stem": "img/114B_stem.png"}, {"subject": "A", "year": "115", "num": 1, "type": "單選", "rate": "84%", "img": "img/115_q01.png", "answer": [{"t": "(2)　30 元"}], "key": "把「每種獎金 × 拿到它的機率」全部加起來，就是期望值。", "kaodian": [{"unit": "排列組合與機率", "title": "考點6 期望值（長期平均）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp6"}, {"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "../concept-map/115學測數學_排列組合與機率.html#kp5"}], "steps": [{"type": "text", "c": "兩次抽籤互不影響，所以「兩次的結果」機率要相乘。"}, {"type": "text", "c": "• 兩次都抽到「吉」→ 得 180 元，機率是："}, {"type": "math", "c": "\\dfrac{1}{3}\\times\\dfrac{1}{3}=\\dfrac{1}{9}"}, {"type": "text", "c": "• 兩次都抽到「祥」→ 得 90 元，機率也是 1/9。其餘情況沒有獎金（算 0 元）。"}, {"type": "text", "c": "期望值 =（獎金 × 機率）逐項相加："}, {"type": "math", "c": "E=180\\times\\dfrac{1}{9}+90\\times\\dfrac{1}{9}=20+10=30\\ (\\text{元})"}, {"type": "text", "c": "所以答案是 (2) 30 元。"}]}, {"subject": "A", "year": "115", "num": 2, "type": "單選", "rate": "55%", "img": "img/115_q02.png", "answer": [{"t": "(1)"}], "key": "[x] 是「不超過 x 的最大整數」；把每個根號夾在兩個整數之間，取整數部分。", "kaodian": [{"unit": "數與式", "title": "考點6 高斯函數（最大整數函數）", "url": "../concept-map/115學測數學_數與式.html#kp6"}, {"unit": "數與式", "title": "考點3 數線上的點、距離、分點與根號估算", "url": "../concept-map/115學測數學_數與式.html#kp3"}], "steps": [{"type": "text", "c": "記住整數平方：9²=81、10²=100、11²=121，用它們夾出根號在哪兩個整數之間。"}, {"type": "text", "c": "x=-20：√119 在 10 與 11 之間 → 取 10；√79 在 8 與 9 之間 → 取 8。"}, {"type": "math", "c": "f(-20)=[\\sqrt{119}]+[\\sqrt{79}]=10+8=18"}, {"type": "text", "c": "x=0：√99 在 9 與 10 之間 → 取 9，兩個都是 9。"}, {"type": "math", "c": "f(0)=[\\sqrt{99}]+[\\sqrt{99}]=9+9=18"}, {"type": "text", "c": "x=1：√98 取 9，√100 剛好等於 10。"}, {"type": "math", "c": "f(1)=[\\sqrt{98}]+[\\sqrt{100}]=9+10=19"}, {"type": "text", "c": "比較：f(-20)=f(0)=18，都小於 f(1)=19，即 f(-20) ≤ f(0) < f(1)，選 (1)。"}]}, {"subject": "A", "year": "115", "num": 3, "type": "單選", "rate": "41%", "img": "img/115_q03.png", "answer": [{"t": "(1)　"}, {"m": "2^{-6/5}"}], "key": "指數每加一個公差 d，函數值就乘上 a^d——這個倍數正好是等比的公比。", "kaodian": [{"unit": "指數與對數", "title": "考點1 指數律與指數方程", "url": "../concept-map/115學測數學_指數與對數.html#kp1"}, {"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "../concept-map/115學測數學_數列與級數.html#kp2"}], "steps": [{"type": "text", "c": "因為 f(x)=aˣ，相鄰兩項相除時指數相減，剛好差一個公差 10/3："}, {"type": "math", "c": "\\dfrac{f(c_2)}{f(c_1)}=a^{\\,c_2-c_1}=a^{10/3}=4\\ \\ (\\text{題目說公比是 }4)"}, {"type": "text", "c": "把 4 寫成 2 的次方（4=2²），解出底數 a："}, {"type": "math", "c": "a=4^{3/10}=\\left(2^{2}\\right)^{3/10}=2^{3/5}"}, {"type": "text", "c": "同樣地，f(10),f(8),f(6) 的公比是後項除前項，指數差 8-10=-2："}, {"type": "math", "c": "\\dfrac{f(8)}{f(10)}=a^{-2}=\\left(2^{3/5}\\right)^{-2}=2^{-6/5}"}, {"type": "text", "c": "所以公比是 2^(-6/5)，選 (1)。"}]}, {"subject": "A", "year": "115", "num": 4, "type": "單選", "rate": "56%", "img": "img/115_q04.png", "answer": [{"t": "(3)　401"}], "key": "把「取 3 種材料」的情況分三類，分別數出「會產生幾種道具」再相加。", "kaodian": [{"unit": "排列組合與機率", "title": "考點2 組合與分組分配", "url": "../concept-map/115學測數學_排列組合與機率.html#kp2"}, {"unit": "排列組合與機率", "title": "考點1 計數原理與排列", "url": "../concept-map/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "注意問的是「共可合成幾種道具」，不是幾種取法。分三類："}, {"type": "text", "c": "① 3 種都是基本材料 → 不管哪三種，結果都是同一種草藥 → 只算 1 種。"}, {"type": "text", "c": "② 2 基本 + 1 進階 → 結果只看那 1 種進階材料（10 選 1），基本不影響 → 10 種食物。"}, {"type": "text", "c": "③ 其餘情況（1 基本+2 進階，或 3 進階）→ 每一種不同的材料組合都是不同藥水，所以「組合數」就是藥水種數："}, {"type": "math", "c": "\\binom{6}{1}\\binom{10}{2}+\\binom{10}{3}=6\\times 45+120=390"}, {"type": "text", "c": "三類相加：1 + 10 + 390 = 401，選 (3)。"}]}, {"subject": "A", "year": "115", "num": 5, "type": "單選", "rate": "26%", "img": "img/115_q05.png", "answer": [{"t": "(5)　無窮多個"}], "key": "矩陣乘法可「拆開相加」；把已知的式子湊出目標，再加上「乘完變 0 的方向」得到一整條解。", "kaodian": [{"unit": "矩陣", "title": "考點1 矩陣的意義、相等與乘法", "url": "../concept-map/115學測數學_矩陣.html#kp1"}, {"unit": "矩陣", "title": "考點4 一次聯立方程式與高斯消去法", "url": "../concept-map/115學測數學_矩陣.html#kp4"}], "steps": [{"type": "text", "c": "矩陣作用在向量上可以拆開：A(u+v)=Au+Av。先把題目三個式子記成："}, {"type": "math", "c": "A(1,1,0)=(0,-1,1),\\quad A(0,-1,1)=(1,1,0),\\quad A(1,0,-1)=(0,0,0)"}, {"type": "text", "c": "想要 Av=(1,0,1)。觀察：把前兩式左右相加，右邊剛好是 (1,0,1)："}, {"type": "math", "c": "A\\big[(1,1,0)+(0,-1,1)\\big]=(0,-1,1)+(1,1,0)=(1,0,1)"}, {"type": "text", "c": "所以 v=(1,0,1) 是一個解。又因為 A(1,0,-1)=(0,0,0)，把 (1,0,-1) 的任意倍加上去，乘完多出來的是 0，值不變："}, {"type": "math", "c": "\\vec{v}=(1,0,1)+t\\,(1,0,-1)=(1+t,\\ 0,\\ 1-t)"}, {"type": "text", "c": "這些解的第二個分量都是 0，而「垂直於 (0,1,0)」正好就是第二分量為 0（內積=0）。所以每個解都符合，共有無窮多個，選 (5)。"}]}, {"subject": "A", "year": "115", "num": 6, "type": "單選", "rate": "37%", "img": "img/115_q06.png", "answer": [{"t": "(2)　2 個"}], "key": "等腰有三種可能（哪一邊是頂角）；算完別忘了把「三點共線」的假三角形刪掉。", "kaodian": [{"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "../concept-map/115學測數學_直線與圓.html#kp2"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "先算 AB=5。設 C=(c, -6)（在直線 y=-6 上），分三種情形："}, {"type": "text", "c": "① CA=CB（C 到 A、B 一樣遠）→ C 在 AB 的中垂線上，中垂線和 y=-6 交在 1 個點（c=-15/2）。"}, {"type": "math", "c": "②\\ \\overline{AC}=\\overline{AB}=5:\\ (c-2)^2+(-6+2)^2=25\\Rightarrow c=5\\ \\text{或}\\ -1"}, {"type": "math", "c": "③\\ \\overline{BC}=\\overline{AB}=5:\\ (c+1)^2+(-6-2)^2=25\\ \\text{（算出無解）}"}, {"type": "text", "c": "初步得到 c=-15/2、5、-1 三個點。但 C=(5,-6) 剛好落在直線 AB 上（A、B、C 連成一直線），不是三角形，要刪掉！"}, {"type": "text", "c": "所以真正合格的只有 (-15/2,-6) 和 (-1,-6)，共 2 個，選 (2)。（見右圖）"}], "fig": "img/115_fig_q06.png"}, {"subject": "A", "year": "115", "num": 7, "type": "多選", "rate": "74%（全對率 66%）", "img": "img/115_q07.png", "answer": [{"t": "(3)(4)"}], "key": "把兩個不等式各畫成半平面，交集在哪個象限，用一個代表點去試最快。", "kaodian": [{"unit": "直線與圓", "title": "考點5 平面區域與線性規劃", "url": "../concept-map/115學測數學_直線與圓.html#kp5"}], "steps": [{"type": "text", "c": "兩條件整理成：y < 2x-3（在這條線下方）且 y < -x/2 - 1/2（在那條線下方）。"}, {"type": "text", "c": "第一、二象限：要 y 是正的，但第二式要 y < 負數，矛盾 → 不可能。"}, {"type": "text", "c": "第三象限：試 (-10,-24)，兩式都成立 → 可以。"}, {"type": "text", "c": "第四象限：試 (3,-3)，兩式都成立 → 可以。"}, {"type": "text", "c": "x 軸（y=0）：第一式要 x>3/2，第二式要 x<-1，不能同時 → 不可能。"}, {"type": "text", "c": "所以點可能在第三、第四象限，選 (3)(4)。"}]}, {"subject": "A", "year": "115", "num": 8, "type": "多選", "rate": "70%（全對率 56%）", "img": "img/115_q08.png", "answer": [{"t": "(2)(5)"}], "key": "先算 A²，發現 A²=2A+I（可直接驗證）；再利用「A 對稱 → Aⁿ 也對稱」。", "kaodian": [{"unit": "矩陣", "title": "考點2 矩陣的高次方 Aⁿ", "url": "../concept-map/115學測數學_矩陣.html#kp2"}, {"unit": "數列與級數", "title": "考點3 遞迴數列：構造等比與數學歸納法", "url": "../concept-map/115學測數學_數列與級數.html#kp3"}], "steps": [{"type": "math", "c": "A=\\begin{bmatrix}2&1\\\\1&0\\end{bmatrix}\\Rightarrow A^2=\\begin{bmatrix}5&2\\\\2&1\\end{bmatrix}"}, {"type": "text", "c": "(1) 由 A² 讀出 b₂=2、c₂=2，兩者相等，不是 b₂<c₂ → 錯。"}, {"type": "text", "c": "(2) 直接檢查：2A+I 的四個位置算出來剛好等於 A²（下式），對！"}, {"type": "math", "c": "2A+\\begin{bmatrix}1&0\\\\0&1\\end{bmatrix}=\\begin{bmatrix}5&2\\\\2&1\\end{bmatrix}=A^2"}, {"type": "text", "c": "(3) 兩邊同乘 Aⁿ 得 A^(n+2)=2A^(n+1)+Aⁿ，所以每格都是 x_(n+2)=2x_(n+1)+x_n，和題目寫的不同 → 錯。"}, {"type": "text", "c": "(4) 矩陣乘直行 (0,1) 等於「取出第二直行」＝(bₙ,dₙ)，不會變成下一項 → 錯。"}, {"type": "text", "c": "(5) A 對稱，所以 Aⁿ 也對稱（bₙ=cₙ）。把 Aⁿ 平方看 A^(2n) 的左上與右下："}, {"type": "math", "c": "a_{2n}=a_n^{2}+b_n^{2},\\quad d_{2n}=b_n^{2}+d_n^{2}\\ \\Rightarrow\\ d_{2n}-a_{2n}=d_n^{2}-a_n^{2}"}, {"type": "text", "c": "相減時 bₙ² 消掉 → 對。故選 (2)(5)。"}]}, {"subject": "A", "year": "115", "num": 9, "type": "多選", "rate": "44%（全對率 21%）", "img": "img/115_q09.png", "answer": [{"t": "(1)(2)(4)"}], "key": "T 分數是把原始分做一條直線變換：斜率 10/σ。σ 越小，同樣的分差被放得越大。", "kaodian": [{"unit": "數據分析", "title": "考點1 一維數據：平均、中位數與標準差", "url": "../concept-map/115學測數學_數據分析.html#kp1"}, {"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "../concept-map/115學測數學_數據分析.html#kp3"}], "steps": [{"type": "math", "c": "T=50+\\dfrac{10}{\\sigma}(S-\\mu):\\quad \\text{數學斜率}=\\dfrac{10}{12}=\\dfrac{5}{6},\\ \\ \\text{英文斜率}=\\dfrac{10}{8}=\\dfrac{5}{4}"}, {"type": "text", "c": "(1) 英文 S=52：T=50+(5/4)×(52-60)=50-10=40 → 對。"}, {"type": "text", "c": "(2) 數學：T-S = -S/6，因成績 S≥0 所以 T-S≤0，即 T 不超過原始分 → 對。"}, {"type": "text", "c": "(3) 英文的放大倍率(5/4)比數學(5/6)大。就算兩科原始平均較高，換成 T 分數後不一定較高（可舉反例）→ 錯。"}, {"type": "text", "c": "(4) 要 T≥40：數學需 S≥48、英文需 S≥52。數學的及格門檻比較低 → 對。"}, {"type": "text", "c": "(5) T 分數會把兩科標準差都變成 10，所以「數學對英文」迴歸斜率＝相關係數 r；但用原始分是 r×(12/8)，兩者不同 → 錯。"}, {"type": "text", "c": "故選 (1)(2)(4)。"}]}, {"subject": "A", "year": "115", "num": 10, "type": "多選", "rate": "36%（全對率 10%）", "img": "img/115_q10.png", "answer": [{"t": "(1)(5)"}], "key": "梯形對角線的交點會依「上底:下底」分割；面積用行列式算，再逐項檢查。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}, {"unit": "平面向量", "title": "考點4 行列式與平行四邊形面積", "url": "../concept-map/115學測數學_平面向量.html#kp4"}], "steps": [{"type": "text", "c": "設 A 為原點，AB=(2,-6)、AD=(1,5)。三角形 ABD 面積用行列式：½|2·5-(-6)·1|=8。"}, {"type": "text", "c": "梯形中 AB∥DC，對角線交點 E 使 BE:ED = AB:DC = 1:k。由「E 到 AB 的高 = D 的高的 1/(1+k)」："}, {"type": "math", "c": "\\dfrac{1}{1+k}\\times 8=3\\ \\Rightarrow\\ k=\\dfrac{5}{3},\\quad \\text{可求得 }C=\\left(\\tfrac{13}{3},-5\\right)"}, {"type": "math", "c": "(1)\\ \\cos\\angle BAD=\\dfrac{\\vec{AB}\\cdot\\vec{AD}}{|\\vec{AB}||\\vec{AD}|}=\\dfrac{2-30}{2\\sqrt{10}\\cdot\\sqrt{26}}=\\dfrac{-7\\sqrt{65}}{65}\\ \\text{（對）}"}, {"type": "text", "c": "(2) △ABD=8，不是 9 → 錯。　(3) 由分點求 AE=(3/8)AC=(13/8, -15/8)，不是 (3/2,1/2) → 錯。"}, {"type": "math", "c": "(4)\\ \\text{四邊形面積}=\\dfrac{64}{3}\\neq\\dfrac{65}{3}\\ \\text{（錯）};\\quad (5)\\ |\\vec{BC}|=\\dfrac{\\sqrt{58}}{3}<\\dfrac{8}{3}\\ \\text{（對）}"}, {"type": "text", "c": "故選 (1)(5)。"}]}, {"subject": "A", "year": "115", "num": 11, "type": "多選", "rate": "33%（全對率 12%）", "img": "img/115_q11.png", "answer": [{"t": "(2)(4)"}], "key": "cos 圖形週期是 4、左右對稱；而且不管 m 是多少，直線都通過 (0,1)——它一定是交點。", "kaodian": [{"unit": "三角", "title": "考點4 三角函數圖形：週期、對稱與疊合", "url": "../concept-map/115學測數學_三角.html#kp4"}, {"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "Γ:y=cos((π/2)x) 週期為 4。直線 y=mx+1 通過 (0,1)，而 Γ 在 x=0 也等於 1，所以 (0,1) 永遠是交點。"}, {"type": "text", "c": "(1) (0,1) 是交點，但它的 x=0 不是負的 → 錯。"}, {"type": "text", "c": "(2) cos 是偶函數，圖形左右對稱；若 (a,b) 是交點，鏡射到 (-a,b) 就是 L₋ₘ 的交點 → 對。"}, {"type": "math", "c": "(3)\\ x=\\tfrac{20}{3}\\ \\text{代入}:\\ \\cos\\tfrac{10\\pi}{3}=-\\tfrac{1}{2}\\neq\\tfrac{1}{2}\\ \\text{（此點不在 }\\Gamma\\text{ 上，錯）}"}, {"type": "math", "c": "(4)\\ \\cos\\tfrac{\\pi x}{2}=-1\\Rightarrow x=4k+2;\\ \\text{又}\\ x=-\\tfrac{2}{m}\\Rightarrow \\tfrac{1}{m}=-(2k+1)\\ \\text{是奇數（對）}"}, {"type": "text", "c": "(5) 舉 m=1：它和 x 軸交點 (-1,0) 確實是交點，但整條線和 Γ 交在 x=-2,-1,0 共 3 個（奇數）→ 錯。"}, {"type": "text", "c": "故選 (2)(4)。（見右圖）"}]}, {"subject": "A", "year": "115", "num": 12, "type": "多選", "rate": "28%（全對率 11%）", "img": "img/115_q12.png", "answer": [{"t": "(2)(4)"}], "key": "三次函數的對稱中心 x 座標＝-（x²係數）/(3×x³係數)；f-g=0 決定交點個數。", "kaodian": [{"unit": "多項式函數", "title": "考點5 三次函數圖形與對稱中心", "url": "../concept-map/115學測數學_多項式函數.html#kp5"}, {"unit": "多項式函數", "title": "考點3 多項式方程式與不等式的解法", "url": "../concept-map/115學測數學_多項式函數.html#kp3"}], "steps": [{"type": "text", "c": "設 f(x)=x³+px²+qx+r，則 g=f-(2x³+2x)=-x³+px²+(q-2)x+r。"}, {"type": "text", "c": "對稱中心的 x 座標：f 是 -p/3，g 是 +p/3（g 的 x³係數是 -1），兩者相加："}, {"type": "math", "c": "a_1+a_2=-\\dfrac{p}{3}+\\dfrac{p}{3}=0\\ \\text{（一定是 0，(2) 對）}"}, {"type": "text", "c": "(1) 交點看 f-g=0：2x³+2x=2x(x²+1)=0 只有 x=0 一個實根 → 只交 1 點 → 錯。"}, {"type": "math", "c": "(3)\\ b_1+b_2=\\dfrac{4p^{3}}{27}-\\dfrac{2p}{3}+2r\\ \\text{（會隨 }p,r\\text{ 改變，不唯一）}\\Rightarrow \\text{錯}"}, {"type": "text", "c": "(4) a₁=a₂ 表示 p=0，此時 b₁=f(0)=r=g(0)=b₂ → 對。"}, {"type": "text", "c": "(5) b₁=b₂ 可化成 p(1-q)=0；只要取 q=1、p≠0，就有 b₁=b₂ 但 a₁≠a₂ → 錯。"}, {"type": "text", "c": "故選 (2)(4)。"}]}, {"subject": "A", "year": "115", "num": 13, "type": "選填", "rate": "73%", "img": "img/115_q13.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{9}{10}"}], "key": "條件機率＝（碩士又通過的機率）÷（全部通過的機率）。", "kaodian": [{"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "../concept-map/115學測數學_排列組合與機率.html#kp4"}], "steps": [{"type": "text", "c": "學士佔 1/4、其中 1/5 通過；碩士佔 3/4、其中 3/5 通過。先算「隨便抽一位會通過」的總機率："}, {"type": "math", "c": "P(\\text{通過})=\\dfrac{1}{4}\\cdot\\dfrac{1}{5}+\\dfrac{3}{4}\\cdot\\dfrac{3}{5}=\\dfrac{1}{20}+\\dfrac{9}{20}=\\dfrac{1}{2}"}, {"type": "text", "c": "題目問「已知這人通過，他是碩士」的機率，用通過中屬於碩士的那部分去除以總通過："}, {"type": "math", "c": "P(\\text{碩}\\mid\\text{通過})=\\dfrac{\\ \\frac{3}{4}\\cdot\\frac{3}{5}\\ }{\\frac{1}{2}}=\\dfrac{9/20}{1/2}=\\dfrac{9}{10}"}, {"type": "text", "c": "答案 9/10。"}]}, {"subject": "A", "year": "115", "num": 14, "type": "選填", "rate": "19%", "img": "img/115_q14.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{1}{4}"}], "key": "向量垂直 → 內積等於 0，先把 a 用 b 表示；再對 a+b 配方求最大。", "kaodian": [{"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}, {"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "../concept-map/115學測數學_多項式函數.html#kp2"}], "steps": [{"type": "text", "c": "直線 y=bx-1 的方向向量是 (1,b)。向量 (a,b) 垂直於它，內積為 0："}, {"type": "math", "c": "(a,b)\\cdot(1,b)=a+b^{2}=0\\ \\Rightarrow\\ a=-b^{2}"}, {"type": "text", "c": "代回 a+b，變成只含 b 的二次式，配方找最大："}, {"type": "math", "c": "a+b=-b^{2}+b=-\\left(b-\\dfrac{1}{2}\\right)^{2}+\\dfrac{1}{4}\\le \\dfrac{1}{4}"}, {"type": "text", "c": "當 b=1/2 時達到最大，a+b 的最大值是 1/4。"}]}, {"subject": "A", "year": "115", "num": 15, "type": "選填", "rate": "31%", "img": "img/115_q15.png", "answer": [{"t": "選填　"}, {"m": "\\dfrac{b}{a}=\\dfrac{3}{2}"}], "key": "a,b,c 等差 → 三點的 x 座標等距；此時「共線」就等於 y 座標也成等差。", "kaodian": [{"unit": "指數與對數", "title": "考點5 指對數的應用：成長衰退模型與數列", "url": "../concept-map/115學測數學_指數與對數.html#kp5"}, {"unit": "數列與級數", "title": "考點1 等差數列：通項、求和與等差中項", "url": "../concept-map/115學測數學_數列與級數.html#kp1"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率（三點共線）", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "因為 a,b,c 等差，x 座標間距 b-a 和 c-b 相等。x 等距時，三點共線 ⟺ y 也成等差："}, {"type": "math", "c": "2\\log(4b)=\\log(3a)+\\log(6c)"}, {"type": "text", "c": "用對數運算（係數變次方、相加變相乘）："}, {"type": "math", "c": "\\log(4b)^{2}=\\log(3a\\cdot 6c)\\Rightarrow 16b^{2}=18ac\\Rightarrow 8b^{2}=9ac"}, {"type": "text", "c": "再代 c=2b-a（等差：a+c=2b），並全部除以 a²："}, {"type": "math", "c": "8\\left(\\tfrac{b}{a}\\right)^{2}-18\\left(\\tfrac{b}{a}\\right)+9=0\\Rightarrow \\tfrac{b}{a}=\\tfrac{3}{2}\\ \\text{或}\\ \\tfrac{3}{4}"}, {"type": "text", "c": "因為 a<b（b/a>1），取 b/a = 3/2。"}]}, {"subject": "A", "year": "115", "num": 16, "type": "選填", "rate": "20%", "img": "img/115_q16.png", "answer": [{"t": "選填　"}, {"m": "\\overline{PQ}=\\dfrac{3\\sqrt{5}}{2}"}], "key": "用兩根寫出拋物線、頂點在直線上定出係數；平移後頂點還在線上且過 B，解出移動量。", "kaodian": [{"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "../concept-map/115學測數學_多項式函數.html#kp2"}, {"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "../concept-map/115學測數學_直線與圓.html#kp2"}], "steps": [{"type": "text", "c": "由與 x 軸交點 ±1/2 寫成 f(x)=k(x²-1/4)。頂點在 x=0，代入直線 y=1+2x 得頂點 y=1："}, {"type": "math", "c": "-\\dfrac{k}{4}=1\\Rightarrow k=-4,\\quad f(x)=-4x^{2}+1,\\ \\ P=(0,1)"}, {"type": "text", "c": "平移後頂點 Q=(h, 1+2h)（還在直線上），圖形 y=-4(x-h)²+(1+2h) 通過 B(1/2, 0)："}, {"type": "math", "c": "4h^{2}-6h=0\\Rightarrow h=0\\,(\\text{就是}P)\\ \\text{或}\\ h=\\tfrac{3}{2}\\Rightarrow Q=\\left(\\tfrac{3}{2},4\\right)"}, {"type": "text", "c": "P、Q 相異取 h=3/2，再用兩點距離："}, {"type": "math", "c": "\\overline{PQ}=\\sqrt{\\left(\\tfrac{3}{2}\\right)^{2}+(4-1)^{2}}=\\sqrt{\\tfrac{45}{4}}=\\dfrac{3\\sqrt{5}}{2}"}]}, {"subject": "A", "year": "115", "num": 17, "type": "選填", "rate": "6%", "img": "img/115_q17.png", "answer": [{"t": "選填　"}, {"m": "k=\\dfrac{3}{11}"}], "key": "先把角關係理清楚，在三角形 BCD 用正弦定理配合 BC=2BD 解出角，再用三倍角算比值。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "../concept-map/115學測數學_三角.html#kp2"}, {"unit": "三角", "title": "考點5 和差角與倍角", "url": "../concept-map/115學測數學_三角.html#kp5"}], "steps": [{"type": "text", "c": "設 ∠ACD=φ，則 ∠BCD=2φ，整個 ∠ACB=3φ。因 ∠A=90°，所以 ∠ABC=90°-3φ。"}, {"type": "text", "c": "在三角形 BCD 中，∠BDC=180°-2φ-(90°-3φ)=90°+φ。對它用正弦定理，並代入 BC=2BD："}, {"type": "math", "c": "\\dfrac{BC}{BD}=\\dfrac{\\sin(90^\\circ+\\varphi)}{\\sin 2\\varphi}=\\dfrac{\\cos\\varphi}{2\\sin\\varphi\\cos\\varphi}=\\dfrac{1}{2\\sin\\varphi}=2\\Rightarrow \\sin\\varphi=\\dfrac{1}{4}"}, {"type": "text", "c": "在直角三角形 ABC 裡令 AC=1，則 AD=tanφ、AB=tan3φ；用三倍角公式算出 tan3φ："}, {"type": "math", "c": "k=\\dfrac{\\overline{AD}}{\\overline{AB}}=\\dfrac{\\tan\\varphi}{\\tan 3\\varphi}=\\dfrac{1/\\sqrt{15}}{\\,11/(3\\sqrt{15})\\,}=\\dfrac{3}{11}"}]}, {"subject": "A", "year": "115", "num": 18, "type": "混合題（單選 3 分）", "rate": "69%", "img": "img/115_q18.png", "answer": [{"t": "(3)　"}, {"m": "5\\sqrt{3}"}], "key": "平行四邊形面積＝兩鄰邊外積向量的長度。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "../concept-map/115學測數學_空間向量.html#kp3"}], "steps": [{"type": "text", "c": "ABCD 以 AB、AD 為兩鄰邊。平行四邊形面積就等於外積 AB×AD 的長度："}, {"type": "math", "c": "[ABCD]=\\left|\\vec{AB}\\times\\vec{AD}\\right|=\\left|(-5,5,5)\\right|=\\sqrt{25+25+25}=\\sqrt{75}=5\\sqrt{3}"}, {"type": "text", "c": "選 (3)。"}], "stem": "img/115_stem.png"}, {"subject": "A", "year": "115", "num": 19, "type": "非選擇題（4 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/115_q19.png", "answer": [{"t": "非選　"}, {"m": "-x+y+z=1"}], "key": "平面 ABCD 的法向量就用 AB×AD；再代入平面上的已知點 B。", "kaodian": [{"unit": "空間向量", "title": "考點4 平面方程式、投影與點到平面距離", "url": "../concept-map/115學測數學_空間向量.html#kp4"}], "steps": [{"type": "text", "c": "ABCD 在同一平面上，它的法向量可取 AB×AD=(-5,5,5)，化簡成 (-1,1,1)。"}, {"type": "text", "c": "平面通過 B(1,2,0)，用「法向量·(位置差)=0」寫式："}, {"type": "math", "c": "-1(x-1)+1(y-2)+1(z-0)=0\\ \\Rightarrow\\ -x+y+z=1"}, {"type": "text", "c": "所以平面 ABCD 的方程式是 -x+y+z=1（也可寫成 x-y-z+1=0）。"}], "stem": "img/115_stem.png"}, {"subject": "A", "year": "115", "num": 20, "type": "非選擇題（8 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/115_q20.png", "answer": [{"t": "非選　體積 "}, {"m": "V=10"}, {"t": "，最長距離 "}, {"m": "\\sqrt{94}"}], "key": "外積必垂直於它的兩個因子 → 反推出 AP 方向；體積=|AP·(AB×AD)|；最遠點一定是某個頂點。", "kaodian": [{"unit": "空間向量", "title": "考點3 外積、面積與體積（行列式）", "url": "../concept-map/115學測數學_空間向量.html#kp3"}, {"unit": "空間向量", "title": "考點1 空間坐標、距離與正立方體", "url": "../concept-map/115學測數學_空間向量.html#kp1"}], "steps": [{"type": "text", "c": "外積一定垂直於相乘的兩個向量，所以 AP 同時垂直於 AD×AP 和 AP×AB。因此 AP 平行於這兩者的外積："}, {"type": "math", "c": "(-2,0,-4)\\times(6,-10,-8)=(-40,-40,20)\\ \\parallel\\ (-2,-2,1)"}, {"type": "text", "c": "(-2,-2,1) 長度為 3，而 |AP|=6，所以 AP=2×(-2,-2,1)=(-4,-4,2)。體積用「AP 與底面外積的內積」："}, {"type": "math", "c": "V=\\left|\\vec{AP}\\cdot(\\vec{AB}\\times\\vec{AD})\\right|=\\left|(-4,-4,2)\\cdot(-5,5,5)\\right|=|20-20+10|=10"}, {"type": "text", "c": "同法解得 AB=(-1,1,-2)、AD=(-2,-3,1)。封閉立體上離 A 最遠的點一定是頂點；各頂點相對 A 是 AB、AD、AP 的 0/1 組合，逐一算長度比較："}, {"type": "math", "c": "\\overline{AB}=\\sqrt{6},\\ \\overline{AD}=\\sqrt{14},\\ |\\vec{AB}+\\vec{AP}|=\\sqrt{34},\\ |\\vec{AB}+\\vec{AD}+\\vec{AP}|=\\sqrt{86},\\ |\\vec{AD}+\\vec{AP}|=\\sqrt{94}"}, {"type": "text", "c": "最大的是 √94（發生在頂點 AD+AP，即圖中的 S 點）。所以體積為 10、六面體上距 A 的最長距離為 √94。"}], "stem": "img/115_stem.png"}, {"subject": "B", "year": "115", "num": 1, "type": "單選", "rate": "52%", "img": "img/115B_q01.png", "answer": [{"t": "(4)　9 個"}], "key": "「誤差百分比小於 5%」就是 |N-95| 小於 95 的 5%，把 N 夾在兩個數之間數整數。", "kaodian": [{"unit": "數與式", "title": "考點2 絕對值的意義、方程式與不等式", "url": "../concept-map/115學測數學_數與式.html#kp2"}, {"unit": "數與式", "title": "考點5 比例、百分率與加權平均（生活應用）", "url": "../concept-map/115學測數學_數與式.html#kp5"}], "steps": [{"type": "text", "c": "把百分比不等式的分母去掉：兩邊同乘 95。"}, {"type": "math", "c": "\\dfrac{|N-95|}{95}\\times100\\%<5\\%\\ \\Rightarrow\\ |N-95|<95\\times0.05=4.75"}, {"type": "text", "c": "絕對值小於 4.75，代表 N 與 95 相差不到 4.75："}, {"type": "math", "c": "95-4.75<N<95+4.75\\ \\Rightarrow\\ 90.25<N<99.75"}, {"type": "text", "c": "中間的整數是 91, 92, …, 99，共 9 個。選 (4)。"}]}, {"subject": "B", "year": "115", "num": 2, "type": "單選", "rate": "46%", "img": "img/115B_q02.png", "answer": [{"t": "(5)"}], "key": "先把 e 的次方單獨留下，再用 ln 兩邊一取，就能把指數拉下來（ln eˣ = x）。", "kaodian": [{"unit": "指數與對數", "title": "考點5 指對數的應用：成長衰退模型與數列", "url": "../concept-map/115學測數學_指數與對數.html#kp5"}, {"unit": "指數與對數", "title": "考點2 對數的定義、運算法則與換底", "url": "../concept-map/115學測數學_指數與對數.html#kp2"}], "steps": [{"type": "text", "c": "兩邊先除以 100，讓 e 的部分單獨留下："}, {"type": "math", "c": "100e^{\\frac{3n}{100}}=135\\ \\Rightarrow\\ e^{\\frac{3n}{100}}=\\dfrac{135}{100}"}, {"type": "text", "c": "指數在 e 上，兩邊取自然對數 ln，指數就被拉下來："}, {"type": "math", "c": "\\dfrac{3n}{100}=\\ln\\!\\left(\\dfrac{135}{100}\\right)"}, {"type": "text", "c": "最後把係數 3/100 移到右邊（乘 100/3）："}, {"type": "math", "c": "n=\\dfrac{100}{3}\\ln\\!\\left(\\dfrac{135}{100}\\right)"}, {"type": "text", "c": "選 (5)。"}]}, {"subject": "B", "year": "115", "num": 3, "type": "單選", "rate": "62%", "img": "img/115B_q03.png", "answer": [{"t": "(2)"}], "key": "反方陣就是把「A 把誰變成誰」倒過來讀：A⁻¹ 會把結果變回原本的向量。", "kaodian": [{"unit": "矩陣", "title": "考點3 反方陣與解矩陣方程式", "url": "../concept-map/115學測數學_矩陣.html#kp3"}], "steps": [{"type": "text", "c": "題目說 A 把 (1,1) 變成 (0,1)、把 (1,-1) 變成 (1,0)。反方陣 A⁻¹ 就是把這兩件事倒過來："}, {"type": "math", "c": "A^{-1}\\begin{bmatrix}0\\\\1\\end{bmatrix}=\\begin{bmatrix}1\\\\1\\end{bmatrix},\\qquad A^{-1}\\begin{bmatrix}1\\\\0\\end{bmatrix}=\\begin{bmatrix}1\\\\-1\\end{bmatrix}"}, {"type": "text", "c": "A⁻¹ 乘 (1,0) 剛好取出 A⁻¹ 的第一行 =(1,-1)；乘 (0,1) 取出第二行 =(1,1)。拼起來："}, {"type": "math", "c": "A^{-1}=\\begin{bmatrix}1 & 1\\\\ -1 & 1\\end{bmatrix}"}, {"type": "text", "c": "選 (2)。"}]}, {"subject": "B", "year": "115", "num": 4, "type": "單選", "rate": "44%", "img": "img/115B_q04.png", "answer": [{"t": "(3)　東經 150 度"}], "key": "兩船同速、同時間，走的距離相等；北緯 60° 的緯線圈半徑只有赤道的 cos60°=½，同樣里程對應的經度要加倍。", "kaodian": [{"unit": "三角", "title": "考點1 三角比、弧度與廣義角", "url": "../concept-map/115學測數學_三角.html#kp1"}], "steps": [{"type": "text", "c": "甲在北緯 60° 向西：從西經 169° 往西過 180°，到東經 171°，經度共轉了"}, {"type": "math", "c": "(180^\\circ-169^\\circ)+(180^\\circ-171^\\circ)=11^\\circ+9^\\circ=20^\\circ"}, {"type": "text", "c": "但北緯 60° 的緯線圈半徑是赤道的 cos60°=½，甲實際走的弧長 =（緯線圈半徑）×（角度）："}, {"type": "math", "c": "\\text{甲的弧長}=R\\cos60^\\circ\\times20^\\circ=\\dfrac{R}{2}\\times20^\\circ=R\\times10^\\circ"}, {"type": "text", "c": "乙在赤道（半徑 R）同速、同時間，弧長一樣，換算成乙轉的經度："}, {"type": "math", "c": "R\\times(\\text{乙的經度差})=R\\times10^\\circ\\ \\Rightarrow\\ \\text{乙轉了}10^\\circ"}, {"type": "text", "c": "乙從東經 140° 向東走 10° → 東經 150°。選 (3)。"}]}, {"subject": "B", "year": "115", "num": 5, "type": "單選", "rate": "58%", "img": "img/115B_q05.png", "answer": [{"t": "(3)　"}, {"m": "\\dfrac{3^{6}}{2^{9}}N"}], "key": "每次先把前一次投注金額乘 3/2 當「預定金額」，若超過 2N 就再砍半才投注——投注金額會交替乘 3/2、乘 3/4。", "kaodian": [{"unit": "數列與級數", "title": "考點2 等比數列：通項、求和與等比中項", "url": "../concept-map/115學測數學_數列與級數.html#kp2"}, {"unit": "數列與級數", "title": "考點3 遞迴數列：構造等比與數學歸納法", "url": "../concept-map/115學測數學_數列與級數.html#kp3"}], "steps": [{"type": "text", "c": "逐次算：預定金額 = 前次投注 ×3/2；若 >2N 就再 ÷2 才投注。"}, {"type": "math", "c": "N\\to\\tfrac32N\\to\\tfrac98N\\to\\tfrac{27}{16}N\\to\\tfrac{81}{64}N\\to\\tfrac{243}{128}N\\to\\tfrac{729}{512}N"}, {"type": "text", "c": "看出規律：投注金額交替「×3/2」「×3/4」。第七次是從 N 連乘三次 3/2、三次 3/4："}, {"type": "math", "c": "a_7=N\\left(\\tfrac32\\right)^{3}\\left(\\tfrac34\\right)^{3}=N\\cdot\\dfrac{27}{8}\\cdot\\dfrac{27}{64}=\\dfrac{3^{6}}{2^{9}}N"}, {"type": "text", "c": "選 (3)。"}]}, {"subject": "B", "year": "115", "num": 6, "type": "單選", "rate": "38%", "img": "img/115B_q06.png", "answer": [{"t": "(1)　4x+3y+48=0"}], "key": "領海是基線 L 外側「寬 12 浬」的帶；先看內側點 (5,5) 在 L 哪一邊，領海在另一邊，再找與 L 平行、距離 12 的直線。", "kaodian": [{"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "領海基線 L：4x+3y-12=0。先看內側點 (5,5) 落在哪一邊："}, {"type": "math", "c": "4(5)+3(5)-12=23>0"}, {"type": "text", "c": "所以「內側」是 4x+3y-12>0，領海（外側）在 4x+3y-12<0 那邊。與 L 平行的直線寫成 4x+3y+k=0，到 L 的距離："}, {"type": "math", "c": "\\dfrac{|k-(-12)|}{\\sqrt{4^2+3^2}}=\\dfrac{|k+12|}{5}=12\\ \\Rightarrow\\ |k+12|=60"}, {"type": "text", "c": "得 k=48 或 k=-72。領海在外側（4x+3y 較小那邊），取 k=48，直線為 4x+3y+48=0。選 (1)。"}]}, {"subject": "B", "year": "115", "num": 7, "type": "單選", "rate": "37%", "img": "img/115B_q07.png", "answer": [{"t": "(2)　"}, {"m": "\\dfrac{17}{18}"}], "key": "p 與 q 相除時，共同的交集機率會約掉，直接得 p/q = P(至少兩個中獎) ÷ P(A 中獎)。", "kaodian": [{"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "../concept-map/115學測數學_排列組合與機率.html#kp4"}, {"unit": "排列組合與機率", "title": "考點5 獨立事件與餘事件", "url": "../concept-map/115學測數學_排列組合與機率.html#kp5"}], "steps": [{"type": "text", "c": "設 W =「至少兩個福袋中獎」。依條件機率定義："}, {"type": "math", "c": "p=P(W\\mid A)=\\dfrac{P(W\\cap A)}{P(A)},\\qquad q=P(A\\mid W)=\\dfrac{P(A\\cap W)}{P(W)}"}, {"type": "text", "c": "相除時 P(W∩A)=P(A∩W) 剛好約掉："}, {"type": "math", "c": "\\dfrac{p}{q}=\\dfrac{P(W)}{P(A)}"}, {"type": "text", "c": "三袋中獎機率 3/4、2/3、1/2 且獨立。至少兩個中獎 =（恰兩個）+（全部三個）："}, {"type": "math", "c": "P(W)=\\underbrace{\\tfrac34\\tfrac23\\tfrac12}_{\\text{全中}}+\\underbrace{\\tfrac34\\tfrac23\\tfrac12}_{AB}+\\underbrace{\\tfrac34\\tfrac13\\tfrac12}_{AC}+\\underbrace{\\tfrac14\\tfrac23\\tfrac12}_{BC}=\\dfrac{17}{24}"}, {"type": "text", "c": "而 P(A)=3/4=18/24，所以"}, {"type": "math", "c": "\\dfrac{p}{q}=\\dfrac{17/24}{18/24}=\\dfrac{17}{18}"}, {"type": "text", "c": "選 (2)。"}]}, {"subject": "B", "year": "115", "num": 8, "type": "多選", "rate": "32%（全對率 12%）", "img": "img/115B_q08.png", "answer": [{"t": "(3)(5)"}], "key": "用「加 π 會變號」sin(θ+π)=-sinθ 把原式化簡成 -3sin(πx/5)+3，再逐一比對。", "kaodian": [{"unit": "三角", "title": "考點4 三角函數圖形：週期、對稱與疊合", "url": "../concept-map/115學測數學_三角.html#kp4"}], "steps": [{"type": "text", "c": "原函數化簡："}, {"type": "math", "c": "y=3\\sin\\!\\left(\\tfrac{\\pi}{5}x+\\pi\\right)+3=-3\\sin\\!\\left(\\tfrac{\\pi}{5}x\\right)+3"}, {"type": "text", "c": "(3)：sin(πx/5-π) 也等於 -sin(πx/5)，整條一樣 → 正確。"}, {"type": "text", "c": "(5)：-3sin(πx/5)+3，和化簡結果一字不差 → 正確。"}, {"type": "text", "c": "(1) 振幅變 6、(2) 頻率被改、(4) 常數變 -3，皆不同。答 (3)(5)。"}]}, {"subject": "B", "year": "115", "num": 9, "type": "多選", "rate": "35%（全對率 16%）", "img": "img/115B_q09.png", "answer": [{"t": "(2)(4)"}], "key": "令 u=x-2 展開最省事：(2-x)²=u²，整個式子變成 u 的多項式，一次看清餘式、係數與正負。", "kaodian": [{"unit": "多項式函數", "title": "考點1 多項式除法、餘式定理與因式定理", "url": "../concept-map/115學測數學_多項式函數.html#kp1"}, {"unit": "多項式函數", "title": "考點3 多項式方程式與不等式的解法", "url": "../concept-map/115學測數學_多項式函數.html#kp3"}], "steps": [{"type": "text", "c": "令 u=x-2（x=u+2）：1-x=-(u+1)、2-x=-u、4+x=u+6，代入："}, {"type": "math", "c": "f=(1-x)(2-x)^2(4+x)=-(u+1)\\,u^2\\,(u+6)=-u^4-7u^3-6u^2"}, {"type": "text", "c": "(2)：對照 a(x-2)⁴+b(x-2)³+c(x-2)²，得 c=-6 → 正確。"}, {"type": "text", "c": "(1)：f=(2-x)·[(1-x)(2-x)(4+x)]，剛好整除，餘式是 0，不是 -x+2 → 錯。"}, {"type": "text", "c": "(3)：(2-x)²≥0，正負看 (1-x)(4+x)，它 >0 的範圍是 (-4,1) 不是 (-4,2) → 錯。"}, {"type": "text", "c": "(4)(5)：f(2026)、f(-2022) 都是負數，比值"}, {"type": "math", "c": "\\dfrac{f(2026)}{f(-2022)}=\\dfrac{2025\\cdot2030}{2023\\cdot2018}>1"}, {"type": "text", "c": "故 (4) 正確；兩者皆負而比值>1，表示 f(2026) 更小，即 f(2026)<f(-2022)，(5) 錯。答 (2)(4)。"}]}, {"subject": "B", "year": "115", "num": 10, "type": "多選", "rate": "35%（全對率 17%）", "img": "img/115B_q10.png", "answer": [{"t": "(1)(4)"}], "key": "「乘 0.5」是線性變換：標準差跟著乘 0.5、相關係數不變；迴歸直線一定通過（平均, 平均）。", "kaodian": [{"unit": "數據分析", "title": "考點1 一維數據：平均、中位數與標準差", "url": "../concept-map/115學測數學_數據分析.html#kp1"}, {"unit": "數據分析", "title": "考點2 相關係數 r", "url": "../concept-map/115學測數學_數據分析.html#kp2"}, {"unit": "數據分析", "title": "考點3 迴歸直線（最適直線）", "url": "../concept-map/115學測數學_數據分析.html#kp3"}], "steps": [{"type": "text", "c": "身長：平均 65、變異數 100（標準差 10）；A 濃度：平均 50、變異數 225（標準差 15）；相關係數 0.75。B=0.5A。"}, {"type": "text", "c": "(1)：B 標準差 = 0.5×(A 標準差)=0.5×15=15/2 → 正確。"}, {"type": "text", "c": "(4)：用「A 對身長」的迴歸直線一定過 (身長平均, A平均)=(65,50)；身長=65 剛好是平均，預測 A=50 → 正確。"}, {"type": "text", "c": "(3)：B=0.5A 是正倍數變換，與 A 的相關係數是 +1，不是 0.5 → 錯。"}, {"type": "text", "c": "(2)：身長中位數 65 推不出 A（不同變數）的中位數，更推不出 B 的 → 錯。"}, {"type": "text", "c": "(5)：B 對身長的迴歸斜率 = 0.5×(A 對身長斜率)=0.5×(0.75×15/10)=9/16≠1/2 → 錯。答 (1)(4)。"}]}, {"subject": "B", "year": "115", "num": 11, "type": "多選", "rate": "26%（全對率 10%）", "img": "img/115B_q11.png", "answer": [{"t": "(2)(5)"}], "key": "兩燈罩共頂點、同軸、同地面，差別只在「圓錐張開角」；張角越大，地面截痕依序是橢圓→拋物線→雙曲線。大燈罩 Γ 張角比小燈罩 γ 大。", "kaodian": [], "steps": [{"type": "text", "c": "光線是以燈源為頂點的圓錐面，兩燈罩軸線相同、地面固定，唯一差別是圓錐張開角。"}, {"type": "text", "c": "平面（地面）切圓錐，隨張角由小到大，截痕依序為：橢圓 → 拋物線 → 雙曲線。"}, {"type": "text", "c": "大燈罩範圍較大 → 張角較大，所以 Γ（大）比 γ（小）「更靠後一階」。"}, {"type": "text", "c": "(2)：Γ 是拋物線（大剛好臨界），γ 張角更小 → 橢圓 → 正確。"}, {"type": "text", "c": "(5)：γ 是雙曲線（小已過臨界），Γ 張角更大 → 也是雙曲線 → 正確。"}, {"type": "text", "c": "(1)(3)(4) 方向都相反，錯。答 (2)(5)。"}]}, {"subject": "B", "year": "115", "num": 12, "type": "多選", "rate": "27%（全對率 8%）", "img": "img/115B_q12.png", "answer": [{"t": "(1)(3)(4)"}], "key": "列出「A 瓶糖量」的遞迴 aₙ=¼aₙ₋₁+50；糖總量守恆=100，配不動點 200/3 判斷長期趨勢。", "kaodian": [{"unit": "數列與級數", "title": "考點3 遞迴數列：構造等比與數學歸納法", "url": "../concept-map/115學測數學_數列與級數.html#kp3"}], "steps": [{"type": "text", "c": "一次稀釋：A(1000mL,糖 aₙ₋₁) 倒 500mL 到 B、再從 B 倒 500mL 回 A。追蹤糖量得遞迴："}, {"type": "math", "c": "a_n=\\dfrac14\\,a_{n-1}+50\\qquad(a_0=100)"}, {"type": "text", "c": "(1)：a₁=¼(100)+50=75 → 正確。"}, {"type": "text", "c": "(3)：倒出後 A 剩 ½aₙ，B 端糖為 100-½aₙ，再回收一半："}, {"type": "math", "c": "a_{n+1}=\\tfrac12 a_n+\\tfrac12\\!\\left(100-\\tfrac12 a_n\\right)=\\tfrac14 a_n+50\\ \\checkmark"}, {"type": "text", "c": "(4)：不動點 c 滿足 c=¼c+50 → c=200/3，則 ⟨aₙ-200/3⟩ 是公比 ¼ 的等比 → 正確。"}, {"type": "text", "c": "(2)：B 瓶糖量 = 100-aₙ（守恆），不是 50-½aₙ → 錯。"}, {"type": "text", "c": "(5)：aₙ=200/3+(100/3)(¼)ⁿ，第 100 次仍 ≈66.7>60 → 錯。答 (1)(3)(4)。"}]}, {"subject": "B", "year": "115", "num": 13, "type": "選填", "rate": "29%", "img": "img/115B_q13.png", "answer": [{"t": "14"}], "key": "兩直線交點與 O、(-20,0) 構成三角形，先用斜角求三個內角，再用正弦定理算 OP。", "kaodian": [{"unit": "三角", "title": "考點2 正弦定理與餘弦定理", "url": "../concept-map/115學測數學_三角.html#kp2"}, {"unit": "直線與圓", "title": "考點1 直線方程式、斜率與角平分線", "url": "../concept-map/115學測數學_直線與圓.html#kp1"}], "steps": [{"type": "text", "c": "L₁ 過 O、斜角 75°；L₂ 過 A(-20,0)、斜角 30°。交點 P 與 O、A 成三角形，底 AO=20。"}, {"type": "text", "c": "內角：A 處 = 30°；O 處，L₁ 朝右上 75°、O→A 朝左(180°)，夾角 = 180°-75°=105°；故 P 處 = 180°-30°-105°=45°。"}, {"type": "text", "c": "用正弦定理（OP 對 A 角、AO 對 P 角）："}, {"type": "math", "c": "\\dfrac{OP}{\\sin30^\\circ}=\\dfrac{AO}{\\sin45^\\circ}\\ \\Rightarrow\\ OP=20\\cdot\\dfrac{\\sin30^\\circ}{\\sin45^\\circ}=\\dfrac{20\\cdot\\frac12}{\\frac{\\sqrt2}{2}}=10\\sqrt2"}, {"type": "math", "c": "10\\sqrt2\\approx14.14\\ \\xrightarrow{\\text{四捨五入}}\\ 14"}, {"type": "text", "c": "答 14。"}]}, {"subject": "B", "year": "115", "num": 14, "type": "選填", "rate": "36%", "img": "img/115B_q14.png", "answer": [{"t": "96"}], "key": "5,6 相鄰又 6,7 相鄰 → 6 一定夾在 5、7 中間，把 {5,6,7} 綁成一塊；{3,4} 也綁一塊，再整體排列。", "kaodian": [{"unit": "排列組合與機率", "title": "考點1 計數原理與排列（有順序）", "url": "../concept-map/115學測數學_排列組合與機率.html#kp1"}], "steps": [{"type": "text", "c": "5,6 相鄰且 6,7 相鄰，所以 6 在 5、7 中間，{5,6,7} 綁成一塊，內部只有 567、765 兩種。"}, {"type": "text", "c": "{3,4} 綁成一塊，內部 34、43 兩種。"}, {"type": "text", "c": "要排的是 [567塊]、[34塊]、1、2 共 4 個，排列 4!："}, {"type": "math", "c": "4!\\times2\\times2=24\\times4=96"}, {"type": "text", "c": "答 96。"}]}, {"subject": "B", "year": "115", "num": 15, "type": "選填", "rate": "24%", "img": "img/115B_q15.png", "answer": [{"m": "\\dfrac{1}{3}<p<\\dfrac{5}{12}"}], "key": "設 a =「有近視且有蛀牙」的比例，用列聯表把每格用 a 表示；兩句「占少數／占多數」給出 a 的範圍，再換成 p。", "kaodian": [{"unit": "排列組合與機率", "title": "考點4 條件機率與貝氏定理", "url": "../concept-map/115學測數學_排列組合與機率.html#kp4"}, {"unit": "數據分析", "title": "考點4 加權平均、中位數與資料判讀", "url": "../concept-map/115學測數學_數據分析.html#kp4"}], "steps": [{"type": "text", "c": "設 a = 有近視且有蛀牙的比例。由邊際總和：有近視∩無蛀牙 =½-a、有蛀牙∩無近視 =⅓-a；p（無近視無蛀牙）由無蛀牙列合 ⅔ 得："}, {"type": "math", "c": "p=\\dfrac23-\\left(\\dfrac12-a\\right)=a+\\dfrac16"}, {"type": "text", "c": "① 有近視的人中，有蛀牙占少數：a÷½ <½ → a<¼。"}, {"type": "text", "c": "② 有蛀牙的人中，有近視占多數：a÷⅓ >½ → a>⅙。"}, {"type": "math", "c": "\\dfrac16<a<\\dfrac14\\ \\Rightarrow\\ \\dfrac16+\\dfrac16<p<\\dfrac16+\\dfrac14\\ \\Rightarrow\\ \\dfrac13<p<\\dfrac{5}{12}"}, {"type": "text", "c": "答 1/3 < p < 5/12。"}]}, {"subject": "B", "year": "115", "num": 16, "type": "選填", "rate": "22%", "img": "img/115B_q16.png", "answer": [{"m": "\\dfrac{4}{3}"}], "key": "g(x)-f(x) 是拋物線，在兩交點 x=1,5 為 0，可寫成 k(x-1)(x-5)；用點 (2,2) 與直線 f 求 k，再取頂點得最大值。", "kaodian": [{"unit": "多項式函數", "title": "考點2 二次函數：判別式、頂點與配方", "url": "../concept-map/115學測數學_多項式函數.html#kp2"}], "steps": [{"type": "text", "c": "L 與 Γ 交於 x=1、5，故 g(x)-f(x) 在 x=1,5 皆為 0，可寫成："}, {"type": "math", "c": "g(x)-f(x)=k(x-1)(x-5)"}, {"type": "text", "c": "一次函數 f 過 (1,0)、(5,4)，斜率 =1，故 f(x)=x-1，f(2)=1；又 (2,2) 在 Γ 上，g(2)=2："}, {"type": "math", "c": "g(2)-f(2)=2-1=1=k(2-1)(2-5)=-3k\\ \\Rightarrow\\ k=-\\dfrac13"}, {"type": "text", "c": "k<0 開口向下，頂點在 x=3 取最大："}, {"type": "math", "c": "\\left.g(x)-f(x)\\right|_{x=3}=-\\dfrac13(3-1)(3-5)=\\dfrac43"}, {"type": "text", "c": "答 4/3。"}]}, {"subject": "B", "year": "115", "num": 17, "type": "選填", "rate": "3%", "img": "img/115B_q17.png", "answer": [{"m": "\\dfrac{23}{5}"}], "key": "透視把每個空間點畫成「前平面影像 A」與「消失點 VP」連線上的分點，比例看深度 y；先用已知點定出深度常數，再套到目標點。", "kaodian": [{"unit": "平面向量", "title": "考點2 線性組合、分點與面積比", "url": "../concept-map/115學測數學_平面向量.html#kp2"}], "steps": [{"type": "text", "c": "前平面（y=0）的影像：點 (x,0,z) 畫成 (x,z)。如 (0,0,0)→(0,0)、(3,0,3)→(3,3)。"}, {"type": "text", "c": "深度 y 越大，影像沿「A 到消失點 VP=(0,15)」這條直線滑動，分割比例 t=y/(y+d)："}, {"type": "math", "c": "\\text{影像}=A+t\\,(VP-A),\\qquad t=\\dfrac{y}{y+d}"}, {"type": "text", "c": "用 (3,4,0)→(13/5,2)：A=(3,0)，影像 =(3-3t, 15t)。由 15t=2 得 t=2/15，再由 t=4/(4+d)=2/15 解出 d=26。"}, {"type": "text", "c": "目標 (3,4,3)：A=(3,3)，y=4 → t=2/15，求 y 坐標："}, {"type": "math", "c": "v=3+t\\,(15-3)=3+\\dfrac{2}{15}\\times12=3+\\dfrac{8}{5}=\\dfrac{23}{5}"}, {"type": "text", "c": "答 23/5。"}]}, {"subject": "B", "year": "115", "num": 18, "type": "混合題（單選 3 分）", "rate": "68%", "img": "img/115B_q18.png", "answer": [{"t": "(1)　x=4"}], "key": "起點 (8,0)、終點 (0,0) 在同一水平線上，中垂線是通過中點且鉛直的線。", "kaodian": [{"unit": "直線與圓", "title": "考點2 兩點距離、中點與三角形", "url": "../concept-map/115學測數學_直線與圓.html#kp2"}], "steps": [{"type": "text", "c": "起點 (8,0)、終點 (0,0) 都在 x 軸上，線段中點 =(4,0)，線段本身水平。"}, {"type": "text", "c": "中垂線通過中點且與線段垂直（鉛直），即 x=4。選 (1)。"}], "stem": "img/115B_stem.png"}, {"subject": "B", "year": "115", "num": 19, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/115B_q19.png", "answer": [{"m": "(x-4)^2+(y+4)^2=32"}], "key": "圓心 P（北極星）到起點、終點等距 → P 在中垂線 x=4 上；再用「轉 90°」的垂直條件定出 P，寫出圓方程式。", "kaodian": [{"unit": "直線與圓", "title": "考點3 圓方程式與點的位置", "url": "../concept-map/115學測數學_直線與圓.html#kp3"}, {"unit": "平面向量", "title": "考點3 內積：夾角、垂直與正射影", "url": "../concept-map/115學測數學_平面向量.html#kp3"}], "steps": [{"type": "text", "c": "甲星繞 P 轉 90°，起點 (8,0)、終點 (0,0)。P 是圓心 → 到兩點等距 → P 在中垂線 x=4 上，設 P=(4,t)。"}, {"type": "text", "c": "「轉 90°」表示 P→起點 與 P→終點 互相垂直，內積 = 0："}, {"type": "math", "c": "(4,-t)\\cdot(-4,-t)=-16+t^2=0\\ \\Rightarrow\\ t=\\pm4"}, {"type": "text", "c": "由圖（圓心在 x 軸下方）取 t=-4，得 P=(4,-4)。驗證代入 L：y=x-8 → -4=4-8 ✓，故 P 在 L 上。"}, {"type": "text", "c": "半徑² =(4-0)²+(-4-0)²=32，圓方程式："}, {"type": "math", "c": "(x-4)^2+(y+4)^2=32"}], "stem": "img/115B_stem.png"}, {"subject": "B", "year": "115", "num": 20, "type": "非選擇題（6 分）", "rate": "非選擇題（大考中心未列答對率）", "img": "img/115B_q20.png", "answer": [{"t": "向量 PR ="}, {"m": "(-12,-2)"}, {"t": "，R=(-8,-6)"}], "key": "乙星也繞 P 逆時針轉 90°：先求向量 P→Q，套「逆時針 90°：(x,y)→(-y,x)」得 PR，再加回 P 得 R。", "kaodian": [{"unit": "平面向量", "title": "考點5 向量的旋轉與坐標應用", "url": "../concept-map/115學測數學_平面向量.html#kp5"}], "steps": [{"type": "text", "c": "乙星繞 P=(4,-4) 逆時針轉 90°，起點 Q=(2,8)。先求 P→Q："}, {"type": "math", "c": "\\overrightarrow{PQ}=(2-4,\\;8-(-4))=(-2,\\,12)"}, {"type": "text", "c": "逆時針轉 90° 的規則 (x,y)→(-y,x)："}, {"type": "math", "c": "\\overrightarrow{PR}=(-12,\\,-2)"}, {"type": "text", "c": "終點 R = P + 向量 PR："}, {"type": "math", "c": "R=(4+(-12),\\ -4+(-2))=(-8,\\,-6)"}, {"type": "text", "c": "答：向量 PR =(-12,-2)，R=(-8,-6)。"}], "stem": "img/115B_stem.png"}];